/**
 * NE:       İlk açılış karşılaması — program KENDİNİ gösterir: gerçek motorla canlı demo, sonra kart iste.
 * NEDEN:    Arkadaşlar beğenmedi: soğuk "banka seç"; ne/niçin belli değil; güven vermiyor. Mehmet abi'nin
 *           kilit dersi: "güveni YAZIYLA değil programın KENDİSİYLE ver." Bu yüzden yazı-yemin ekranı YOK.
 *           Güven programın davranışında: rakamın hesabı AÇIK (şeffaf matematik), resmî kaynak tıklanır,
 *           "kesinleşmedi" dürüstlüğü, kart adımında numara HİÇ sorulmaz. Program konuşmaz, gösterir.
 * NASIL:    Tek ekran demo (preset sepetler market/akaryakıt/restoran → farklı kart kazanır); "kendi
 *           kartlarımla başla" → App kart-ekleme adımı (onKartaGec). Demo maket DEĞİL: sabit örnek üyelik
 *           üzerinde GERÇEK kararVer koşar; gösterilen +TL motorun birebir değeridir (kırmızı çizgi).
 *           BuyukCevap demo=salt-okunur (aksiyon butonları gizli) ama hesap+kaynak AÇIK (kanıt kalır).
 * YAN ETKİ: Yok — yerel preset state; demo hesabı canlı SAGLIKLI kampanyalardan; ağ/dosya yok.
 */
import { useMemo, useState } from "react";
import { Animated, ImageBackground, ScrollView, StyleSheet, Text, View } from "react-native";
import { kararVer } from "../motor/karar";
import type { KararSatiri, TaslakKampanya } from "../tipler";
import { BuyukCevap } from "./BuyukCevap";
import { Basilabilir } from "./Basilabilir";
import { GuvenSeridi } from "./GuvenSeridi";
import { useGiris } from "../hareket";
import { dokunsalSecim } from "../dokunsal";
import { TEMA } from "../tema";

const PROGRAMLAR = ["Bonus", "World", "Axess", "Maximum", "Bankkart"];

const PRESETLER = [
  { kod: "market", etiket: "Market", magaza: "Migros", sepet: 2500 },
  { kod: "akaryakit", etiket: "Akaryakıt", magaza: "Shell", sepet: 1000 },
  { kod: "restoran", etiket: "Restoran", magaza: "Yemek", sepet: 800 },
] as const;

interface Props {
  /** Canlı sağlıklı kampanyalar — demo kararı GERÇEK motorla bunlardan hesaplanır */
  kampanyalar: TaslakKampanya[];
  hareketAzalt?: boolean;
  /** "Kendi kartlarımla başla" / "Geç" → App kart-ekleme adımına geçer */
  onKartaGec: () => void;
}

export function AcilisKarsilama({ kampanyalar, hareketAzalt = false, onKartaGec }: Props) {
  const [preset, setPreset] = useState<string>("market");

  const secili = PRESETLER.find((p) => p.kod === preset) ?? PRESETLER[0];
  const sonuc: KararSatiri | null = useMemo(() => {
    const havuz = kampanyalar.filter((k) => k.kategori === secili.kod);
    const sonuclar = kararVer(havuz, {
      uyeProgramlar: PROGRAMLAR,
      kategori: secili.kod,
      sepetTL: secili.sepet,
      kesimGunleri: {},
    });
    const s = sonuclar[0];
    if (!s) return null;
    return { ...s, guvenDurumu: s.tip === "vade" ? "informational" : "legacy_pending" } as KararSatiri;
  }, [kampanyalar, secili]);

  return (
    <ScrollView style={s.kap} contentContainerStyle={s.icerik} showsVerticalScrollIndicator={false}>
      {/* Geç — ikna için zorlamayız (sağ üst, sönük) */}
      <View style={s.ustSatir}>
        <Text style={s.ornekRozet}>ÖRNEK · senin kartların değil</Text>
        <Basilabilir onPress={onKartaGec} stil={s.gec} hareketAzalt={hareketAzalt} accessibilityRole="button" accessibilityLabel="Karşılamayı geç, doğrudan kart ekle">
          <Text style={s.gecYazi}>Geç →</Text>
        </Basilabilir>
      </View>

      {/*
       * NE: İlk kurulumun düz metin başlangıcını aynı gerçek-kasa karar sahnesine dönüştürür.
       * NEDEN: Splash'tan sonraki ilk yüz yalnız başlık ve açıklamayla açılıyor; ürünün değerini anlatsa da
       *       duygusal ilk izlenim ve “bunu hemen deneyeyim” isteği yaratmıyordu.
       * NASIL: Metinsiz 21:9 sahneye kısa değer cümlesi bindirilir; örnek hesabın gerçek motoru, kaynakları,
       *       presetleri ve kart kurulum sırası aynen korunur.
       * YAN ETKİ: Yaklaşık 55 KB ortak WebP ilk kurulumda yüklenir; ağ çağrısı veya yeni finansal iddia yoktur.
       */}
      <ImageBackground
        source={require("../../assets/sahneler/karar-ani-v3.webp")}
        style={s.karsilamaHero}
        imageStyle={s.karsilamaHeroGorsel}
        resizeMode="cover"
        accessibilityRole="image"
        accessibilityLabel="Market kasasında üç kart arasından en iyi kartın altın ışıkla seçildiği sahne"
      >
        <View style={s.karsilamaHeroKarartma} />
        <View style={s.karsilamaHeroIcerik}>
          <Text style={s.karsilamaHeroEtiket}>KARTAKIL KARAR ANI</Text>
          <Text style={s.buyukBaslik}>Kasada hangi kart?</Text>
          <Text style={s.degerCumlesi}>Mağazayı ve tutarı söyle; en kazançlı kartını net TL ile gör.</Text>
        </View>
      </ImageBackground>
      <View style={s.magazaSerit}>
        <View>
          <Text style={s.ornekEtiket}>ŞİMDİ GERÇEK BİR ÖRNEK</Text>
          <Text style={s.magazaAd}>{secili.magaza}</Text>
        </View>
        <Text style={s.magazaTutar}>{secili.sepet.toLocaleString("tr-TR")} ₺</Text>
      </View>

      {/* Güven burada, YAZIYLA değil: BuyukCevap hesabı açık gösterir (şeffaf matematik) + resmî
          kaynağı tıklanır kılar + "kesinleşmedi" der (abartmaz). Program kendini gösterir. */}
      {sonuc ? (
        <BuyukCevap satir={sonuc} demo hareketAzalt={hareketAzalt} />
      ) : (
        <Text style={s.bosYazi}>Bu örnekte kampanya bulunamadı — başka sepet dene.</Text>
      )}

      <Text style={s.presetBaslik}>Başka bir sepet dene:</Text>
      <View style={s.presetSatir}>
        {PRESETLER.map((p, i) => (
          <PresetCip
            key={p.kod}
            etiket={`${p.etiket} · ${p.sepet.toLocaleString("tr-TR")}₺`}
            secili={p.kod === preset}
            sira={i}
            hareketAzalt={hareketAzalt}
            onPress={() => {
              dokunsalSecim();
              setPreset(p.kod);
            }}
          />
        ))}
      </View>

      {/* Görünür güven — kart eklemeden ÖNCE en büyük diferansiyatör (davranış-kanıtı, vaaz değil).
          Detay ipucu yok (App modal'ı burada yok); sade rozet şeridi ilk temasın güven mührü. */}
      <GuvenSeridi hareketAzalt={hareketAzalt} />

      <Basilabilir onPress={() => { dokunsalSecim(); onKartaGec(); }} stil={s.anaCta} hareketAzalt={hareketAzalt} accessibilityRole="button" accessibilityLabel="Kendi kartlarımla başla, kart eklemeye geç">
        <Text style={s.anaCtaYazi}>Kendi kartlarımla başla →</Text>
      </Basilabilir>
      <View style={{ height: 28 }} />
    </ScrollView>
  );
}

function PresetCip({ etiket, secili, sira, hareketAzalt, onPress }: { etiket: string; secili: boolean; sira: number; hareketAzalt: boolean; onPress: () => void }) {
  const giris = useGiris(sira, hareketAzalt);
  return (
    <Animated.View style={giris}>
      <Basilabilir onPress={onPress} stil={[s.cip, secili && s.cipSecili]} hareketAzalt={hareketAzalt} accessibilityRole="button" accessibilityState={{ selected: secili }} accessibilityLabel={`${etiket} sepetini dene`}>
        <Text style={[s.cipYazi, secili && s.cipYaziSecili]}>{etiket}</Text>
      </Basilabilir>
    </Animated.View>
  );
}

const s = StyleSheet.create({
  kap: { flex: 1 },
  icerik: { padding: TEMA.bosluk.l, gap: TEMA.bosluk.m },
  ustSatir: { flexDirection: "row", alignItems: "center", justifyContent: "space-between" },
  ornekRozet: {
    color: TEMA.renk.yaziSoluk, fontSize: 11, fontWeight: "700", letterSpacing: 0.5,
    borderWidth: 1, borderColor: TEMA.renk.panelKenar, borderRadius: TEMA.yaricap.hap,
    paddingVertical: 5, paddingHorizontal: 11,
  },
  gec: { paddingVertical: 6, paddingHorizontal: 10 },
  gecYazi: { color: TEMA.renk.yaziSoluk, fontSize: 13, fontWeight: "700" },
  karsilamaHero: {
    height: 190,
    borderRadius: TEMA.yaricap.buyuk,
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    overflow: "hidden",
    justifyContent: "flex-end",
    padding: TEMA.bosluk.l,
  },
  karsilamaHeroGorsel: { borderRadius: TEMA.yaricap.buyuk },
  karsilamaHeroKarartma: {
    position: "absolute",
    top: 0,
    right: 0,
    bottom: 0,
    left: 0,
    backgroundColor: "rgba(7,9,13,0.28)",
  },
  karsilamaHeroIcerik: { maxWidth: "58%" },
  karsilamaHeroEtiket: {
    color: TEMA.renk.altinAcik,
    fontSize: 9.5,
    fontWeight: "900",
    letterSpacing: 1.15,
    marginBottom: 5,
  },
  buyukBaslik: { color: "#fff", fontSize: 24, fontWeight: "900", letterSpacing: -0.4 },
  degerCumlesi: { color: "rgba(255,255,255,0.84)", fontSize: 12, lineHeight: 17, fontWeight: "600", marginTop: 4 },
  magazaSerit: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    paddingVertical: 4,
  },
  ornekEtiket: { color: TEMA.renk.yaziEnSoluk, fontSize: 9, fontWeight: "900", letterSpacing: 0.7, marginBottom: 3 },
  magazaAd: { color: TEMA.renk.yazi, fontSize: 16, fontWeight: "800" },
  magazaTutar: { color: TEMA.renk.altinAcik, fontSize: 17, fontWeight: "900", fontVariant: ["tabular-nums"] },
  bosYazi: { color: TEMA.renk.yaziSoluk, fontSize: 13, paddingVertical: TEMA.bosluk.l, textAlign: "center" },
  presetBaslik: { color: TEMA.renk.yaziSoluk, fontSize: 12.5, fontWeight: "700", marginTop: TEMA.bosluk.s },
  presetSatir: { flexDirection: "row", flexWrap: "wrap", gap: TEMA.bosluk.s },
  cip: {
    borderWidth: 1, borderColor: TEMA.renk.panelKenar, backgroundColor: TEMA.renk.panel,
    borderRadius: TEMA.yaricap.hap, paddingVertical: 9, paddingHorizontal: 14,
  },
  cipSecili: { borderColor: TEMA.renk.altinKenar, backgroundColor: "rgba(212,175,55,0.10)" },
  cipYazi: { color: TEMA.renk.yaziSoluk, fontSize: 13, fontWeight: "700" },
  cipYaziSecili: { color: TEMA.renk.altinAcik },
  anaCta: {
    minHeight: 52, borderRadius: TEMA.yaricap.orta, backgroundColor: TEMA.renk.altin,
    alignItems: "center", justifyContent: "center", marginTop: TEMA.bosluk.m,
  },
  anaCtaYazi: { color: TEMA.renk.zeminKoyu, fontSize: 15.5, fontWeight: "800" },
});
