/**
 * NE:       Cam (glass) yüzey overlay — üst ışık + 1px rim hairline + alt gölge (premium camekan hissi).
 * NEDEN:    Görsel Devrim 2: düz kat1/kat2 panelleri "cam"a çevirir; ad-hoc rgba tekrarı yerine tek primitif.
 * NASIL:    absoluteFill overlay (pointerEvents none) — LinearGradient üst-ışık→transparent→alt-gölge +
 *           üst kenara 1px rim. blur YOK (expo-blur kurulu değil); RN'de standart katmanlı taklit.
 * YAN ETKİ: Yok — saf dekor; dokunmayı yutmaz (pointerEvents none), ebeveyn overflow:hidden ister.
 */
import { StyleSheet, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { TEMA } from "../tema";

export function CamYuzey({ yaricap = TEMA.yaricap.orta }: { yaricap?: number }) {
  return (
    <View
      style={[StyleSheet.absoluteFill, { borderRadius: yaricap, overflow: "hidden" }]}
      pointerEvents="none"
    >
      <LinearGradient
        colors={[TEMA.yuzey.cam.ustIsik, "transparent", TEMA.yuzey.cam.altGolge]}
        locations={[0, 0.45, 1]}
        start={{ x: 0.2, y: 0 }}
        end={{ x: 0.7, y: 1 }}
        style={StyleSheet.absoluteFill}
      />
      <View style={[s.rim, { backgroundColor: TEMA.yuzey.cam.rimUst }]} />
    </View>
  );
}

const s = StyleSheet.create({
  rim: { position: "absolute", top: 0, left: 0, right: 0, height: 1 },
});
