/**
 * NE:       Kazanç Karnesi çekirdeği — kullanılan/kaçırılan kart kararlarının cihaz-içi analizi.
 * NEDEN:    KartAkıl'ın diferansiyatörü: "bu ay kartlarınla ne kazandın, neyi kaçırdın?".
 *           Muadillerinde yok. Ama rakam ŞİŞİRİLMEZ: v1 kullanıcının kendi beyanı (tahmini),
 *           "doğrulandı" iddiası ancak fişle/banka callback'iyle gelir (kırmızı çizgi: sahte rakam yok).
 * NASIL:    Saf fonksiyon, cihazda çalışır (KVKK — konum/finansal veri sunucuya gitmez).
 *           Bozuk/negatif/NaN kazanç, geçersiz gün ve tanınmayan durum ELENİR (sapma-yasak).
 *           Kartlar cardProductName varsa onunla, yoksa program adıyla kırılır; sıralama deterministik.
 * YAN ETKİ: Yok — girdiyi değiştirmez, IO yapmaz.
 */
export type KarneDurumu = "kullanildi" | "kacirildi";

export interface KarneKaydi {
  id: string;
  program: string;
  cardProductName?: string;
  merchant: string;
  kategori: string;
  /** Net TL — v1'de kullanıcının beyanı (tahmini); doğrulanmış değil */
  kazancTL: number;
  /** ISO takvim günü "YYYY-MM-DD" */
  tarih: string;
  durum: KarneDurumu;
}

export interface KartKirilimi {
  ad: string;
  program: string;
  kazanc: number;
  adet: number;
}

export interface KarneOzeti {
  toplamKazanc: number;
  toplamKacan: number;
  kullanilanSayi: number;
  kacirilanSayi: number;
  toplamIsaret: number;
  /** kullanılan / (kullanılan + kaçırılan) × 100 — 0-100 tam sayı; işaret yoksa 0 */
  kullanimOrani: number;
  buAyKazanc: number;
  kartKirilimi: KartKirilimi[];
  sonKayitlar: KarneKaydi[];
}

const ISO_GUN = /^(\d{4})-(\d{2})-(\d{2})$/u;

function gecerliKayit(k: unknown): k is KarneKaydi {
  if (k == null || typeof k !== "object") return false;
  const a = k as Partial<KarneKaydi>;
  return (
    typeof a.id === "string" &&
    typeof a.program === "string" &&
    typeof a.merchant === "string" &&
    typeof a.kategori === "string" &&
    typeof a.tarih === "string" &&
    ISO_GUN.test(a.tarih) &&
    (a.durum === "kullanildi" || a.durum === "kacirildi") &&
    typeof a.kazancTL === "number" &&
    Number.isFinite(a.kazancTL) &&
    a.kazancTL >= 0 &&
    !Object.is(a.kazancTL, -0)
  );
}

/** Bozuk kayıtları eleyip yalnız geçerli olanları döndürür (görsel/hesap katmanı buna güvenir). */
export function gecerliKayitlar(kayitlar: readonly unknown[]): KarneKaydi[] {
  return Array.isArray(kayitlar) ? kayitlar.filter(gecerliKayit) : [];
}

function ayAnahtari(isoGun: string): string {
  const m = ISO_GUN.exec(isoGun);
  return m ? `${m[1]}-${m[2]}` : "";
}

function kartAdi(k: KarneKaydi): string {
  return k.cardProductName?.trim() || k.program;
}

export function karneOzetiOlustur(kayitlar: readonly unknown[], bugunISO: string): KarneOzeti {
  const gecerli = gecerliKayitlar(kayitlar);
  const buAy = ayAnahtari(bugunISO);

  let toplamKazanc = 0;
  let toplamKacan = 0;
  let kullanilanSayi = 0;
  let kacirilanSayi = 0;
  let buAyKazanc = 0;
  const kirilimHarita = new Map<string, KartKirilimi>();

  for (const k of gecerli) {
    if (k.durum === "kullanildi") {
      toplamKazanc += k.kazancTL;
      kullanilanSayi += 1;
      if (buAy && ayAnahtari(k.tarih) === buAy) buAyKazanc += k.kazancTL;

      const ad = kartAdi(k);
      const anahtar = `${k.program}␟${ad}`;
      const mevcut = kirilimHarita.get(anahtar);
      if (mevcut) {
        mevcut.kazanc += k.kazancTL;
        mevcut.adet += 1;
      } else {
        kirilimHarita.set(anahtar, { ad, program: k.program, kazanc: k.kazancTL, adet: 1 });
      }
    } else {
      toplamKacan += k.kazancTL;
      kacirilanSayi += 1;
    }
  }

  const toplamIsaret = kullanilanSayi + kacirilanSayi;
  const kullanimOrani = toplamIsaret > 0 ? Math.round((kullanilanSayi / toplamIsaret) * 100) : 0;

  const kartKirilimi = [...kirilimHarita.values()].sort(
    (a, b) => b.kazanc - a.kazanc || a.ad.localeCompare(b.ad, "tr-TR")
  );

  // En yeni önce; aynı günde id ile deterministik
  const sonKayitlar = [...gecerli].sort(
    (a, b) => (a.tarih < b.tarih ? 1 : a.tarih > b.tarih ? -1 : a.id.localeCompare(b.id))
  );

  return {
    toplamKazanc,
    toplamKacan,
    kullanilanSayi,
    kacirilanSayi,
    toplamIsaret,
    kullanimOrani,
    buAyKazanc,
    kartKirilimi,
    sonKayitlar,
  };
}
