/// <reference types="google.maps" />

/**
 * NE:       Web/PWA'da kullanıcı ile en yakın altı mağazayı gerçek Google yol haritasında gösterir.
 * NEDEN:    Web kullanıcıları da native cihazlarla aynı gerçek mevki ve numaralı mağaza ayrımını uygulama içinde görmelidir.
 * NASIL:    Resmî @googlemaps/js-api-loader ile Maps JavaScript API'yi ihtiyaç anında yükler; standart yol haritasına
 *           kullanıcı ve listeyle eşleşen 1–6 marka renkli işaret ekler, gerçek sınırları tüm noktaları kapsayacak şekilde ayarlar.
 * YAN ETKİ: Web anahtarı yoksa, yetkisizse veya ağ yüklemesi başarısızsa boş/sahte harita yerine gerçek Maps URL yedeğine
 *           düşer. Başarılı yüklemede görünüm bölgesi Google'a iletilir; KartAkıl konumu saklamaz.
 */
import { useEffect, useMemo, useRef, useState } from "react";
import { ActivityIndicator, StyleSheet, Text, View } from "react-native";
import { importLibrary, setOptions } from "@googlemaps/js-api-loader";
import { magazaRenk } from "../marka/magazaLogolari";
import {
  gercekHaritaKapsamiOlustur,
  type KullaniciKonumu,
} from "../motor/gercekHarita";
import type { YakinMagaza } from "../motor/konum";
import { gercekHaritaAc } from "../veri/haritaKopru";
import { TEMA } from "../tema";
import { Basilabilir } from "./Basilabilir";
import { GercekHaritaYedegi } from "./GercekHaritaYedegi";

type Props = {
  konum: KullaniciKonumu;
  yakinlar: readonly YakinMagaza[];
};

type YuklemeDurumu = "yukleniyor" | "hazir" | "hata";

let ayarliWebAnahtari: string | null = null;

function yukleyiciyiAyarla(anahtar: string): void {
  if (ayarliWebAnahtari === anahtar) return;
  setOptions({
    key: anahtar,
    v: "weekly",
    language: "tr",
    region: "TR",
    authReferrerPolicy: "origin",
  });
  ayarliWebAnahtari = anahtar;
}

export function YakinCevreHaritasi({ konum, yakinlar }: Props) {
  const webAnahtari = (process.env.EXPO_PUBLIC_GOOGLE_MAPS_WEB_KEY ?? "").trim();
  const kapsam = useMemo(
    () => gercekHaritaKapsamiOlustur(konum, yakinlar),
    [konum, yakinlar]
  );
  const haritaElemani = useRef<HTMLElement | null>(null);
  const [durum, setDurum] = useState<YuklemeDurumu>("yukleniyor");

  useEffect(() => {
    if (!webAnahtari || !kapsam || !haritaElemani.current) {
      setDurum("hata");
      return;
    }

    const etkinKapsam = kapsam;
    let iptal = false;
    let harita: google.maps.Map | null = null;
    const isaretler: google.maps.Marker[] = [];
    const pencere = window as typeof window & { gm_authFailure?: () => void };
    const oncekiKimlikHatasi = pencere.gm_authFailure;
    const kimlikHatasi = () => {
      if (!iptal) setDurum("hata");
    };
    pencere.gm_authFailure = kimlikHatasi;

    async function haritayiKur(): Promise<void> {
      try {
        yukleyiciyiAyarla(webAnahtari);
        await Promise.all([importLibrary("maps"), importLibrary("marker")]);
        if (iptal || !haritaElemani.current) return;

        harita = new google.maps.Map(haritaElemani.current, {
          center: { lat: etkinKapsam.merkez.lat, lng: etkinKapsam.merkez.lon },
          zoom: 14,
          mapTypeId: google.maps.MapTypeId.ROADMAP,
          disableDefaultUI: true,
          zoomControl: true,
          clickableIcons: false,
          gestureHandling: "cooperative",
          keyboardShortcuts: true,
        });

        const sinirlar = new google.maps.LatLngBounds();
        sinirlar.extend({ lat: konum.lat, lng: konum.lon });
        isaretler.push(
          new google.maps.Marker({
            map: harita,
            position: { lat: konum.lat, lng: konum.lon },
            title: "Sen buradasın",
            zIndex: 100,
            icon: {
              path: google.maps.SymbolPath.CIRCLE,
              fillColor: "#318ce7",
              fillOpacity: 1,
              strokeColor: "#ffffff",
              strokeWeight: 3,
              scale: 9,
            },
          })
        );

        etkinKapsam.noktalar.forEach((nokta) => {
          const konumNoktasi = { lat: nokta.lat, lng: nokta.lon };
          sinirlar.extend(konumNoktasi);
          isaretler.push(
            new google.maps.Marker({
              map: harita,
              position: konumNoktasi,
              title: `${nokta.sira}. ${nokta.marka} · ${nokta.subeAd}`,
              label: {
                text: String(nokta.sira),
                color: "#ffffff",
                fontSize: "12px",
                fontWeight: "900",
              },
              icon: {
                path: google.maps.SymbolPath.CIRCLE,
                fillColor: magazaRenk(nokta.marka),
                fillOpacity: 1,
                strokeColor: "#ffffff",
                strokeWeight: 2,
                scale: 16,
              },
            })
          );
        });

        harita.fitBounds(sinirlar, 52);
        google.maps.event.addListenerOnce(harita, "idle", () => {
          if (harita && (harita.getZoom() ?? 0) > 16) harita.setZoom(16);
        });
        if (!iptal) setDurum("hazir");
      } catch {
        if (!iptal) setDurum("hata");
      }
    }

    void haritayiKur();
    return () => {
      iptal = true;
      isaretler.forEach((isaret) => isaret.setMap(null));
      if (harita) google.maps.event.clearInstanceListeners(harita);
      if (pencere.gm_authFailure === kimlikHatasi) pencere.gm_authFailure = oncekiKimlikHatasi;
    };
  }, [kapsam, konum.lat, konum.lon, webAnahtari]);

  if (!webAnahtari || !kapsam || durum === "hata") {
    return <GercekHaritaYedegi konum={konum} yakinlar={yakinlar} />;
  }

  return (
    <View style={s.kap}>
      <View style={s.haritaCerçevesi}>
        <View
          ref={(eleman) => {
            haritaElemani.current = eleman as unknown as HTMLElement | null;
          }}
          style={StyleSheet.absoluteFill}
          collapsable={false}
          accessibilityLabel={`Gerçek yakın çevre haritası. Sen ve en yakın ${kapsam.noktalar.length} yer gösteriliyor.`}
        />
        {durum === "yukleniyor" ? (
          <View style={s.yukleniyor}>
            <ActivityIndicator color="#4ba4ff" />
            <Text style={s.yukleniyorYazi}>Gerçek harita hazırlanıyor…</Text>
          </View>
        ) : null}
        <View style={s.ustBilgi} pointerEvents="none">
          <Text style={s.baslik}>Gerçek yakın çevre</Text>
          <Text style={s.alt}>Mavi nokta sensin · 1–{kapsam.noktalar.length} aşağıdaki yerlerle eşleşir</Text>
        </View>
      </View>
      <Basilabilir
        onPress={() => gercekHaritaAc(konum)}
        stil={s.buyut}
        accessibilityRole="link"
        accessibilityLabel="Gerçek haritayı Google Haritalar'da büyüt"
      >
        <Text style={s.buyutYazi}>Haritada büyüt ↗</Text>
      </Basilabilir>
      <Text style={s.gizlilik}>Gerçek Google yol haritası · konumun KartAkıl’da saklanmaz</Text>
    </View>
  );
}

const s = StyleSheet.create({
  kap: {
    borderRadius: TEMA.yaricap.buyuk,
    borderWidth: 1,
    borderColor: "rgba(75,164,255,0.32)",
    backgroundColor: "rgba(16,23,34,0.92)",
    padding: 6,
    gap: 7,
    overflow: "hidden",
  },
  haritaCerçevesi: {
    height: 268,
    borderRadius: 18,
    overflow: "hidden",
    backgroundColor: "#d8dde3",
  },
  ustBilgi: {
    position: "absolute",
    top: 9,
    left: 9,
    right: 9,
    borderRadius: 14,
    borderWidth: 1,
    borderColor: "rgba(255,255,255,0.2)",
    backgroundColor: "rgba(13,17,23,0.88)",
    paddingHorizontal: 12,
    paddingVertical: 9,
  },
  baslik: { color: TEMA.renk.yazi, fontSize: 13, fontWeight: "900" },
  alt: { color: "#c2cad5", fontSize: 9.5, lineHeight: 13, marginTop: 2 },
  yukleniyor: {
    position: "absolute",
    top: 0,
    right: 0,
    bottom: 0,
    left: 0,
    alignItems: "center",
    justifyContent: "center",
    gap: 8,
    backgroundColor: "rgba(216,221,227,0.96)",
  },
  yukleniyorYazi: { color: "#253141", fontSize: 11, fontWeight: "700" },
  buyut: {
    minHeight: 44,
    borderRadius: 14,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: "rgba(75,164,255,0.13)",
    borderWidth: 1,
    borderColor: "rgba(75,164,255,0.36)",
  },
  buyutYazi: { color: "#acd8ff", fontSize: 12, fontWeight: "800" },
  gizlilik: { color: TEMA.renk.yaziEnSoluk, fontSize: 9.5, textAlign: "center", paddingBottom: 3 },
});
