/**
 * NE:       Cihazın yerel gününü ve KartAkıl V3 için Türkiye takvim gününü güvenli biçimde üretir.
 * NEDEN:    UTC tabanlı toISOString, Türkiye'de gece yarısından sonra önceki günü gösterebilir;
 *           donmuş bir değerlendirme anı da açık kalan uygulamada kampanya gününü eskitebilir.
 * NASIL:    Legacy akış için cihaz alanlarını korur; V3 anlarını Europe/Istanbul saat diliminde
 *           YYYY-MM-DD'ye çevirir ve yalnız gün değiştiğinde saf bir yenileme kararı verir.
 * YAN ETKİ: Verilen Date nesneleri değişmez; ağ, dosya veya zamanlayıcı erişimi yapılmaz.
 */
const TURKIYE_GUN_BICIMI = new Intl.DateTimeFormat("en-US", {
  timeZone: "Europe/Istanbul",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
});

export function yerelTakvimTarihi(tarih = new Date()): string {
  const yil = tarih.getFullYear();
  const ay = String(tarih.getMonth() + 1).padStart(2, "0");
  const gun = String(tarih.getDate()).padStart(2, "0");
  return `${yil}-${ay}-${gun}`;
}

export function turkiyeTakvimTarihi(tarih = new Date()): string {
  const parcalar = TURKIYE_GUN_BICIMI.formatToParts(tarih);
  const deger = (tur: Intl.DateTimeFormatPartTypes) =>
    parcalar.find((parca) => parca.type === tur)?.value;
  const yil = deger("year");
  const ay = deger("month");
  const gun = deger("day");
  if (!yil || !ay || !gun) throw new Error("Türkiye takvim günü üretilemedi.");
  return `${yil}-${ay}-${gun}`;
}

export function degerlendirmeAniniYenile(
  oncekiIso: string,
  simdiIso: string,
  zorla = false
): string {
  if (zorla) return simdiIso;
  return turkiyeTakvimTarihi(new Date(oncekiIso)) === turkiyeTakvimTarihi(new Date(simdiIso))
    ? oncekiIso
    : simdiIso;
}
