/**
 * NE:       "Ne alacaksın?" için görsel kategori kartı — kategori sahne görseli + ad + kampanya sayısı.
 * NEDEN:    Mehmet abi: her kategori kendi RESMİYLE görünsün (küçük çizim-ikon yetmiyor). Görsel, kategoriyi
 *           bir bakışta anlatır; kampanya sayısı değeri gösterir. Seçili kart altın konturla ışıkla öne çıkar.
 * NASIL:    KategoriGorsel (assets/kategoriler webp, yoksa premium degrade fallback) cover + alt karartma
 *           scrim + kategori adı + "N kampanya". Basilabilir yay-fizik dokunuş. Görsel yoksa da ASLA boş/çökmez.
 * YAN ETKİ: Yok — saf sunum; onPress üst bileşenin kategori seçimini çağırır.
 */
import { StyleSheet, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { KategoriGorsel } from "./KategoriGorsel";
import { Basilabilir } from "./Basilabilir";
import { TEMA } from "../tema";

export function KategoriKarti({
  kod,
  etiket,
  adet,
  secili = false,
  onPress,
  hareketAzalt = false,
}: {
  kod: string;
  etiket: string;
  adet?: number;
  secili?: boolean;
  onPress: () => void;
  hareketAzalt?: boolean;
}) {
  return (
    <Basilabilir
      stil={[s.kart, secili && s.kartSecili]}
      onPress={onPress}
      hareketAzalt={hareketAzalt}
      accessibilityRole="button"
      accessibilityState={{ selected: secili }}
      accessibilityLabel={`${etiket}${adet ? `, ${adet} kampanya` : ""} — bu alışverişte en kârlı kartı bul`}
    >
      <KategoriGorsel kategori={kod} yukseklik={96} />
      {/* Alt karartma — kategori adı her görselde okunur (koyu/aydınlık farketmez) */}
      <LinearGradient
        colors={["transparent", "rgba(10,12,15,0.35)", "rgba(10,12,15,0.9)"]}
        style={StyleSheet.absoluteFill}
        pointerEvents="none"
      />
      {secili ? <View style={s.secimHare} pointerEvents="none" /> : null}
      <View style={s.icerik} pointerEvents="none">
        <Text style={[s.etiket, secili && s.etiketSecili]} numberOfLines={1}>
          {etiket}
        </Text>
        {adet != null ? <Text style={s.adet}>{adet} kampanya</Text> : null}
      </View>
    </Basilabilir>
  );
}

const s = StyleSheet.create({
  kart: {
    width: "48%",
    height: 96,
    borderRadius: TEMA.yaricap.orta,
    overflow: "hidden",
    borderWidth: 1,
    borderColor: TEMA.yuzey.kat1.kenar,
  },
  // Seçili = altın kontur + ışık (ışıkla hiyerarşi; kanon)
  kartSecili: { borderColor: TEMA.renk.altinKenar, borderWidth: 1.5 },
  secimHare: {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: "rgba(212,175,55,0.12)",
  },
  icerik: { position: "absolute", left: 10, right: 10, bottom: 8 },
  etiket: { color: "#FFFFFF", fontSize: 14, fontWeight: "800", letterSpacing: -0.2 },
  etiketSecili: { color: TEMA.renk.altinAcik },
  adet: { color: "rgba(255,255,255,0.72)", fontSize: 10.5, fontWeight: "600", marginTop: 1 },
});
