/** NFC normalizasyonlu güvenli erişim (İ/ı gibi birleşim farklarına dayanıklı) */
export function magazaLogo(marka: string): ImageSourcePropType | undefined {
  return MAGAZA_LOGO[marka] ?? MAGAZA_LOGO[marka.normalize("NFC")];
}

// Mağaza renk kimliği — çip/rozetin markayla BÜTÜNLEŞMESİ için (Mehmet abi ilkesi:
// logo beyaz kutuya yapıştırılmaz, mağaza kendi rengine bürünür)
const RENK = new Map(
  (magazaRenkVerisi as { ad: string; renk: string }[]).map((m) => [m.ad.normalize("NFC"), m.renk])
);

export function magazaRenk(marka: string): string {
  return RENK.get(marka.normalize("NFC")) ?? "#9ba0aa";
}
