/**
 * NE:       Yakındaki mağaza seçiminin bağımsız, doğrulamalı ve deterministik hesap çekirdeği.
 * NEDEN:    Bozuk paket verisi, NaN koordinat veya eşit uzaklıklar yanlış/sırası değişen öneriler
 *           üretmemeli; hesaplar cihaz API'si yüklenmeden hızlı ve ağsız test edilebilmelidir.
 * NASIL:    Koordinatları gerçek dünya aralıklarında doğrular, geçersiz şubeleri eler, Türkçe/ASCII marka
 *           yazımlarını tek anahtarda toplar ve tüm mesafe eşitliklerini kesin metin sırasıyla çözer.
 * YAN ETKİ: Girdi dizisi ve şube nesneleri değiştirilmez; geçersiz satırlar sonuçtan sessizce elenir.
 */

export interface Sube {
  ad: string;
  marka: string;
  lat: number;
  lon: number;
}

export interface YakinMagaza {
  marka: string;
  subeAd: string;
  mesafeM: number;
  /** Şube koordinatı — yalnız cihazda "yol tarifi" deep-link'i için (sunucuya gitmez). */
  lat: number;
  lon: number;
}

const DUNYA_YARICAPI_METRE = 6_371_000;

export function koordinatGecerliMi(lat: number, lon: number): boolean {
  return (
    Number.isFinite(lat) &&
    Number.isFinite(lon) &&
    lat >= -90 &&
    lat <= 90 &&
    lon >= -180 &&
    lon <= 180
  );
}

export function onPlanKonumIzniIstenmeliMi(granted: boolean, canAskAgain: boolean): boolean {
  return !granted && canAskAgain;
}

function metinTemizle(deger: unknown): string | null {
  if (typeof deger !== "string") return null;
  const temiz = deger.trim();
  return temiz.length > 0 ? temiz : null;
}

function metinAnahtari(deger: string): string {
  return deger
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .toLocaleLowerCase("tr-TR")
    .replace(/ı/gu, "i");
}

function metinKarsilastir(sol: string, sag: string): number {
  const solAnahtar = metinAnahtari(sol);
  const sagAnahtar = metinAnahtari(sag);
  if (solAnahtar < sagAnahtar) return -1;
  if (solAnahtar > sagAnahtar) return 1;
  if (sol < sag) return -1;
  if (sol > sag) return 1;
  return 0;
}

function yakinMagazaKarsilastir(sol: YakinMagaza, sag: YakinMagaza): number {
  if (sol.mesafeM !== sag.mesafeM) return sol.mesafeM - sag.mesafeM;
  const markaSirasi = metinKarsilastir(sol.marka, sag.marka);
  return markaSirasi !== 0 ? markaSirasi : metinKarsilastir(sol.subeAd, sag.subeAd);
}

function ayniMarkaAdayKarsilastir(sol: YakinMagaza, sag: YakinMagaza): number {
  if (sol.mesafeM !== sag.mesafeM) return sol.mesafeM - sag.mesafeM;
  const subeSirasi = metinKarsilastir(sol.subeAd, sag.subeAd);
  return subeSirasi !== 0 ? subeSirasi : metinKarsilastir(sol.marka, sag.marka);
}

/** İki geçerli dünya koordinatı arasındaki kuş uçuşu uzaklık, metreye yuvarlanmış. */
export function mesafeM(lat1: number, lon1: number, lat2: number, lon2: number): number {
  if (!koordinatGecerliMi(lat1, lon1) || !koordinatGecerliMi(lat2, lon2)) {
    throw new RangeError("Koordinatlar sonlu ve dünya sınırları içinde olmalıdır.");
  }

  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) ** 2;
  const guvenliA = Math.min(1, Math.max(0, a));
  return Math.round(DUNYA_YARICAPI_METRE * 2 * Math.asin(Math.sqrt(guvenliA)));
}

/** Marka başına en yakın geçerli şube; mesafe ve metin eşitliklerinde kesin sıralı ilk `adet`. */
export function enYakinMagazalar(
  subeler: readonly Sube[],
  lat: number,
  lon: number,
  adet = 6
): YakinMagaza[] {
  const sinir = Number.isFinite(adet) ? Math.floor(adet) : 0;
  if (!Array.isArray(subeler) || sinir <= 0 || !koordinatGecerliMi(lat, lon)) return [];

  const enYakin = new Map<string, YakinMagaza>();
  for (const sube of subeler) {
    if (!sube || typeof sube !== "object") continue;

    const marka = metinTemizle(sube.marka);
    const subeAd = metinTemizle(sube.ad);
    if (!marka || !subeAd || !koordinatGecerliMi(sube.lat, sube.lon)) continue;

    const aday: YakinMagaza = {
      marka,
      subeAd,
      mesafeM: mesafeM(lat, lon, sube.lat, sube.lon),
      lat: sube.lat,
      lon: sube.lon,
    };
    const markaAnahtari = metinAnahtari(marka);
    const eski = enYakin.get(markaAnahtari);
    if (!eski || ayniMarkaAdayKarsilastir(aday, eski) < 0) enYakin.set(markaAnahtari, aday);
  }

  return [...enYakin.values()].sort(yakinMagazaKarsilastir).slice(0, sinir);
}

export function mesafeYaz(metre: number): string {
  if (!Number.isFinite(metre) || metre < 0) return "—";
  const yuvarlanmisMetre = Math.round(metre);
  return yuvarlanmisMetre < 1000
    ? `${yuvarlanmisMetre} m`
    : `${(yuvarlanmisMetre / 1000).toFixed(1).replace(".", ",")} km`;
}
