/**
 * NE:       Google Places'ten (New) cihaz konumuna en yakın GERÇEK hastaneleri çeker (tüm Türkiye).
 * NEDEN:    Kayseri json'u elle derlenmişti → başka şehirde "kayıt yok". Acil bir anda kullanıcı nerede
 *           olursa olsun yakın büyük hastaneler gelmeli — diş/psikiyatri/muayenehane değil.
 * NASIL:    İKİ çağrı birleşir: (a) DISTANCE = yanı başındaki, (b) POPULARITY = bölgenin büyük/tanınmış
 *           hastaneleri (tek DISTANCE çağrısı yoğun bölgede küçük yerlerle dolup büyük hastaneleri kaçırıyordu).
 *           Google "hospital" tipi geniş (diş/psikiyatri/diyaliz/poliklinik düşüyor) → ad filtresiyle YALNIZ
 *           tam-teşekküllü hastane tutulur, dar uzmanlık elenir. Anahtar yok / hata / boş → null (yerel liste).
 *           Konum yalnız Google'a gider, bizim sunucuya DEĞİL.
 * YAN ETKİ: İki dış HTTP çağrısı (Google). Kalıcı kayıt/izleme yok.
 */
import { mesafeM, koordinatGecerliMi } from "../motor/konumHesap";

const ANAHTAR = process.env.EXPO_PUBLIC_GOOGLE_PLACES_KEY ?? "";
const UCPOINT = "https://places.googleapis.com/v1/places:searchNearby";

// DAHİL: gerçek hastane adı. HARİÇ: dar uzmanlık / küçük sağlık yeri (acilde tam-teşekküllü gerekir).
const HASTANE_ADI = /hastane|hospital|tıp\s*fak|tıp\s*merkez|medical|sağlık\s*merkez|şehir hastane|devlet hastane|üniversite.*tıp/iu;
// Kökleri kısa tut (Türkçe çekim: "poliklinik"→"polikliniği" k→ğ; "muayene"→"muayenehane") — çekimli hâli de yakalasın.
const DAR_UZMANLIK = /diş|ağız|ortodonti|implant|psikiyatr|ruh sağlığı|amatem|göz\b|veteriner|hayvan|diyaliz|poliklini|muayene|estetik|güzellik|saç ekim|tüp bebek|üreme|fizik tedavi|cilt|dermatoloji|optik|işitme|eczane|laboratuv|görüntülem|radyoloji|onkoloji tanı/iu;

function gercekHastaneMi(ad: string): boolean {
  const a = ad.toLocaleLowerCase("tr-TR");
  return HASTANE_ADI.test(a) && !DAR_UZMANLIK.test(a);
}

export type PlacesHastane = {
  ad: string;
  lat: number;
  lon: number;
  tip: string;
  acilServis: boolean;
  mesafeM: number;
};

export async function yakinHastanelerPlaces(
  lat: number,
  lon: number,
  adet = 6,
  yaricapM = 20000
): Promise<PlacesHastane[] | null> {
  if (!ANAHTAR || !koordinatGecerliMi(lat, lon)) return null;

  async function cagir(rankPref?: "DISTANCE"): Promise<unknown[]> {
    try {
      const govde: Record<string, unknown> = {
        includedTypes: ["hospital"],
        maxResultCount: 20,
        languageCode: "tr",
        locationRestriction: { circle: { center: { latitude: lat, longitude: lon }, radius: yaricapM } },
      };
      if (rankPref) govde.rankPreference = rankPref;
      const yanit = await fetch(UCPOINT, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Goog-Api-Key": ANAHTAR,
          "X-Goog-FieldMask": "places.displayName,places.location,places.primaryType",
        },
        body: JSON.stringify(govde),
      });
      if (!yanit.ok) return [];
      const veri: unknown = await yanit.json();
      const yerler = (veri as { places?: unknown[] }).places;
      return Array.isArray(yerler) ? yerler : [];
    } catch {
      return [];
    }
  }

  try {
    // (a) en yakın + (b) popüler/büyük — birleşir, filtrelenir, koordinat dedup, mesafeye göre sıra.
    const gruplar = await Promise.all([cagir("DISTANCE"), cagir()]);
    const tumYerler = gruplar.flat();
    if (tumYerler.length === 0) return null;

    const gorulen = new Set<string>();
    const sonuc: PlacesHastane[] = [];
    for (const y of tumYerler) {
      const yer = y as { displayName?: { text?: string }; location?: { latitude?: number; longitude?: number } };
      const ad = yer.displayName?.text ?? "";
      const plat = yer.location?.latitude;
      const plon = yer.location?.longitude;
      if (!ad || !gercekHastaneMi(ad)) continue;
      if (typeof plat !== "number" || typeof plon !== "number" || !koordinatGecerliMi(plat, plon)) continue;
      const anahtar = `${plat.toFixed(4)}-${plon.toFixed(4)}`;
      if (gorulen.has(anahtar)) continue;
      gorulen.add(anahtar);
      sonuc.push({ ad: ad.slice(0, 60), lat: plat, lon: plon, tip: "hastane", acilServis: false, mesafeM: mesafeM(lat, lon, plat, plon) });
    }
    sonuc.sort((a, b) => a.mesafeM - b.mesafeM);
    return sonuc.length > 0 ? sonuc.slice(0, adet) : null;
  } catch {
    return null;
  }
}
