/**
 * NE:       Kredi kartı vektör parçaları — EMV chip + temassız (NFC) simgesi + ağ logoları
 * NEDEN:    Foto-gerçekçi kart hissi bu küçük gerçek detaylardan doğar (jenerik kutu değil)
 * NASIL:    react-native-svg; chip = altın degrade + iç kontak deseni; temassız = 4 yay;
 *           ağ logoları sade vektör (Visa/Mastercard/Troy/Amex) — birebir marka kopyası değil,
 *           tanınır sadeleştirme
 * YAN ETKİ: Yok
 */
import { Text } from "react-native";
import Svg, { Circle, Defs, LinearGradient, Path, Rect, Stop, G } from "react-native-svg";

/** EMV altın chip — gerçek kartlardaki kontak deseniyle */
export function Chip({ boy = 34 }: { boy?: number }) {
  const en = boy * 1.28; // gerçek chip oranı (~yatay dikdörtgen)
  return (
    <Svg width={en} height={boy} viewBox="0 0 44 34">
      <Defs>
        <LinearGradient id="chipG" x1="0" y1="0" x2="1" y2="1">
          <Stop offset="0" stopColor="#f6e5a8" />
          <Stop offset="0.45" stopColor="#d9b24a" />
          <Stop offset="0.55" stopColor="#c99a2e" />
          <Stop offset="1" stopColor="#e8cf7e" />
        </LinearGradient>
      </Defs>
      <Rect x="0.6" y="0.6" width="42.8" height="32.8" rx="5" fill="url(#chipG)" stroke="#a87f22" strokeWidth="0.8" />
      {/* Kontak deseni — gerçek EMV çizgileri */}
      <G stroke="#a87f22" strokeWidth="1.1" opacity="0.85">
        <Path d="M15 0.6 V33.4" fill="none" />
        <Path d="M29 0.6 V33.4" fill="none" />
        <Path d="M0.6 11 H15" fill="none" />
        <Path d="M0.6 23 H15" fill="none" />
        <Path d="M29 11 H43.4" fill="none" />
        <Path d="M29 23 H43.4" fill="none" />
        <Rect x="15" y="11" width="14" height="12" fill="none" />
      </G>
    </Svg>
  );
}

/** Temassız ödeme simgesi — sağa açılan 4 yay */
export function Temassiz({ boy = 22, renk = "#ffffff" }: { boy?: number; renk?: string }) {
  return (
    <Svg width={boy} height={boy} viewBox="0 0 24 24">
      <G stroke={renk} strokeWidth="1.9" fill="none" strokeLinecap="round" opacity="0.92">
        <Path d="M7 8.5 a6 6 0 0 1 0 7" />
        <Path d="M10.5 6 a10 10 0 0 1 0 12" />
        <Path d="M14 3.8 a14 14 0 0 1 0 16.4" />
      </G>
    </Svg>
  );
}

/** Ağ logosu — sadeleştirilmiş, tanınır (birebir marka değil) */
export function AgLogosu({ ag, boy = 22 }: { ag: string; boy?: number }) {
  const a = ag.toLowerCase();
  if (a.includes("master")) {
    return (
      <Svg width={boy * 1.6} height={boy} viewBox="0 0 40 24">
        <Circle cx="15" cy="12" r="10" fill="#eb001b" opacity="0.95" />
        <Circle cx="25" cy="12" r="10" fill="#f79e1b" opacity="0.9" />
      </Svg>
    );
  }
  if (a.includes("troy")) {
    return (
      <Svg width={boy * 2} height={boy} viewBox="0 0 52 24">
        <Path d="M4 16 q10 -12 22 0 q10 10 22 -2" stroke="#00a0e3" strokeWidth="3.4" fill="none" strokeLinecap="round" />
      </Svg>
    );
  }
  if (a.includes("amex") || a.includes("american")) {
    return (
      <Text
        style={{
          color: "#f7f7ff",
          fontSize: boy * 0.62,
          fontWeight: "900",
          letterSpacing: 0.2,
          opacity: 0.95,
        }}
      >
        AMEX
      </Text>
    );
  }
  // Visa (varsayılan) — italik wordmark (Text en temiz + tanınır)
  return (
    <Text
      style={{
        color: "#f7f7ff",
        fontSize: boy * 0.92,
        fontWeight: "800",
        fontStyle: "italic",
        letterSpacing: 0.5,
        opacity: 0.95,
      }}
    >
      VISA
    </Text>
  );
}
