/**
 * NE:       Günün Kartı — Hangi Kart? sekmesi başında mühürlü kapak; dokununca açılır ve cüzdandaki
 *           programlardan BUGÜN (gün tohumu) öne çıkanı + o programın en iyi aktif kampanyasını gösterir.
 * NEDEN:    "Bugün hangi kartım şanslı?" merakıyla açtıran günlük keşif ritüeli (sürpriz #5). Günde bir
 *           kez açılır (App günlük kapı); ertesi gün yeni kart. Kampanya yoksa dürüst mesaj — boş kutu YOK.
 * NASIL:    Kapalı: grafit+altın kapak (dokun). Açık: KrediKarti (program yüzü) + kampanya başlığı;
 *           kampanya varsa AltinHale (kazanç kanonu). dokunsalHafif dokunuş. Animasyon minimal (reveal).
 * YAN ETKİ: Yok — seçim gununKarti.ts motorundan (deterministik); para türetmez. Sunucu yok.
 */
import { StyleSheet, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import type { GununKartiSecim } from "../motor/gununKarti";
import { PROGRAM_MARKA } from "../marka/markalar";
import { dokunsalHafif } from "../dokunsal";
import { TEMA } from "../tema";
import { KrediKarti } from "./KrediKarti";
import { AltinHale } from "./AltinHale";
import { Basilabilir } from "./Basilabilir";

export function GununKarti({
  secim,
  acildi,
  hareketAzalt = false,
  onAc,
}: {
  secim: GununKartiSecim;
  acildi: boolean;
  hareketAzalt?: boolean;
  onAc: () => void;
}) {
  const marka = PROGRAM_MARKA[secim.program];

  if (!acildi) {
    return (
      <Basilabilir
        stil={s.kapak}
        onPress={() => {
          dokunsalHafif();
          onAc();
        }}
        hareketAzalt={hareketAzalt}
        accessibilityRole="button"
        accessibilityLabel="Günün Kartını aç"
      >
        <LinearGradient
          colors={[TEMA.renk.zeminKoyu, TEMA.renk.panel]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={StyleSheet.absoluteFill}
        />
        <View style={s.kapakRozet}>
          <Text style={s.kapakSoru}>?</Text>
        </View>
        <View style={s.kapakOrta}>
          <Text style={s.kapakBaslik}>Günün Kartı</Text>
          <Text style={s.kapakAlt}>Açmak için dokun</Text>
        </View>
        <Text style={s.kapakOk}>›</Text>
      </Basilabilir>
    );
  }

  const k = secim.kampanya;
  return (
    <View style={s.acik}>
      {k ? <AltinHale yaricap={70} /> : null}
      <KrediKarti
        program={secim.program}
        kartGradyan={marka?.kartGradyan as [string, string, ...string[]] | undefined}
        en={92}
        hareketAzalt={hareketAzalt}
      />
      <View style={s.acikOrta}>
        <Text style={s.acikBaslik}>Bugün {secim.program} önde</Text>
        {k ? (
          <Text style={s.acikKampanya} numberOfLines={2}>
            {k.baslik}
          </Text>
        ) : (
          <Text style={s.acikYok} numberOfLines={2}>
            Bugün öne çıkan kampanyası yok — ama cüzdanında hazır.
          </Text>
        )}
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  kapak: {
    flexDirection: "row",
    alignItems: "center",
    gap: TEMA.bosluk.m,
    borderRadius: TEMA.yaricap.buyuk,
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    overflow: "hidden",
    paddingVertical: TEMA.bosluk.l,
    paddingHorizontal: TEMA.bosluk.l,
    marginBottom: TEMA.bosluk.l,
  },
  kapakRozet: {
    width: 44,
    height: 44,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    backgroundColor: TEMA.renk.altinZemin,
    alignItems: "center",
    justifyContent: "center",
  },
  kapakSoru: { color: TEMA.renk.altinAcik, fontSize: 22, fontWeight: "800" },
  kapakOrta: { flex: 1 },
  kapakBaslik: { color: TEMA.renk.altinAcik, fontSize: 14, fontWeight: "800" },
  kapakAlt: { color: TEMA.renk.yaziSoluk, fontSize: 11.5, marginTop: 2 },
  kapakOk: { color: TEMA.renk.altinAcik, fontSize: 22, fontWeight: "800" },
  acik: {
    flexDirection: "row",
    alignItems: "center",
    gap: TEMA.bosluk.m,
    borderRadius: TEMA.yaricap.buyuk,
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    backgroundColor: TEMA.renk.altinZemin,
    padding: TEMA.bosluk.m,
    marginBottom: TEMA.bosluk.l,
    overflow: "hidden",
  },
  acikOrta: { flex: 1 },
  acikBaslik: { color: TEMA.renk.altinAcik, fontSize: 13.5, fontWeight: "800" },
  acikKampanya: { color: TEMA.renk.yazi, fontSize: 12, lineHeight: 16, marginTop: 3 },
  acikYok: { color: TEMA.renk.yaziSoluk, fontSize: 11.5, lineHeight: 16, marginTop: 3 },
});
