/**
 * NE:       Sayıyı 0'dan hedefe yumuşak yuvarlayarak dolduran count-up kancası (görsel devrim).
 * NEDEN:    Kazanan TL rakamı "gelir" hissi verir — ama finansal rakam bir an bile YANLIŞ
 *           görünmemeli; bu yüzden yalnız görsel dolgudur, çağıran katman oturan değeri her
 *           zaman kanonik string'e kilitler (para sapmaz).
 * NASIL:    requestAnimationFrame + easeOutCubic; hareketAzalt açıksa anında hedefe atlar;
 *           hedef değişince yeniden akar; sökülünce rAF iptal edilir. Değer tam sayı yuvarlanır
 *           ve son karede tam olarak hedefe eşitlenir.
 * YAN ETKİ: Yok — yalnız yerel state; ağ/dosya erişimi yok.
 */
import { useEffect, useRef, useState } from "react";

interface Secenek {
  hareketAzalt?: boolean;
  sureMs?: number;
}

export function useSayac(hedef: number, secenek?: Secenek): number {
  const sure = secenek?.sureMs ?? 620;
  const hareketAzalt = secenek?.hareketAzalt ?? false;
  // İlk kare flaşı önlemek için: animasyonlu durumda 0'dan başla (effect rAF ile hedefe akar);
  // reduce-motion / 0 / geçersiz hedefte doğrudan hedefte dur (efektin erken-dönüş koşuluyla birebir).
  const [deger, setDeger] = useState(() =>
    hareketAzalt || !Number.isFinite(hedef) || hedef <= 0 ? hedef : 0,
  );
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    if (hareketAzalt || !Number.isFinite(hedef) || hedef <= 0) {
      setDeger(hedef);
      return;
    }
    let iptal = false;
    let t0: number | null = null;
    const easeOutCubic = (x: number) => 1 - Math.pow(1 - x, 3);
    const adim = (zaman: number) => {
      if (iptal) return;
      if (t0 === null) t0 = zaman;
      const ilerleme = Math.min(1, (zaman - t0) / sure);
      setDeger(ilerleme >= 1 ? hedef : Math.round(hedef * easeOutCubic(ilerleme)));
      if (ilerleme < 1) rafRef.current = requestAnimationFrame(adim);
    };
    setDeger(0);
    rafRef.current = requestAnimationFrame(adim);
    return () => {
      iptal = true;
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
    };
  }, [hedef, hareketAzalt, sure]);

  return deger;
}
