/**
 * NE:       Açılış karşılama ekranı — sinematik giriş: tam ekran giriş görseli (yelpaze premium kartlar +
 *           altın huzme/halo) yavaşça yakınlaşır, "KartAkıl" adı yumuşak belirir, sonra fade → ana içerik.
 * NEDEN:    Mehmet abi (2026-07-21): "çok daha muhteşem bir giriş" — statik değil, film gibi açılış.
 *           Premium ilk-izlenim + kimlik (grafit+altın). Expo Go'da da görünür (native splash'tan ayrı DOM katmanı).
 * NASIL:    giris Animated.Value (0→1): görsel scale 1.08→1 (sinematik zoom-in) + marka adı opacity/translateY
 *           (gecikmeli belirir). Sonra opak fade-out (native driver). hareketAzalt açıksa kısa bekleyip anında
 *           geçer (statik dinginlik). Tek atış, loop yok.
 * YAN ETKİ: pointerEvents none (dokunmayı yutmaz); bittiğinde onBitti ile kendini kaldırtır.
 */
import { useEffect, useRef } from "react";
/*
 * NE: Kullanılmayan `View` importunu kaldırır.
 * NEDEN: Tam yayın kapısındaki no-unused TypeScript denetimini gereksiz bağımlılık durduruyordu.
 * NASIL: Bileşenin gerçek import kümesiyle sınırlar.
 * YAN ETKİ: Çalışma zamanı ve görünüm değişmez.
 */
import { Animated, Image, StyleSheet, Text } from "react-native";
import { TEMA } from "../tema";

const GIRIS = require("../../assets/giris.webp");
const AnimatedImage = Animated.createAnimatedComponent(Image);

export function Acilis({
  onBitti,
  hareketAzalt = false,
}: {
  onBitti: () => void;
  hareketAzalt?: boolean;
}) {
  const opak = useRef(new Animated.Value(1)).current; // fade-out
  const giris = useRef(new Animated.Value(hareketAzalt ? 1 : 0)).current; // zoom-in + marka beliriş

  useEffect(() => {
    if (hareketAzalt) {
      const t = setTimeout(onBitti, 850);
      return () => clearTimeout(t);
    }
    // Giriş: görsel yavaşça yakınlaşır + marka adı belirir (yumuşak, sinematik)
    const acilisAnim = Animated.timing(giris, {
      toValue: 1,
      duration: 1150,
      useNativeDriver: true,
    });
    acilisAnim.start();
    // Sahne oturur → yumuşak fade → ana içerik
    const bekle = setTimeout(() => {
      Animated.timing(opak, {
        toValue: 0,
        duration: 540,
        useNativeDriver: true,
      }).start(({ finished }) => {
        if (finished) onBitti();
      });
    }, 1950);
    return () => {
      acilisAnim.stop();
      clearTimeout(bekle);
    };
  }, [opak, giris, onBitti, hareketAzalt]);

  const olcek = giris.interpolate({ inputRange: [0, 1], outputRange: [1.08, 1] });
  const yaziOpak = giris.interpolate({ inputRange: [0, 0.55, 1], outputRange: [0, 0, 1] });
  const yaziKay = giris.interpolate({ inputRange: [0, 1], outputRange: [18, 0] });

  return (
    <Animated.View
      style={[StyleSheet.absoluteFill, s.kap, { opacity: opak }]}
      pointerEvents="none"
    >
      <AnimatedImage
        source={GIRIS}
        style={[StyleSheet.absoluteFill, { transform: [{ scale: olcek }] }]}
        resizeMode="cover"
      />
      <Animated.View
        style={[s.altYazi, { opacity: yaziOpak, transform: [{ translateY: yaziKay }] }]}
      >
        <Text style={s.ad}>KartAkıl</Text>
        <Text style={s.slogan}>Hangi kartımla ödesem?</Text>
      </Animated.View>
    </Animated.View>
  );
}

const s = StyleSheet.create({
  kap: { backgroundColor: TEMA.renk.zemin },
  altYazi: { position: "absolute", left: 0, right: 0, bottom: "17%", alignItems: "center" },
  ad: {
    color: TEMA.renk.altinAcik,
    fontSize: 40,
    fontWeight: "800",
    letterSpacing: 1.5,
  },
  slogan: {
    color: TEMA.renk.gumus,
    fontSize: 15,
    marginTop: 8,
    letterSpacing: 0.3,
  },
});
