/**
 * NE:       Yükleme anı için içeriğin ŞEKLİNDE premium iskelet + tek geçişli altın parıltı.
 * NEDEN:    Görsel devrim: dönen çember değil, boş beyaz an da değil — kimlik rengi (altın)
 *           yükleme anına bile işler; algılanan hız artar, güven kırılmaz.
 * NASIL:    Grafit blok (kat1 yüzeyi) + üstünden soldan sağa kayan altın-tonlu LinearGradient
 *           parıltı (Animated loop, native driver). hareketAzalt açıksa parıltı durur, blok
 *           sabit soluk kalır.
 * YAN ETKİ: Yok — saf sunum; ağ/dosya erişimi yok.
 */
import { useEffect, useRef } from "react";
import { Animated, StyleSheet, View, type DimensionValue, type ViewStyle } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { TEMA } from "../tema";

interface Props {
  en?: DimensionValue;
  boy?: number;
  yaricap?: number;
  hareketAzalt?: boolean;
  style?: ViewStyle;
}

export function Iskelet({
  en = "100%",
  boy = 16,
  yaricap = TEMA.yaricap.kucuk,
  hareketAzalt = false,
  style,
}: Props) {
  const kaydir = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (hareketAzalt) return;
    const dongu = Animated.loop(
      Animated.timing(kaydir, { toValue: 1, duration: 1150, useNativeDriver: true })
    );
    dongu.start();
    return () => dongu.stop();
  }, [kaydir, hareketAzalt]);

  return (
    <View
      style={[
        { width: en, height: boy, borderRadius: yaricap, backgroundColor: TEMA.yuzey.kat1.zemin, overflow: "hidden" },
        style,
      ]}
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
    >
      {!hareketAzalt ? (
        <Animated.View
          style={[
            StyleSheet.absoluteFill,
            { transform: [{ translateX: kaydir.interpolate({ inputRange: [0, 1], outputRange: [-260, 260] }) }] },
          ]}
          pointerEvents="none"
        >
          <LinearGradient
            colors={["transparent", "rgba(212,175,55,0.16)", "transparent"]}
            start={{ x: 0, y: 0.5 }}
            end={{ x: 1, y: 0.5 }}
            style={StyleSheet.absoluteFill}
          />
        </Animated.View>
      ) : null}
    </View>
  );
}

/** Karar sonucu beklenirken kart-şeklinde iskelet grubu (büyük cevap + iki satır). */
export function IskeletKarar({ hareketAzalt = false }: { hareketAzalt?: boolean }) {
  return (
    <View style={g.kap} accessibilityLabel="Sonuç hesaplanıyor">
      <View style={g.sahne}>
        <Iskelet en={190} boy={120} yaricap={TEMA.yaricap.orta} hareketAzalt={hareketAzalt} />
        <Iskelet en={150} boy={16} hareketAzalt={hareketAzalt} style={{ marginTop: TEMA.bosluk.l }} />
        <Iskelet en={110} boy={34} yaricap={TEMA.yaricap.kucuk} hareketAzalt={hareketAzalt} style={{ marginTop: TEMA.bosluk.s }} />
      </View>
      <Iskelet boy={58} yaricap={TEMA.yaricap.orta} hareketAzalt={hareketAzalt} style={{ marginTop: TEMA.bosluk.m }} />
      <Iskelet boy={58} yaricap={TEMA.yaricap.orta} hareketAzalt={hareketAzalt} style={{ marginTop: TEMA.bosluk.s }} />
    </View>
  );
}

const g = StyleSheet.create({
  kap: { marginTop: TEMA.bosluk.s },
  sahne: {
    borderRadius: TEMA.yaricap.buyuk,
    borderWidth: 1,
    borderColor: TEMA.yuzey.kat2.kenar,
    backgroundColor: TEMA.yuzey.kat2.zemin,
    paddingVertical: TEMA.bosluk.xl,
    alignItems: "center",
  },
});
