/**
 * NE:       Canlı yayın deposu (Supabase yayin_snapshot) → en son ONAYLI v3 yayın paketini çeker,
 *           başarılı çekimi cihazda önbelleğe alır (çevrimdışı süreklilik).
 * NEDEN:    "Canlı" = uygulama her açılışta güncel kampanyaları buluttan alır. Ağ yoksa, koda gömülü
 *           (aylar önceki) seed yerine EN SON çekilen canlı veriyi gösterelim → kullanıcı offline'da bile
 *           mümkün olan en güncel veriyi görür (stale-while-revalidate). Admin yeni snapshot yükleyince
 *           bir sonraki çevrimiçi açılışta taze veri gelir — kod/store güncellemesi gerekmeden.
 * NASIL:    Supabase PostgREST tek GET (anon key + timeout). Başarı → AsyncStorage'a yaz + döndür.
 *           Hata/offline/anahtar-yok → önbellekten oku; o da yoksa null (çağıran bundle seed'e düşer).
 * YAN ETKİ: Yalnız OKUR (kart no / konum GÖNDERMEZ). Kırmızı çizgi: yalnız insan-onaylı snapshot yayına
 *           yazıldığından buradan gelen veri onaylıdır; SHA doğrulaması App tarafında (v3KaynakHash).
 *           Önbellek yazımı best-effort (hata yutulur); ASLA exception fırlatmaz, boş ekran üretmez.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";
import type { TaslakKampanya } from "../tipler";

const URL = process.env.EXPO_PUBLIC_SUPABASE_URL;
const ANON = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY;
const ONBELLEK_ANAHTARI = "kartakil.canliYayin.v1";

export interface CanliYayinPaketi {
  /** kampanyalar-v3.json muadili — v3YayininiDogrula'ya verilecek yayın nesnesi */
  v3Yayin: unknown;
  /** v3-esleme-katalogu.json muadili */
  katalog: unknown;
  /** v3-kaynak-manifesti.json muadili ({ sourceFetchedAtById }) */
  manifest: { sourceFetchedAtById?: Record<string, string> } & Record<string, unknown>;
  /** kampanyalar.json muadili — SHA hesabı ve V3 doğrulaması için ham kayıtlar */
  ham: TaslakKampanya[];
}

/** Paketin gerekli parçaları tam mı? (ağdan da önbellekten de aynı bütünlük kapısı) */
function paketGecerliMi(veri: unknown): veri is CanliYayinPaketi {
  const v = veri as CanliYayinPaketi | null;
  return !!v && !!v.v3Yayin && !!v.katalog && !!v.manifest && Array.isArray(v.ham);
}

/** Cihaz önbelleğinden son başarılı canlı paketi oku (yoksa/bozuksa null). */
async function onbellektenOku(): Promise<CanliYayinPaketi | null> {
  try {
    const ham = await AsyncStorage.getItem(ONBELLEK_ANAHTARI);
    if (!ham) return null;
    const veri = JSON.parse(ham);
    return paketGecerliMi(veri) ? veri : null;
  } catch {
    return null;
  }
}

/**
 * Canlı yayını getir. Öncelik: ağdan taze → başarılıysa önbelleğe yaz. Ağ yok/hata/anahtar yok →
 * son başarılı önbellek. O da yoksa null (çağıran bundle seed'e düşer). Asla throw etmez.
 */
export async function canliYayiniGetir(zamanAsimiMs = 6000): Promise<CanliYayinPaketi | null> {
  if (!URL || !ANON) return onbellektenOku(); // anahtar gelmeden: önbellek varsa o, yoksa bundle

  try {
    const ctrl = new AbortController();
    const zamanlayici = setTimeout(() => ctrl.abort(), zamanAsimiMs);
    const res = await fetch(
      `${URL}/rest/v1/yayin_snapshot?is_active=eq.true&select=veri&order=created_at.desc&limit=1`,
      {
        headers: { apikey: ANON, Authorization: `Bearer ${ANON}` },
        signal: ctrl.signal,
      }
    );
    clearTimeout(zamanlayici);
    if (!res.ok) return onbellektenOku();

    const satirlar: unknown = await res.json();
    const veri =
      Array.isArray(satirlar) && satirlar.length > 0
        ? (satirlar[0] as { veri?: unknown }).veri
        : null;

    if (!paketGecerliMi(veri)) return onbellektenOku();

    // Taze veri geldi → önbelleğe yaz (best-effort, arka plan; hata çekimi bozmaz)
    AsyncStorage.setItem(ONBELLEK_ANAHTARI, JSON.stringify(veri)).catch(() => undefined);
    return veri;
  } catch {
    return onbellektenOku(); // abort / ağ / parse → son başarılı canlı veri
  }
}
