/**
 * NE:       Kampanya/mağaza kategorisi için "sahne görseli" — gerçek foto varsa onu, yoksa premium fallback.
 * NEDEN:    Görsel devrim planı (docs/GORSEL-DEVRIM-YOL-HARITASI-2026-07-21.md): her ekran sahne görseliyle
 *           Maximum-seviyesine çıkar; AMA görsel dosyası gelmeden de ASLA çökmez / boş beyaz an olmaz.
 * NASIL:    assets/kategoriler/{kategori}.webp statik map → cover Image. Görsel yoksa kategori-renkli
 *           degrade + soluk büyük KategoriIkon (sahne hissi). Üst bileşen (KampanyaKarti) çift scrim ekler.
 *           Yeni görsel gelince: KATEGORI_GORSEL'e 1 satır require → app otomatik zenginleşir.
 * YAN ETKİ: Yok — saf sunum; ağ/dosya erişimi yok.
 */
import { Image, StyleSheet, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { KategoriIkon } from "./KategoriIkon";
import { TEMA } from "../tema";

// Grup A görselleri (ChatGPT) — her kategori bir DİZİ; birden çok varyant = tekrar biter
// (kampanya id'sine göre stabil döner). Yeni görsel gelince o kategorinin dizisine 1 satır ekle.
const KATEGORI_GORSEL: Record<string, number[]> = {
  market: [
    require("../../assets/kategoriler/market.webp"),
    require("../../assets/kategoriler/market-2.webp"),
  ],
  akaryakit: [
    require("../../assets/kategoriler/akaryakit.webp"),
    require("../../assets/kategoriler/akaryakit-2.webp"),
  ],
  "e-ticaret": [
    require("../../assets/kategoriler/e-ticaret.webp"),
    require("../../assets/kategoriler/e-ticaret-2.webp"),
  ],
  giyim: [
    require("../../assets/kategoriler/giyim.webp"),
    require("../../assets/kategoriler/giyim-2.webp"),
  ],
  "yeme-icme": [
    require("../../assets/kategoriler/yeme-icme.webp"),
    require("../../assets/kategoriler/yeme-icme-2.webp"),
  ],
  elektronik: [
    require("../../assets/kategoriler/elektronik.webp"),
    require("../../assets/kategoriler/elektronik-2.webp"),
  ],
  seyahat: [
    require("../../assets/kategoriler/seyahat.webp"),
    require("../../assets/kategoriler/seyahat-2.webp"),
  ],
  saglik: [
    require("../../assets/kategoriler/saglik.webp"),
    require("../../assets/kategoriler/saglik-2.webp"),
  ],
  diger: [
    require("../../assets/kategoriler/diger.webp"),
    require("../../assets/kategoriler/diger-2.webp"),
  ],
  "vergi-kamu": [
    require("../../assets/kategoriler/vergi-kamu.webp"),
    require("../../assets/kategoriler/vergi-kamu-2.webp"),
  ],
  egitim: [
    require("../../assets/kategoriler/egitim.webp"),
    require("../../assets/kategoriler/egitim-2.webp"),
  ],
  eglence: [
    require("../../assets/kategoriler/eglence.webp"),
    require("../../assets/kategoriler/eglence-2.webp"),
  ],
  "ev-yasam": [
    require("../../assets/kategoriler/ev-yasam.webp"),
    require("../../assets/kategoriler/ev-yasam-2.webp"),
  ],
};

// Fallback degrade üst tonu — her kategoriye sakin bir sahne rengi (grafite erir)
const KATEGORI_RENK: Record<string, string> = {
  market: "#1f6f4a",
  akaryakit: "#8a4b1f",
  giyim: "#6a3d7a",
  elektronik: "#1f4f7a",
  "yeme-icme": "#7a3320",
  "e-ticaret": "#7a5a1f",
  seyahat: "#1f5f7a",
  saglik: "#2a7a5f",
  egitim: "#3a4a7a",
  eglence: "#7a2a5a",
  "ev-yasam": "#5a5a3a",
  "vergi-kamu": "#4a4a5a",
};

// Kod eşanlamlıları — karar ekranı "restoran" der, görsel havuzu "yeme-icme" (aynı sahne).
const ALIAS: Record<string, string> = { restoran: "yeme-icme", yemek: "yeme-icme" };

export function KategoriGorsel({
  kategori,
  yukseklik,
  varyant = 0,
}: {
  kategori: string;
  yukseklik: number;
  varyant?: number;
}) {
  const anahtar = ALIAS[kategori] ?? kategori;
  const dizi = KATEGORI_GORSEL[anahtar];
  if (dizi && dizi.length > 0) {
    const gorsel = dizi[varyant % dizi.length];
    return <Image source={gorsel} style={{ width: "100%", height: yukseklik }} resizeMode="cover" />;
  }
  const renk = KATEGORI_RENK[kategori] ?? "#3a3d47";
  return (
    <View style={{ height: yukseklik, overflow: "hidden" }}>
      <LinearGradient
        colors={[renk, "#191c22", TEMA.renk.zemin]}
        start={{ x: 0.15, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={StyleSheet.absoluteFill}
      />
      {/* soluk dev ikon — sahne hissi (dokunmayı yutmaz) */}
      <View style={s.ikon} pointerEvents="none">
        <KategoriIkon kod={kategori} renk="rgba(255,255,255,0.12)" boy={Math.round(yukseklik * 0.72)} />
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  ikon: {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    alignItems: "flex-end",
    justifyContent: "center",
    paddingRight: 20,
  },
});
