/** cardProductId → issuerId (BuyukCevap gibi issuerId taşımayan sunum yerlerinden köprüye erişim). */
export function urunIssuerId(cardProductId: string | undefined): string | undefined {
  if (!cardProductId) return undefined;
  return KATALOG.cardProducts.find((u) => u.id === cardProductId)?.issuerId;
}

/** Bu issuer için köprü var mı + uygulama adı (buton etiketi için). */
export function bankaKoprusu(issuerId: string | undefined): { ad: string } | null {
  if (!issuerId) return null;
  const b = BANKA_KOPRU[issuerId];
  return b ? { ad: b.ad } : null;
}

/** Platforma göre en güvenli açılış URL'i (custom scheme YOK). */
export function bankaAcURL(issuerId: string): string | null {
  const b = BANKA_KOPRU[issuerId];
  if (!b) return null;
  if (Platform.OS === "ios") return b.iosUniversal ?? `https://apps.apple.com/tr/app/id${b.appStoreId}`;
  if (Platform.OS === "android") return `market://details?id=${b.androidPackage}`;
  return b.web; // web önizleme: banka sitesi
}

/** Bankanın kendi uygulamasını/sayfasını aç; hata olursa web'e düş. Ödeme İŞLEMEZ. */
export async function bankaAc(issuerId: string): Promise<void> {
  const b = BANKA_KOPRU[issuerId];
  if (!b) return;
  const url = bankaAcURL(issuerId);
  if (!url) return;
  try {
    await Linking.openURL(url);
  } catch {
    // universal link / market yoksa evrensel web fallback
    try {
      await Linking.openURL(b.web);
    } catch {
      // sessiz — kullanıcı akışı bozulmaz
    }
  }
}

/**
 * NE:       Ödeme köprüsü sunumu — buton etiketi + dürüst alt metin.
 * NEDEN:    Mehmet abi (2026-07-21): "kullanıcı en rahat tık ile ödeyebilsin." KartAkıl ödeme İŞLEMEZ
 *           (kırmızı çizgi); kullanıcıyı bankanın KENDİ app'ine götürür. Araştırma (2026-07-21): TR'de
 *           banka QR ödeme ekranına dıştan deep-link YOK → en güvenli/rahat yol app'i açmak (bankaAc).
 * NASIL:    kartAdi (program/kart) + issuer app adından "öde" etiketi ve "app açılır · karekodu okut" ipucu.
 * YAN ETKİ: Yok — saf string. Açma işini bankaAc yapar (custom scheme YOK, canOpenURL YOK).
 */
export function odemeButonu(
  issuerId: string | undefined,
  kartAdi?: string
): { etiket: string; ipucu: string } | null {
  const kopru = bankaKoprusu(issuerId);
  if (!kopru) return null;
  const isim = kartAdi?.trim() || kopru.ad;
  return { etiket: `${isim} ile öde`, ipucu: `${kopru.ad} açılır · karekodu okut` };
}

/**
 * NE:       Kampanya-katıl köprüsü — kampanyanın PUBLIC sayfasını açar (deep-link değil).
 * NEDEN:    BonusFlaş/World gibi bazı kampanyalar "önce katıl" ister; öde'den ÖNCE tek dokunuş.
 * NASIL:    Katılım/kaynak linki varsa openURL; yoksa sessiz (adım gösterilmez).
 * YAN ETKİ: Yalnız Linking.openURL — tarayıcı/app açar; veri tutmaz, ağ çağırmaz.
 */
export async function kampanyayaKatil(katilimLinki?: string): Promise<void> {
  if (!katilimLinki) return;
  try {
    await Linking.openURL(katilimLinki);
  } catch {
    // sessiz
  }
}
