/**
 * NE:       Karar satırının detay düğmesini ve resmî kaynak bağlantısını ayrı hedefler olarak sunar.
 * NEDEN:    Kaynak bağlantısını satır düğmesinin içinde tutmak web'de geçersiz iç içe etkileşim;
 *           yalnız kaynak bulunan satırı detay düğmesi yapmak ise sonuç vermeyen bir eylem üretir.
 * NASIL:    Degrade kart kabuğu etkileşimsiz Animated.View'da kalır; yalnız açılabilir içerik detay
 *           düğmesini etkinleştirir, 44 pt kaynak bağlantısı kardeş dalda ve disclosure'dan bağımsızdır.
 * YAN ETKİ: Kart gövdesi yalnız detayı açıp kapatır; kaynak bağlantısı yalnız tarayıcıyı açar.
 */
import { useEffect, useRef, useState } from "react";
/*
 * NE: Kullanılmayan `Image` importunu kaldırır.
 * NEDEN: Kart görselini KrediKarti üretir; ölü import tam kalite kapısını durduruyordu.
 * NASIL: Sonuç satırını yalnız kullandığı native yüzeylerle bırakır.
 * YAN ETKİ: Sonuç kartının görünümü ve erişilebilirliği değişmez.
 */
import { Animated, Linking, StyleSheet, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import type { KararSatiri } from "../tipler";
import { kararGuvenSunumu } from "../motor/kararGuvenSunumu";
import { TEMA } from "../tema";
import { kartGorunumu } from "../marka/markalar";
import { TutarYazi } from "./TutarYazi";
import { KrediKarti } from "./KrediKarti";
import { Basilabilir } from "./Basilabilir";

export function SonucSatiri({
  satir,
  sira,
  hareketAzalt = false,
}: {
  satir: KararSatiri;
  sira: number;
  hareketAzalt?: boolean;
}) {
  const [acik, setAcik] = useState(false);
  const birinci = sira === 1;
  const urunGorunumu = kartGorunumu(satir.cardProgramId, satir.cardProductId);
  const { v3Kesin, legacyTeyit, teyitGerekli, guvenRozeti } = kararGuvenSunumu(satir);
  const detayVar =
    satir.hesap.length > 0 ||
    satir.sadeKosullar.length > 0 ||
    satir.digerFirsat > 0;
  // Kampanyasız (vade) satır: motorun uzun iki cümlesi ("...kampanya bulunamadı" + "...vade
  // avantajını hesaplarım") her satırda tekrarlanıp listeyi kalabalıklaştırıyordu. Burada YALNIZ
  // gösterilen metin kısaltılır (karar/motor mantığı değişmez) — satırda kart yüzü + kısa vade notu kalır.
  const vadeSatiri = satir.tip === "vade";
  const kesimGunuYok = vadeSatiri && satir.etiket === "—";

  // Sahne girişi: sıraya göre gecikmeli yumuşak yüksel-belir (yay fizikli, robotik değil)
  const giris = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    if (hareketAzalt) {
      giris.setValue(1);
      return;
    }
    const animasyon = Animated.spring(giris, {
      toValue: 1,
      delay: sira * 70,
      useNativeDriver: true,
      ...TEMA.yay.sahne,
    });
    animasyon.start();
    return () => animasyon.stop();
  }, [giris, hareketAzalt, sira]);

  const satirEtiketi = `${sira}. sıra, ${satir.cardProductName ?? satir.program}, ${satir.etiket}${guvenRozeti ? `, ${guvenRozeti}` : ""}`;

  return (
    <Animated.View
      style={[
        s.satir,
        birinci && s.satirBirinci,
        {
          opacity: giris,
          transform: [{ translateY: giris.interpolate({ inputRange: [0, 1], outputRange: [14, 0] }) }],
        },
      ]}
    >
      {birinci && (
        // Şampiyon ışığı: altın degrade hâre — 1 numara ilk bakışta belli olsun
        <LinearGradient
          colors={["rgba(212,175,55,0.22)", "rgba(212,175,55,0.04)", "rgba(212,175,55,0.12)"]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={StyleSheet.absoluteFill}
          pointerEvents="none"
        />
      )}
      <Basilabilir
        onPress={() => detayVar && setAcik((onceki) => !onceki)}
        disabled={!detayVar}
        stil={s.satirAnaEylem}
        hareketAzalt={hareketAzalt}
        accessibilityRole={detayVar ? "button" : undefined}
        accessibilityState={detayVar ? { expanded: acik } : undefined}
        aria-expanded={detayVar ? acik : undefined}
        accessibilityLabel={detayVar ? `${satirEtiketi}, detayları ${acik ? "kapat" : "aç"}` : satirEtiketi}
      >
        <View style={s.ust}>
          <View style={s.miniKartSar}>
            {/* Mini gerçek kart yüzü — sıralamadaki her kart kendi görünümüyle (Apple Wallet liste hissi) */}
            <KrediKarti
              program={satir.program}
              urunAdi={satir.cardProductName}
              markaAdi={urunGorunumu?.markaAdi}
              odemeAgi={satir.paymentNetwork}
              kartGradyan={urunGorunumu?.kartGradyan}
              imza={urunGorunumu?.imza}
              altEtiket={satir.issuerName}
              en={62}
              soluk={!birinci}
              hareketAzalt={hareketAzalt}
            />
            <View style={[s.siraRozet, birinci ? s.siraAltin : s.siraGumus]}>
              <Text style={s.siraYazi}>{sira}</Text>
            </View>
          </View>
          <View style={s.orta}>
            <View style={s.programSatir}>
              <Text style={s.program} numberOfLines={1}>
                {satir.cardProductName ?? satir.program}
              </Text>
              {satir.katilimGerekli && (
                <View style={s.katilRozet}>
                  <Text style={s.katilYazi}>önce katıl</Text>
                </View>
              )}
              {guvenRozeti ? (
                <View style={[s.teyitRozet, v3Kesin && s.dogrulandiRozet]}>
                  <Text style={[s.teyitYazi, v3Kesin && s.dogrulandiYazi]}>{guvenRozeti}</Text>
                </View>
              ) : null}
            </View>
            {vadeSatiri ? (
              <Text style={s.vadeNot} numberOfLines={2}>
                {kesimGunuYok ? "Kesim günü gir → vade avantajı" : "Vade avantajı"}
              </Text>
            ) : (
              <>
                <Text style={s.baslik} numberOfLines={acik ? undefined : 2}>
                  {satir.baslik}
                </Text>
                {!!satir.aciklama && <Text style={s.aciklama}>{satir.aciklama}</Text>}
              </>
            )}
          </View>
          <View style={s.rozet}>
            <TutarYazi
              metin={satir.etiket}
              boy={17}
              renk={birinci ? TEMA.para.kazanc : TEMA.para.notr}
            />
            <Text style={s.etiketAlt}>{legacyTeyit ? "ön hesap" : satir.etiketAlt}</Text>
          </View>
        </View>

        {acik && (
          <View style={s.detay}>
            {satir.hesap.map((adim, i) => (
              <View key={`hesap-${i}`} style={s.hesapSatir}>
                <Text style={s.hesapIsaret}>=</Text>
                <Text style={s.hesap}>{adim}</Text>
              </View>
            ))}
            {satir.sadeKosullar.map((k, i) => (
              <View key={i} style={s.kosulSatir}>
                <Text style={s.kosulIsaret}>•</Text>
                <Text style={s.kosul}>{k}</Text>
              </View>
            ))}
            {satir.digerFirsat > 0 && (
              <Text style={s.diger}>Bu kartın bu kategoride {satir.digerFirsat} fırsatı daha var.</Text>
            )}
          </View>
        )}
      </Basilabilir>

      {/* Köprü — Mehmet abi isteği: kampanya sayfasına GÖRÜNÜR yönlendirme */}
      {satir.kaynakUrl && (
        <View style={s.kopruSatir}>
          {satir.katilimGerekli && (
            <Text style={s.kopruUyari}>⚠ Önce bankanın sayfasından katıl</Text>
          )}
          <Basilabilir
            stil={s.kopruButon}
            onPress={() => Linking.openURL(satir.kaynakUrl!)}
            accessibilityRole="link"
            accessibilityLabel={`${satir.baslik} resmî kampanya sayfasını aç`}
            accessibilityHint="Tarayıcıda açılır"
            hareketAzalt={hareketAzalt}
          >
            <Text style={s.kopruYazi}>{teyitGerekli ? "Koşulu kontrol et ↗" : "Resmî kaynak ↗"}</Text>
          </Basilabilir>
        </View>
      )}
    </Animated.View>
  );
}

const s = StyleSheet.create({
  satir: {
    borderRadius: TEMA.yaricap.orta,
    // Normal satır = kat1 yüzeyi (zeminden bir ton açık)
    backgroundColor: TEMA.yuzey.kat1.zemin,
    borderWidth: 1,
    borderColor: TEMA.yuzey.kat1.kenar,
    padding: TEMA.bosluk.m,
    marginBottom: TEMA.bosluk.m,
    overflow: "hidden", // şampiyon degradesi köşe yarıçapına saygı duysun
  },
  // Şampiyon = kazanan yüzeyi + altın kontur (ışıkla öne çıkar)
  satirBirinci: { backgroundColor: TEMA.yuzey.kazanan.zemin, borderColor: TEMA.yuzey.kazanan.kenar },
  satirAnaEylem: { borderRadius: TEMA.yaricap.orta },
  ust: { flexDirection: "row", alignItems: "center", gap: TEMA.bosluk.m },
  miniKartSar: { position: "relative" },
  siraRozet: {
    position: "absolute",
    top: -6,
    left: -6,
    width: 22,
    height: 22,
    borderRadius: 11,
    alignItems: "center",
    justifyContent: "center",
    borderWidth: 1.5,
    borderColor: TEMA.yuzey.kat1.zemin,
  },
  siraAltin: { backgroundColor: TEMA.renk.altin },
  siraGumus: { backgroundColor: TEMA.renk.gumusSoluk },
  siraYazi: { color: TEMA.renk.zeminKoyu, fontWeight: "800", fontSize: 11 },
  orta: { flex: 1 },
  programSatir: { flexDirection: "row", alignItems: "center", gap: 6 },
  tonNokta: { width: 8, height: 8, borderRadius: 4 },
  program: { color: TEMA.renk.yazi, fontSize: 15, fontWeight: "700" },
  urunKimlik: { flex: 1 },
  urunAlt: { color: TEMA.renk.yaziEnSoluk, fontSize: 9.5, marginTop: 1 },
  logo: { width: 58, height: 18 },
  logoYatay: { width: 78, height: 15 },
  katilRozet: {
    borderRadius: TEMA.yaricap.hap,
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    paddingHorizontal: 6,
    paddingVertical: 1,
  },
  katilYazi: { color: TEMA.renk.altinAcik, fontSize: 9, fontWeight: "600" },
  teyitRozet: {
    borderRadius: TEMA.yaricap.hap,
    borderWidth: 1,
    borderColor: TEMA.renk.uyariKenar,
    backgroundColor: TEMA.renk.uyariZemin,
    paddingHorizontal: 6,
    paddingVertical: 2,
  },
  teyitYazi: { color: TEMA.renk.uyari, fontSize: 8.5, fontWeight: "800" },
  dogrulandiRozet: {
    borderColor: TEMA.renk.basariKenar,
    backgroundColor: TEMA.renk.basariZemin,
  },
  dogrulandiYazi: { color: TEMA.renk.basari },
  baslik: { color: TEMA.renk.yaziSoluk, fontSize: 12, marginTop: 2, lineHeight: 16 },
  vadeNot: { color: TEMA.renk.yaziSoluk, fontSize: 12, marginTop: 2, lineHeight: 16 },
  aciklama: { color: TEMA.renk.yaziEnSoluk, fontSize: 10.5, marginTop: 2 },
  rozet: { alignItems: "flex-end", minWidth: 74 },
  etiketAlt: { color: TEMA.renk.yaziEnSoluk, fontSize: 9.5, marginTop: 1 },
  detay: {
    marginTop: TEMA.bosluk.m,
    borderTopWidth: 1,
    borderColor: TEMA.renk.panelKenar,
    paddingTop: TEMA.bosluk.m,
    gap: 4,
  },
  hesapSatir: { flexDirection: "row", gap: 6, alignItems: "flex-start" },
  hesapIsaret: { color: TEMA.renk.altinAcik, fontSize: 11.5, fontWeight: "800" },
  hesap: { color: TEMA.renk.altinAcik, fontSize: 11, lineHeight: 16, flex: 1 },
  kosulSatir: { flexDirection: "row", gap: 6 },
  kosulIsaret: { color: TEMA.renk.altinAcik, fontSize: 12 },
  kosul: { color: TEMA.renk.yaziSoluk, fontSize: 11.5, lineHeight: 16, flex: 1 },
  diger: { color: TEMA.renk.yaziEnSoluk, fontSize: 10.5, fontStyle: "italic", marginTop: 2 },
  kopruSatir: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "flex-end",
    gap: 10,
    marginTop: TEMA.bosluk.s,
  },
  kopruUyari: { color: TEMA.renk.yaziEnSoluk, fontSize: 10, flexShrink: 1 },
  kopruButon: {
    minHeight: 44,
    borderRadius: TEMA.yaricap.hap,
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    backgroundColor: "rgba(212,175,55,0.08)",
    paddingHorizontal: 12,
    paddingVertical: 10,
    justifyContent: "center",
  },
  kopruYazi: { color: TEMA.renk.altinAcik, fontSize: 11.5, fontWeight: "700" },
});
