/**
 * NE:       Sinematik kart-ekleme akışı orkestratörü — BANKA seç → o bankanın KART destesi → cüzdan.
 * NEDEN:    Mehmet abi (2026-07-21): "app basit sekmeli seçim programı olmamalı; önce banka sonra
 *           kart." KartUrunuSecici'nin (tek ekran arama+filtre+galeri) yerine geçer; App'in
 *           state/motor/AsyncStorage katmanına DOKUNMAZ — birebir aynı prop sözleşmesi.
 * NASIL:    İçeride 2 sahne (adım "banka" | "kartlar") + akış-içi yumuşak fade geçiş (Animated).
 *           Üstte cüzdan özeti (seçili kartlar + kesim günü + kaldır) daima görünür. BankaSecimi ve
 *           KartDestesi alt sahneleri yönetir; seçim üst bileşene onSeciliDegistir ile iletilir.
 * YAN ETKİ: Yalnız üst bileşenin verdiği yerel durumu değiştirir; ağ/dosya erişimi yok.
 */
import { useEffect, useMemo, useRef, useState } from "react";
/*
 * NE: Kullanılmayan `ScrollView` importunu kaldırır.
 * NEDEN: Tam yayın kapısındaki no-unused denetimi ölü importu hata sayar.
 * NASIL: Yalnız bileşende kullanılan React Native yüzeylerini bırakır.
 * YAN ETKİ: Kart ekleme akışı ve kaydırma davranışı değişmez.
 */
import { Alert, Animated, Platform, StyleSheet, Text, TextInput, View } from "react-native";
import katalogVerisi from "../veri/v3-esleme-katalogu.json";
import type { KartUrunuEslemeKaydi, V3EslemeKatalogu } from "../motor/v3Gecis";
import { urunProgramAdi } from "../motor/kartKatalogu";
import { kartGorunumu } from "../marka/markalar";
import { EASING } from "../hareket";
import { dokunsalSecim } from "../dokunsal";
import { bankaAc, bankaKoprusu } from "../veri/bankaKopru";
import { TEMA } from "../tema";
import { KrediKarti } from "./KrediKarti";
import { BankaSecimi } from "./BankaSecimi";
import { KartDestesi } from "./KartDestesi";
import { Basilabilir } from "./Basilabilir";

const KATALOG = katalogVerisi as unknown as V3EslemeKatalogu;

interface Props {
  seciliIds: string[];
  kesimGunleri: Record<string, string>;
  onSeciliDegistir: (ids: string[]) => void;
  onKesimDegistir: (productId: string, gun: string) => void;
  hareketAzalt?: boolean;
  /** Kart üzerinde gösterilecek kullanıcı adı (cihazda; numara/finansal veri değil) */
  kartSahibi?: string;
}

/**
 * Cüzdan destesi — Apple-Wallet metaforu: kartlar dikey üst üste biner, her kart öncekinin altından
 * ~kayma kadar peek eder (üst kimlik şeridi/logo görünür), öndeki (dip) kart TAM görünür + çevrilebilir.
 * Bir peek karta dokun → o kart translateY yay ile öne süzülür, üsttekiler yukarı akar.
 * TEK yay dili + yalnız translateY animasyonu (native, jank yok); altın YOK (kanon: altın yalnız kazanana).
 */
function CuzdanDestesi({
  urunler,
  kesimGunleri,
  onKesimDegistir,
  onKaldir,
  hareketAzalt,
  kartSahibi,
}: {
  urunler: KartUrunuEslemeKaydi[];
  kesimGunleri: Record<string, string>;
  onKesimDegistir: (productId: string, gun: string) => void;
  onKaldir: (productId: string) => void;
  hareketAzalt: boolean;
  kartSahibi?: string;
}) {
  const n = urunler.length;
  // Overdraw kalkanı: en çok 6 kart çiz (her KrediKarti gradyan+doku+parlama çizer); fazlası "+k" rozet
  const GORUNEN = 6;
  const fazla = Math.max(0, n - GORUNEN);
  const gorunen = fazla > 0 ? urunler.slice(fazla) : urunler;
  const gn = gorunen.length;

  const [genislik, setGenislik] = useState(330);
  const EN = genislik;
  const BOY = EN * (54 / 85.6); // KrediKarti ISO oranı (KrediKarti.tsx:140)
  const kayma = Math.round(BOY * 0.34); // üst kimlik şeridini açığa çıkaran kademe (~logo yüksekliği)
  const collapsedH = BOY + (gn - 1) * kayma; // absolute çocuklar kabı büyütmez → AÇIK yükseklik

  const [aktif, setAktif] = useState(gn - 1);
  const aktifG = Math.min(Math.max(0, aktif), Math.max(0, gn - 1)); // render-arası güvenli index
  // Ekle/sil → en son kart öne (dip); silme sonrası bayat index de bu yolla düzelir
  useEffect(() => {
    setAktif(gn - 1);
  }, [gn]);

  // Konum: id anahtarlı Animated.Value (yeni id collapsedH'ten alttan girer; gidenler temizlenir → leak yok)
  const konumRef = useRef<Map<string, Animated.Value>>(new Map());
  function konum(id: string): Animated.Value {
    let v = konumRef.current.get(id);
    if (!v) {
      v = new Animated.Value(collapsedH); // alttan "cüzdana kayma" girişi
      konumRef.current.set(id, v);
    }
    return v;
  }
  useEffect(() => {
    const idler = new Set(gorunen.map((u) => u.id));
    for (const k of Array.from(konumRef.current.keys())) {
      if (!idler.has(k)) konumRef.current.delete(k);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [gn]);

  // slot: aktif → dip (gn-1, tam görünür); diğerleri orijinal sırayı koruyarak 0..gn-2
  const slot = useMemo(() => {
    const r = new Array<number>(gn);
    let k = 0;
    for (let i = 0; i < gn; i++) if (i !== aktifG) r[i] = k++;
    if (gn > 0) r[aktifG] = gn - 1;
    return r;
  }, [aktifG, gn]);

  // Deste hareketi: tek yay dili (TEMA.yay.sahne), YALNIZ translateY → native, 60fps, reflow yok
  useEffect(() => {
    if (hareketAzalt) {
      gorunen.forEach((u, i) => konum(u.id).setValue(slot[i] * kayma));
      return;
    }
    const a = Animated.parallel(
      gorunen.map((u, i) =>
        Animated.spring(konum(u.id), {
          toValue: slot[i] * kayma,
          useNativeDriver: Platform.OS !== "web",
          ...TEMA.yay.sahne,
        })
      )
    );
    a.start();
    return () => a.stop();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [aktifG, gn, kayma, hareketAzalt]);

  // Aksiyon şeridi: öndeki kart değişince yumuşak cross-fade (native opacity)
  const aksiyonOpak = useRef(new Animated.Value(1)).current;
  useEffect(() => {
    if (hareketAzalt) {
      aksiyonOpak.setValue(1);
      return;
    }
    aksiyonOpak.setValue(0);
    const a = Animated.timing(aksiyonOpak, {
      toValue: 1,
      duration: 180,
      easing: EASING.cikis,
      useNativeDriver: true,
    });
    a.start();
    return () => a.stop();
  }, [aktifG, aksiyonOpak, hareketAzalt]);

  const ondeki = gorunen[aktifG];

  return (
    <View style={s.ozet}>
      <View style={s.ozetBaslikSatir}>
        <Text style={s.ozetBaslik}>Cüzdanındaki kartlar</Text>
        <Text style={s.adet}>{n}</Text>
      </View>
      <View
        style={[s.desteKap, { height: collapsedH }]}
        onLayout={(e) => {
          const w = e.nativeEvent.layout.width;
          if (w > 0 && Math.abs(w - genislik) > 1) setGenislik(w);
        }}
      >
        {gorunen.map((urun, i) => {
          const issuer = KATALOG.issuers.find((x) => x.id === urun.issuerId);
          const gorunum = kartGorunumu(urun.programId, urun.id);
          const onde = i === aktifG;
          const kart = (
            <KrediKarti
              program={urunProgramAdi(KATALOG, urun)}
              urunAdi={urun.name}
              markaAdi={gorunum.markaAdi}
              odemeAgi={urun.paymentNetworks[0]}
              kartGradyan={gorunum.kartGradyan}
              kartYaziKoyu={gorunum.kartYaziKoyu}
              imza={gorunum.imza}
              altEtiket={issuer?.aliases[0] ?? issuer?.name}
              en={EN}
              cevirilebilir={onde}
              hareketAzalt={hareketAzalt}
              kartSahibi={kartSahibi}
              arkaNot={
                kesimGunleri[urun.id] ? `Kesim günü: ${kesimGunleri[urun.id]}` : "Kesim günü girilmedi"
              }
            />
          );
          return (
            <Animated.View
              key={urun.id}
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                top: 0,
                zIndex: slot[i],
                elevation: slot[i],
                transform: [{ translateY: konum(urun.id) }],
              }}
            >
              {onde ? (
                kart
              ) : (
                <Basilabilir
                  onPress={() => {
                    dokunsalSecim();
                    setAktif(i);
                  }}
                  hareketAzalt={hareketAzalt}
                  accessibilityRole="button"
                  accessibilityLabel={`${urun.name} kartını öne getir`}
                >
                  {kart}
                </Basilabilir>
              )}
            </Animated.View>
          );
        })}
        {fazla > 0 ? (
          <View style={s.fazlaRozet} pointerEvents="none">
            <Text style={s.fazlaYazi}>+{fazla}</Text>
          </View>
        ) : null}
      </View>
      {ondeki ? (
        <Animated.View style={{ opacity: aksiyonOpak }}>
          <View style={s.ozetAksiyon}>
            <View style={s.kesimAlan}>
              <Text style={s.kesimEtiket}>Kesim günü</Text>
              <TextInput
                style={s.kesimGiris}
                value={kesimGunleri[ondeki.id] ?? ""}
                onChangeText={(deger) => onKesimDegistir(ondeki.id, deger.replace(/\D/g, "").slice(0, 2))}
                keyboardType="number-pad"
                maxLength={2}
                placeholder="—"
                placeholderTextColor={TEMA.renk.yaziEnSoluk}
                accessibilityLabel={`${ondeki.name} kesim günü`}
              />
            </View>
            <Text style={s.ondekiAd} numberOfLines={1}>
              {ondeki.name}
            </Text>
            <Basilabilir
              onPress={() => {
                const soru = `${ondeki.name} cüzdanından çıkarılsın mı?`;
                // Alert.alert WEB'de çalışmaz (no-op) → tarayıcı confirm'i; native'de Alert. Kaldırma her yerde çalışsın.
                if (Platform.OS === "web") {
                  if (typeof window !== "undefined" && window.confirm(soru)) onKaldir(ondeki.id);
                } else {
                  Alert.alert("Kartı kaldır?", soru, [
                    { text: "Vazgeç", style: "cancel" },
                    { text: "Kaldır", style: "destructive", onPress: () => onKaldir(ondeki.id) },
                  ]);
                }
              }}
              stil={s.kaldir}
              hareketAzalt={hareketAzalt}
              accessibilityRole="button"
              accessibilityLabel={`${ondeki.name} kartını cüzdandan kaldır`}
            >
              <Text style={s.kaldirYazi}>Kaldır</Text>
            </Basilabilir>
          </View>
          {bankaKoprusu(ondeki.issuerId) ? (
            <Basilabilir
              onPress={() => bankaAc(ondeki.issuerId)}
              stil={s.bankaAcCuzdan}
              hareketAzalt={hareketAzalt}
              accessibilityRole="button"
              accessibilityLabel={`${bankaKoprusu(ondeki.issuerId)!.ad} uygulamasını aç`}
              accessibilityHint="Bankanın kendi uygulaması açılır; ödeme burada yapılmaz"
            >
              <Text style={s.bankaAcCuzdanYazi}>
                {bankaKoprusu(ondeki.issuerId)!.ad} uygulamasını aç ↗
              </Text>
            </Basilabilir>
          ) : null}
        </Animated.View>
      ) : null}
    </View>
  );
}

export function KartEklemeAkisi({
  seciliIds,
  kesimGunleri,
  onSeciliDegistir,
  onKesimDegistir,
  hareketAzalt = false,
  kartSahibi,
}: Props) {
  const [adim, setAdim] = useState<"banka" | "kartlar">("banka");
  const [issuerId, setIssuerId] = useState<string | null>(null);
  const gec = useRef(new Animated.Value(1)).current;

  function gecis(yeniAdim: "banka" | "kartlar", yeniIssuer: string | null) {
    if (hareketAzalt) {
      setAdim(yeniAdim);
      setIssuerId(yeniIssuer);
      return;
    }
    Animated.timing(gec, { toValue: 0, duration: 130, useNativeDriver: true }).start(({ finished }) => {
      // Geçiş yarıda kesildiyse (hızlı çift-dokunuş) commit etme — yoksa A sahnesi flash'lar (adversarial O2).
      if (!finished) return;
      setAdim(yeniAdim);
      setIssuerId(yeniIssuer);
      Animated.timing(gec, {
        toValue: 1,
        duration: 220,
        easing: EASING.cikis,
        useNativeDriver: true,
      }).start();
    });
  }

  const seciliUrunler = seciliIds
    .map((id) => KATALOG.cardProducts.find((urun) => urun.id === id && urun.active))
    .filter((urun): urun is KartUrunuEslemeKaydi => Boolean(urun));

  function kaldir(productId: string) {
    onSeciliDegistir(seciliIds.filter((id) => id !== productId));
  }

  return (
    <View style={s.kap}>
      {seciliUrunler.length > 0 && (
        <CuzdanDestesi
          urunler={seciliUrunler}
          kesimGunleri={kesimGunleri}
          onKesimDegistir={onKesimDegistir}
          onKaldir={kaldir}
          hareketAzalt={hareketAzalt}
          kartSahibi={kartSahibi}
        />
      )}

      <Animated.View
        style={{
          opacity: gec,
          transform: [{ translateY: gec.interpolate({ inputRange: [0, 1], outputRange: [8, 0] }) }],
        }}
      >
        {adim === "banka" || !issuerId ? (
          <BankaSecimi
            seciliIds={seciliIds}
            onSec={(id) => gecis("kartlar", id)}
            hareketAzalt={hareketAzalt}
          />
        ) : (
          <KartDestesi
            issuerId={issuerId}
            seciliIds={seciliIds}
            onSeciliDegistir={onSeciliDegistir}
            onGeri={() => gecis("banka", null)}
            hareketAzalt={hareketAzalt}
          />
        )}
      </Animated.View>

      <Text style={s.guven}>
        Kart numarası, son dört hane ve CVV istenmez. Yalnız seçtiğin resmî ürün kimliği cihazında kalır.
      </Text>
    </View>
  );
}

