/**
 * NE:       Kategori + sekme ikonları — her seçimi anlatan premium bespoke SVG seti
 * NEDEN:    Mehmet abi isteği: "seçim sekmelerinde bile o sekmeyi anlatan HQ resimler" —
 *           jenerik emoji/placeholder yasak; her piksel kasıtlı, tutarlı çizgi dili
 * NASIL:    24×24 viewBox, tek çizgi ağırlığı (1.8), yuvarlak uç; renk prop ile
 *           (altın=seçili, gümüş=pasif). Fill değil stroke — hafif, tema-duyarlı.
 * YAN ETKİ: Yok
 */
import type { ReactNode } from "react";
import Svg, { Circle, Path, Rect, Line } from "react-native-svg";

const KG = 1.8; // çizgi ağırlığı — tutarlı

function S({ boy = 22, children }: { boy?: number; children: ReactNode }) {
  return (
    <Svg width={boy} height={boy} viewBox="0 0 24 24" fill="none">
      {children}
    </Svg>
  );
}

const ortak = (renk: string) => ({
  stroke: renk,
  strokeWidth: KG,
  strokeLinecap: "round" as const,
  strokeLinejoin: "round" as const,
});

/** Kategori/sekme koduna göre bespoke ikon */
export function KategoriIkon({ kod, renk, boy = 22 }: { kod: string; renk: string; boy?: number }) {
  const o = ortak(renk);
  switch (kod) {
    case "market":
      return (
        <S boy={boy}>
          <Path d="M4 6h2l1.5 10.5A1.5 1.5 0 0 0 9 18h8a1.5 1.5 0 0 0 1.5-1.3L20 8H6.2" {...o} />
          <Circle cx="9.5" cy="20.5" r="1.2" fill={renk} />
          <Circle cx="17" cy="20.5" r="1.2" fill={renk} />
        </S>
      );
    case "akaryakit":
      return (
        <S boy={boy}>
          <Path d="M5 21V5a2 2 0 0 1 2-2h5a2 2 0 0 1 2 2v16M4 21h11" {...o} />
          <Path d="M6 10h6" {...o} />
          <Path d="M14 8l3 3v6a1.6 1.6 0 0 0 3 0V9l-2.5-2.5" {...o} />
        </S>
      );
    case "e-ticaret":
      return (
        <S boy={boy}>
          <Path d="M4 5h2l1 4m0 0l1.5 6.5A1.5 1.5 0 0 0 10 17h7a1.5 1.5 0 0 0 1.4-1L20 9H7z" {...o} />
          <Path d="M9 21h9" {...o} />
          <Path d="M13 9l1.5 1.5L18 7" {...o} />
        </S>
      );
    case "giyim":
      return (
        <S boy={boy}>
          <Path d="M8.5 4L5 7l2 2 1-.8V20h8V8.2l1 .8 2-2-3.5-3-2 1.5a3 3 0 0 1-4 0z" {...o} />
        </S>
      );
    case "elektronik":
      return (
        <S boy={boy}>
          <Rect x="7" y="2.5" width="10" height="19" rx="2.5" {...o} />
          <Line x1="10.5" y1="18.5" x2="13.5" y2="18.5" {...o} />
        </S>
      );
    case "seyahat":
      return (
        <S boy={boy}>
          <Path d="M2 15l9-2 4-8a1.5 1.5 0 0 1 2.7 1.2L16 12l4 1.5-1 3-5-1-3.5 4L9 19l1-3-5-1z" {...o} />
        </S>
      );
    case "vergi-kamu":
      return (
        <S boy={boy}>
          <Path d="M4 9l8-5 8 5M5 9v9h14V9M4 20h16" {...o} />
          <Line x1="9" y1="12" x2="9" y2="16" {...o} />
          <Line x1="15" y1="12" x2="15" y2="16" {...o} />
        </S>
      );
    case "ev-yasam":
      return (
        <S boy={boy}>
          <Path d="M4 11l8-6 8 6M6 10v9h5v-5h2v5h5v-9" {...o} />
        </S>
      );
    case "saglik":
      return (
        <S boy={boy}>
          <Path d="M12 20s-7-4.5-7-10a4 4 0 0 1 7-2.5A4 4 0 0 1 19 10c0 5.5-7 10-7 10z" {...o} />
          <Path d="M12 9v4M10 11h4" {...o} />
        </S>
      );
    case "egitim":
      return (
        <S boy={boy}>
          <Path d="M2 9l10-4 10 4-10 4z" {...o} />
          <Path d="M6 11v4c0 1.5 3 3 6 3s6-1.5 6-3v-4M22 9v5" {...o} />
        </S>
      );
    case "eglence":
      return (
        <S boy={boy}>
          <Rect x="3" y="5" width="18" height="14" rx="2" {...o} />
          <Path d="M10 9l5 3-5 3z" {...o} />
        </S>
      );
    // Alt sekmeler
    case "karar":
      // Hangi Kart? = kazanan/seçilen kartın kararı — kart + onay rozeti.
      // (Eski yıldız 'favori/derecelendirme' çağrıştırıyordu; UX değerlendirmesi 2026-07-21.)
      return (
        <S boy={boy}>
          <Rect x="2.5" y="6" width="13" height="9.5" rx="2" {...o} />
          <Path d="M2.5 9.7h13" {...o} />
          <Circle cx="17.5" cy="16" r="4.4" {...o} />
          <Path d="M15.5 16l1.4 1.4 2.5-2.8" {...o} />
        </S>
      );
    case "firsatlar":
      return (
        <S boy={boy}>
          <Path d="M4 8a2 2 0 0 1 2-2h8l6 6-8 8-6-6z" {...o} />
          <Circle cx="9" cy="11" r="1.3" fill={renk} />
        </S>
      );
    case "cuzdan":
      return (
        <S boy={boy}>
          <Rect x="3" y="6" width="18" height="13" rx="2.5" {...o} />
          <Path d="M3 10h18M16 14h2" {...o} />
        </S>
      );
    case "karnem":
      return (
        <S boy={boy}>
          <Path d="M4 20h16" {...o} />
          <Path d="M7 20v-5M12 20V8M17 20v-9" {...o} />
        </S>
      );
    default: // diger
      return (
        <S boy={boy}>
          <Circle cx="6" cy="12" r="1.4" fill={renk} />
          <Circle cx="12" cy="12" r="1.4" fill={renk} />
          <Circle cx="18" cy="12" r="1.4" fill={renk} />
        </S>
      );
  }
}
