/**
 * NE:       KartAkıl karar motoru — "bu kategoride hangi kartla ödemeliyim?" hesabı
 * NEDEN:    Uygulamanın kalbi: kampanyayı net TL'ye çevirip kartları sıralar;
 *           kampanya yoksa bile boş dönmez (mimari kural 8 — vade cevabı)
 * NASIL:    Saf fonksiyon, cihazda çalışır (KVKK — kural 7: hiçbir girdi sunucuya
 *           gitmez). Sıra: net TL kazanç ↓ → taksit ay ↓ → vade erteleme ↓.
 *           Kademeli kampanyada sepete uyan EN YÜKSEK kademe; eşik altındaysa
 *           kazanç 0 ama satır düşmez ("X TL'ye tamamla, Y ₺ kazan" fırsat notu).
 * YAN ETKİ: Yok — girdiyi değiştirmez, IO yapmaz; ürün kimliği üst katmanda eklenebilir.
 */
import type { KararSatiri, TaslakKampanya } from "../tipler";
import { yerelTakvimTarihi } from "./tarih";

export interface KararGirdi {
  uyeProgramlar: string[];
  kategori: string;
  sepetTL: number;
  /** Program → ekstre kesim günü (1-31, opsiyonel) — vade cevabının anahtarı */
  kesimGunleri?: Record<string, number | undefined>;
  /** Test edilebilirlik için sabitlenebilir bugün (ISO tarih) */
  bugun?: string;
}

const SON_ODEME_EK_GUN = 10; // kesimden son ödemeye tipik ek süre (TR pratiği)

function bugunIso(girdi: KararGirdi): string {
  return girdi.bugun ?? yerelTakvimTarihi();
}

function tarihGecerli(k: TaslakKampanya, bugun: string): boolean {
  if (k.baslangic && bugun < k.baslangic) return false;
  if (k.bitis && bugun > k.bitis) return false;
  return true;
}

function paraYaz(tl: number): string {
  return tl.toLocaleString("tr-TR", { maximumFractionDigits: 0 });
}

/** Tek kampanyanın bu sepetteki net TL kazancı + fırsat notu + "nasıl hesapladım" adımları.
 *  hesap[] = güven kanıtı (kullanıcı matematiği kendi gözüyle görür — sıralama satılmaz). */
export function kazancHesapla(
  k: TaslakKampanya,
  sepetTL: number
): { kazancTL: number; not: string | null; hesap: string[] } {
  if (k.fayda_tipi === "taksit") {
    return { kazancTL: 0, not: null, hesap: [`${k.fayda_degeri} taksit — faiz/vade avantajı, doğrudan TL kazancı yok`] };
  }
  if (k.fayda_birimi === "yuzde") {
    if (k.min_tutar != null && sepetTL < k.min_tutar)
      return { kazancTL: 0, not: `${paraYaz(k.min_tutar)} ₺ üzeri geçerli`, hesap: [`Kampanya ${paraYaz(k.min_tutar)} ₺ ve üzeri geçerli; sepetin ${paraYaz(sepetTL)} ₺`] };
    const kaz = Math.round((sepetTL * k.fayda_degeri) / 100);
    return {
      kazancTL: kaz,
      not: null,
      hesap: [`%${k.fayda_degeri} × ${paraYaz(sepetTL)} ₺ = ${paraYaz(kaz)} ₺`],
    };
  }
  // TL bazlı fayda
  if (k.kademeler && k.kademeler.length > 0) {
    const sirali = [...k.kademeler].sort((a, b) => a.min_tutar - b.min_tutar);
    let uyan: (typeof sirali)[number] | null = null;
    for (const kd of sirali) if (sepetTL >= kd.min_tutar) uyan = kd;
    if (uyan) {
      const hesap = [`${paraYaz(sepetTL)} ₺ sepet, ${paraYaz(uyan.min_tutar)} ₺ kademesine giriyor → ${paraYaz(uyan.kazanc_tl)} ₺`];
      if (uyan.sart) hesap.push(uyan.sart);
      return { kazancTL: uyan.kazanc_tl, not: null, hesap };
    }
    const ilk = sirali[0];
    return {
      kazancTL: 0,
      not: `Sepeti ${paraYaz(ilk.min_tutar)} ₺'ye tamamla → ${paraYaz(ilk.kazanc_tl)} ₺ kazan`,
      hesap: [`En düşük kademe ${paraYaz(ilk.min_tutar)} ₺; sepetin ${paraYaz(sepetTL)} ₺ — henüz eşiğin altında`],
    };
  }
  if (k.min_tutar != null && sepetTL < k.min_tutar)
    return {
      kazancTL: 0,
      not: `Sepeti ${paraYaz(k.min_tutar)} ₺'ye tamamla → ${paraYaz(k.fayda_degeri)} ₺ kazan`,
      hesap: [`Kampanya ${paraYaz(k.min_tutar)} ₺ ve üzeri geçerli; sepetin ${paraYaz(sepetTL)} ₺`],
    };
  return {
    kazancTL: k.fayda_degeri,
    not: null,
    hesap: [
      k.min_tutar != null
        ? `${paraYaz(k.min_tutar)} ₺+ harcamaya sabit ${paraYaz(k.fayda_degeri)} ₺`
        : `Bu kampanyada sabit ${paraYaz(k.fayda_degeri)} ₺ kazanç`,
    ],
  };
}

/** Kesim gününden bugüne göre toplam erteleme günü (kesime kalan + son ödeme payı) */
export function ertelemeGunu(kesimGunu: number, bugun: string): number {
  const t = new Date(bugun + "T00:00:00");
  const buAyKesim = new Date(t.getFullYear(), t.getMonth(), kesimGunu);
  const kesim =
    buAyKesim > t ? buAyKesim : new Date(t.getFullYear(), t.getMonth() + 1, kesimGunu);
  const gunFarki = Math.round((kesim.getTime() - t.getTime()) / 86400000);
  return gunFarki + SON_ODEME_EK_GUN;
}

export function kararSatirlariniSirala(satirlar: KararSatiri[]): KararSatiri[] {
  return [...satirlar].sort((a, b) => {
    if (b.kazancTL !== a.kazancTL) return b.kazancTL - a.kazancTL;
    const oncelik = { kampanya: 0, taksit: 1, vade: 2 } as const;
    if (oncelik[a.tip] !== oncelik[b.tip]) return oncelik[a.tip] - oncelik[b.tip];
    const ag = parseInt(a.etiket, 10) || 0;
    const bg = parseInt(b.etiket, 10) || 0;
    return bg - ag;
  });
}

export function kararVer(kampanyalar: TaslakKampanya[], girdi: KararGirdi): KararSatiri[] {
  const bugun = bugunIso(girdi);
  const uye = new Set(girdi.uyeProgramlar);

  const adaylar = kampanyalar.filter(
    (k) => uye.has(k.program) && k.kategori === girdi.kategori && tarihGecerli(k, bugun)
  );

  // Her programı bu kategorideki EN İYİ fırsatıyla temsil et
  const satirlar: KararSatiri[] = [];
  const kampanyaliProgramlar = new Set<string>();
  for (const program of girdi.uyeProgramlar) {
    const kendi = adaylar.filter((k) => k.program === program);
    if (kendi.length === 0) continue;
    kampanyaliProgramlar.add(program);

    const puanlanmis = kendi
      .map((k) => ({ k, h: kazancHesapla(k, girdi.sepetTL) }))
      .sort((a, b) => {
        if (b.h.kazancTL !== a.h.kazancTL) return b.h.kazancTL - a.h.kazancTL;
        const at = a.k.fayda_tipi === "taksit" ? a.k.fayda_degeri : 0;
        const bt = b.k.fayda_tipi === "taksit" ? b.k.fayda_degeri : 0;
        return bt - at;
      });
    const enIyi = puanlanmis[0];
    const taksitMi = enIyi.k.fayda_tipi === "taksit";

    satirlar.push({
      program,
      tip: taksitMi ? "taksit" : "kampanya",
      kazancTL: enIyi.h.kazancTL,
      etiket: taksitMi
        ? `${enIyi.k.fayda_degeri} taksit`
        : enIyi.h.kazancTL > 0
          ? `+${paraYaz(enIyi.h.kazancTL)} ₺`
          : "fırsat",
      etiketAlt: taksitMi
        ? "vade avantajı"
        : enIyi.h.kazancTL > 0
          ? enIyi.k.fayda_tipi === "puan"
            ? "puan karşılığı"
            : "net kazanç"
          : "eşiğe yakın",
      baslik: enIyi.k.baslik,
      aciklama: enIyi.h.not ?? (enIyi.k.bitis ? `Son gün: ${tarihYaz(enIyi.k.bitis)}` : ""),
      sadeKosullar: enIyi.k.sade_kosullar,
      katilimGerekli: enIyi.k.katilim_gerekli,
      kaynakUrl: enIyi.k.kaynak_url,
      digerFirsat: kendi.length - 1,
      hesap: enIyi.h.hesap,
    });
  }

  // Kampanyasız üye programlar → vade cevabı (asla boş ekran yok)
  for (const program of girdi.uyeProgramlar) {
    if (kampanyaliProgramlar.has(program)) continue;
    const kesim = girdi.kesimGunleri?.[program];
    if (kesim && kesim >= 1 && kesim <= 31) {
      const gun = ertelemeGunu(kesim, bugun);
      satirlar.push({
        program,
        tip: "vade",
        kazancTL: 0,
        etiket: `${gun} gün`,
        etiketAlt: "ödeme ertelenir",
        baslik: "Bu kategoride kampanya yok — vade avantajı",
        aciklama: `Ekstre kesimi ayın ${kesim}'i: bugünkü harcaman yaklaşık ${gun} gün sonra ödenir.`,
        sadeKosullar: [],
        katilimGerekli: false,
        kaynakUrl: null,
        digerFirsat: 0,
        hesap: [`Kesim günü ${kesim} → kesime kalan gün + ~${SON_ODEME_EK_GUN} gün son ödeme = ${gun} gün erteleme`],
      });
    } else {
      satirlar.push({
        program,
        tip: "vade",
        kazancTL: 0,
        etiket: "—",
        etiketAlt: "kampanya yok",
        baslik: "Bu kategoride güncel kampanya bulunamadı",
        aciklama: "Cüzdanında bu kartın kesim gününü girersen vade avantajını hesaplarım.",
        sadeKosullar: [],
        katilimGerekli: false,
        kaynakUrl: null,
        digerFirsat: 0,
        hesap: [],
      });
    }
  }

  return kararSatirlariniSirala(satirlar);
}

function tarihYaz(iso: string): string {
  const [y, a, g] = iso.split("-").map(Number);
  const AYLAR = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"];
  return `${g} ${AYLAR[(a ?? 1) - 1]} ${y}`;
}
