/**
 * NE:       Foto-gerçekçi ve hareket azaltma ayarına uyumlu kredi kartı bileşeni.
 * NEDEN:    Mehmet abi isteği: "kredi kartları iyice gerçekmiş gibi olsun" — ekrana
 *           bakınca gerçek plastik/metal kart hissi (chip, temassız, doku, ışık); çevrilen yüzün
 *           durumu web ekran okuyucusundan da saklanmamalıdır.
 * NASIL:    ISO 7810 oran (85.6/54); ürün adı/ağına göre marka veya metal degrade →
 *           guilloché doku → ışık parlaması → chip + temassız + ağ + maskeli numara.
 *           Gerçek kart NUMARASI/CVV YOK (kırmızı çizgi) — numara maskeli desen,
 *           uygulamanın veri tutmadığının görünür kanıtı. Reduce Motion açıksa yüz anında değişir;
 *           ekran okuyucuya açık yüz ve sıradaki eylem dinamik düğme etiketiyle bildirilir.
 * YAN ETKİ: Dokunulan çevrilebilir kart yerel animasyon durumunu değiştirir; ağ/depo erişimi yoktur
 *           ve düğme etiketi görsel yerleşimi etkilemez.
 */
import { memo, useId, useRef, useState } from "react";
import { Animated, Image, Platform, StyleSheet, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import Svg, {
  Defs,
  Ellipse,
  Line,
  LinearGradient as SvgLinearGradient,
  Path,
  Pattern,
  RadialGradient,
  Rect,
  Stop,
} from "react-native-svg";
import { PROGRAM_MARKA, type ProgramMarka, type KartImza } from "../marka/markalar";
import { AgLogosu, Chip, Temassiz } from "./KartParcalari";
import { dokunsalHafif } from "../dokunsal";
import { Basilabilir } from "./Basilabilir";

interface Props {
  program: string;
  urunAdi?: string;
  markaAdi?: string;
  odemeAgi?: string;
  kartGradyan?: string[];
  kartYaziKoyu?: boolean;
  /** Kartın üstünde gösterilecek durum etiketi (opsiyonel) */
  altEtiket?: string;
  /** Genişlik (yükseklik ISO orandan hesaplanır) */
  en?: number;
  soluk?: boolean;
  /** true → karta dokununca 3D döner; arka yüzde güvence + kesim günü */
  cevirilebilir?: boolean;
  /** Arka yüzde gösterilecek not (ör. "Kesim günü: 25") */
  arkaNot?: string;
  /** Sistem hareket azaltma ayarı açıkken 3B yayı atlayıp yüzü anında değiştirir. */
  hareketAzalt?: boolean;
  /** Ürüne özel imza grafiği (ör. "gezegen" = Maximiles Black). */
  imza?: KartImza;
  /** Kart üzerinde gösterilecek KART SAHİBİ adı — kullanıcının kendi adı (numara/finansal veri DEĞİL) */
  kartSahibi?: string;
}

/** Guilloché benzeri ince çapraz çizgi dokusu — metal/plastik yüzey hissi */
function Doku({ renk = "#ffffff" }: { renk?: string }) {
  return (
    <Svg style={StyleSheet.absoluteFill} width="100%" height="100%">
      <Defs>
        <Pattern id="guilloche" x="0" y="0" width="14" height="14" patternUnits="userSpaceOnUse">
          <Line x1="0" y1="0" x2="14" y2="14" stroke={renk} strokeWidth="0.5" opacity="0.09" />
          <Line x1="14" y1="0" x2="0" y2="14" stroke={renk} strokeWidth="0.5" opacity="0.06" />
        </Pattern>
      </Defs>
      <Rect x="0" y="0" width="100%" height="100%" fill="url(#guilloche)" />
    </Svg>
  );
}

/**
 * Maximiles Black imza grafiği — telif-güvenli "gezegen halkası" ışık yayı.
 * NEDEN: Mehmet abi'nin gerçek kartındaki alt-kavis Satürn/gezegen deseninin HİSSİNİ verir; birebir
 *        marka sanatı DEĞİL (kendi vektör yorumumuz) → telif-güvenli, keskin, ölçeklenir.
 */
function GezegenYayi({ en }: { en: number }) {
  const boy = en * (54 / 85.6);
  return (
    <Svg
      style={StyleSheet.absoluteFill}
      width="100%"
      height="100%"
      viewBox={`0 0 ${en} ${boy}`}
      pointerEvents="none"
    >
      <Defs>
        <RadialGradient id="gezIsik" cx="36%" cy="66%" r="55%" fx="33%" fy="60%">
          <Stop offset="0" stopColor="#eaf3ff" stopOpacity="0.85" />
          <Stop offset="0.38" stopColor="#9fbde0" stopOpacity="0.28" />
          <Stop offset="1" stopColor="#0a1830" stopOpacity="0" />
        </RadialGradient>
        <SvgLinearGradient id="gezHalka" x1="0" y1="0" x2="1" y2="0">
          <Stop offset="0" stopColor="#ffffff" stopOpacity="0" />
          <Stop offset="0.4" stopColor="#f3f8ff" stopOpacity="0.95" />
          <Stop offset="0.62" stopColor="#c8dbf2" stopOpacity="0.5" />
          <Stop offset="1" stopColor="#ffffff" stopOpacity="0" />
        </SvgLinearGradient>
      </Defs>
      {/* sol-orta ışık patlaması (gezegen ufku parıltısı) */}
      <Ellipse cx={en * 0.4} cy={boy * 0.68} rx={en * 0.46} ry={boy * 0.46} fill="url(#gezIsik)" />
      {/* Satürn benzeri paralel halka arkları (alttan kavisli) */}
      <Path
        d={`M ${-en * 0.08} ${boy * 0.88} Q ${en * 0.46} ${boy * 0.5} ${en * 1.08} ${boy * 0.8}`}
        stroke="url(#gezHalka)"
        strokeWidth={en * 0.022}
        fill="none"
      />
      <Path
        d={`M ${-en * 0.08} ${boy * 0.98} Q ${en * 0.44} ${boy * 0.58} ${en * 1.08} ${boy * 0.9}`}
        stroke="url(#gezHalka)"
        strokeWidth={en * 0.013}
        fill="none"
        opacity={0.75}
      />
      <Path
        d={`M ${-en * 0.08} ${boy * 1.08} Q ${en * 0.48} ${boy * 0.66} ${en * 1.08} ${boy * 1.02}`}
        stroke="url(#gezHalka)"
        strokeWidth={en * 0.032}
        fill="none"
        opacity={0.5}
      />
    </Svg>
  );
}

function KrediKartiTemel({
  program,
  urunAdi,
  markaAdi,
  odemeAgi,
  kartGradyan,
  kartYaziKoyu,
  altEtiket,
  en = 300,
  soluk,
  cevirilebilir,
  arkaNot,
  hareketAzalt = false,
  imza,
  kartSahibi,
}: Props) {
  const marka: ProgramMarka | undefined = PROGRAM_MARKA[program];
  const boy = en * (54 / 85.6);
  // Benzersiz, SABİT SVG gradient id (render gövdesinde sayaç mutasyonu = impure; useId saf). Web'de
  // url(#id) fragmanı kırılmasın diye useId'nin ":" karakterleri temizlenir.
  const isikId = `kartIsik-${useId().replace(/[^a-zA-Z0-9]/g, "")}`;
  const gradyan = kartGradyan ?? marka?.kartGradyan ?? ["#2a2d35", "#16181d", "#0e1014"];
  const yaziKoyu = kartYaziKoyu ?? marka?.kartYaziKoyu ?? false;
  const numaraRengi = yaziKoyu ? "rgba(20,22,28,0.55)" : "rgba(255,255,255,0.72)";
  const agli = odemeAgi ?? marka?.aglar?.[0] ?? "Visa";
  // Kart yüzü açık renkse (Axess turuncu) yazı koyu, değilse beyaz — kimlik NET okunmalı
  const yaziRengi = yaziKoyu ? "#1a1a1a" : "#ffffff";
  const yr = en * 0.055;

  const [arkada, setArkada] = useState(false);
  const flip = useRef(new Animated.Value(0)).current;
  function cevir() {
    dokunsalHafif();
    const hedef = arkada ? 0 : 1;
    setArkada(!arkada);
    if (hareketAzalt) {
      flip.setValue(hedef);
      return;
    }
    Animated.spring(flip, {
      toValue: hedef,
      useNativeDriver: Platform.OS !== "web",
      damping: 15,
      stiffness: 90,
      mass: 1,
    }).start();
  }

  // ÖN YÜZ katmanları
  const onYuz = (
    <>
      <LinearGradient
        colors={gradyan as [string, string, ...string[]]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={[StyleSheet.absoluteFill, soluk && { opacity: 0.72 }]}
      />
      <Doku renk={yaziKoyu ? "#000000" : "#ffffff"} />
      {imza === "gezegen" && <GezegenYayi en={en} />}
      {/* IŞIK SİSTEMİ — gerçek kart hissi (OLED'de parlar): üst-sol radyal ışık kaynağı */}
      <Svg style={StyleSheet.absoluteFill} width="100%" height="100%" pointerEvents="none">
        <Defs>
          <RadialGradient id={isikId} cx="24%" cy="10%" r="90%">
            <Stop offset="0" stopColor="#ffffff" stopOpacity={yaziKoyu ? 0.32 : 0.22} />
            <Stop offset="0.45" stopColor="#ffffff" stopOpacity="0.035" />
            <Stop offset="1" stopColor="#ffffff" stopOpacity="0" />
          </RadialGradient>
        </Defs>
        <Rect x="0" y="0" width="100%" height="100%" fill={`url(#${isikId})`} />
      </Svg>
      {/* Specular sweep — kartın üzerinden geçen parlak ışık şeridi (kaliteyi vurgular) */}
      <LinearGradient
        colors={["transparent", "transparent", "rgba(255,255,255,0.28)", "rgba(255,255,255,0.06)", "transparent"]}
        locations={[0, 0.3, 0.4, 0.5, 0.72]}
        start={{ x: 0.1, y: 0 }}
        end={{ x: 0.85, y: 1 }}
        style={StyleSheet.absoluteFill}
        pointerEvents="none"
      />
      {/* Alt-sağ derinlik — kart kalın/oturmuş görünür (yapmacık düzlük gider) */}
      <LinearGradient
        colors={["transparent", "transparent", "rgba(0,0,0,0.32)"]}
        locations={[0, 0.5, 1]}
        start={{ x: 0.3, y: 0.1 }}
        end={{ x: 1, y: 1 }}
        style={StyleSheet.absoluteFill}
        pointerEvents="none"
      />
      <View style={[s.icerik, { padding: en * 0.062 }]}>
        <View style={s.ustSatir}>
          {marka && !markaAdi ? (
            // Beyaz/ters logo doğrudan kart yüzünde — gerçek fiziksel kart gibi (kutu YOK)
            <Image
              source={marka.logo}
              style={{ width: en * (marka.yatayMi ? 0.66 : 0.5), height: en * 0.15 }}
              resizeMode="contain"
            />
          ) : (
            <Text style={[s.programAd, { color: yaziRengi }]}>{markaAdi ?? program}</Text>
          )}
          <Temassiz boy={en * 0.08} renk={yaziRengi} />
        </View>
        <View style={s.ortaSatir}>
          <Chip boy={en * 0.1} />
        </View>
        <Text
          accessible={false}
          importantForAccessibility="no"
          style={[s.numara, { color: numaraRengi, fontSize: en * 0.05 }]}
        >
          ••••  ••••  ••••  ••••
        </Text>
        {kartSahibi ? (
          <Text numberOfLines={1} style={[s.kartSahibi, { color: yaziRengi, fontSize: en * 0.044 }]}>
            {kartSahibi.toLocaleUpperCase("tr-TR")}
          </Text>
        ) : null}
        <View style={s.enAltSatir}>
          <View>
            <Text
              numberOfLines={1}
              adjustsFontSizeToFit
              style={[s.programWordmark, { color: yaziRengi, fontSize: en * 0.064, maxWidth: en * 0.7 }]}
            >
              {urunAdi ?? program}
            </Text>
            {altEtiket && <Text style={[s.altEtiket, { color: numaraRengi }]}>{altEtiket}</Text>}
          </View>
          <AgLogosu ag={agli} boy={en * 0.08} />
        </View>
        {cevirilebilir && (
          <Text style={[s.cevirIpucu, { color: numaraRengi }]}>dokun → arka yüz</Text>
        )}
      </View>
    </>
  );

  // ARKA YÜZ — manyetik şerit + güvence (veri tutmuyoruz kanıtı) + kesim notu
  const arkaYuz = (
    <>
      <LinearGradient
        colors={[gradyan[gradyan.length - 1], gradyan[0]]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={StyleSheet.absoluteFill}
      />
      <View style={[s.manyetik, { top: en * 0.09 }]} />
      <View style={[s.arkaIcerik, { padding: en * 0.062, paddingTop: en * 0.28 }]}>
        <View style={s.imzaSerit}>
          <Text style={s.imzaYazi}>KartAkıl</Text>
        </View>
        <Text style={[s.arkaGuvence, { fontSize: en * 0.038 }]}>
          Kart numaranı ve harcamanı TUTMAYIZ. Yalnız seçtiğin kart ürününü biliriz.
        </Text>
        {arkaNot && <Text style={[s.arkaNot, { fontSize: en * 0.042 }]}>{arkaNot}</Text>}
        <Text style={[s.arkaProgram, { fontSize: en * 0.05 }]}>{urunAdi ?? program}</Text>
      </View>
    </>
  );

  if (!cevirilebilir) {
    return (
      <View style={[{ width: en, height: boy }, s.golge]}>
        <View style={[s.kart, { borderRadius: yr }]}>{onYuz}</View>
      </View>
    );
  }

  const onDon = flip.interpolate({ inputRange: [0, 1], outputRange: ["0deg", "180deg"] });
  const arkaDon = flip.interpolate({ inputRange: [0, 1], outputRange: ["180deg", "360deg"] });

  return (
    <Basilabilir
      onPress={cevir}
      hareketAzalt={hareketAzalt}
      accessibilityRole="button"
      accessibilityLabel={`${urunAdi ?? program} kartı, ${
        arkada ? "arka yüz açık, ön yüzü göster" : "ön yüz açık, arka yüzü göster"
      }`}
    >
      <View style={[{ width: en, height: boy }, s.golge]}>
        <Animated.View
          style={[
            s.kart,
            StyleSheet.absoluteFill,
            { borderRadius: yr, backfaceVisibility: "hidden", transform: [{ perspective: 900 }, { rotateY: onDon }] },
          ]}
        >
          {onYuz}
        </Animated.View>
        <Animated.View
          style={[
            s.kart,
            StyleSheet.absoluteFill,
            { borderRadius: yr, backfaceVisibility: "hidden", transform: [{ perspective: 900 }, { rotateY: arkaDon }] },
          ]}
        >
          {arkaYuz}
        </Animated.View>
      </View>
    </Basilabilir>
  );
}

/** React.memo: count-up sırasında (props sabitken) ağır SVG/gradient kartı yeniden çizilmesin —
 *  premium "yağ gibi" akış. Props çoğunlukla ilkel (program/urunAdi/en) → shallow eşitlik tutar. */
export const KrediKarti = memo(KrediKartiTemel);

const s = StyleSheet.create({
  golge: {
    shadowColor: "#000",
    shadowOffset: { width: 0, height: 8 },
    shadowOpacity: 0.45,
    shadowRadius: 14,
    elevation: 8,
  },
  kart: {
    flex: 1,
    overflow: "hidden",
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: "rgba(255,255,255,0.16)",
  },
  icerik: { flex: 1, justifyContent: "space-between" },
  ustSatir: { flexDirection: "row", justifyContent: "space-between", alignItems: "flex-start" },
  programAd: { color: "#fff", fontSize: 16, fontWeight: "800" },
  ortaSatir: { flexDirection: "row", alignItems: "center", gap: 10 },
  numara: { fontWeight: "700", letterSpacing: 1, fontVariant: ["tabular-nums"] },
  kartSahibi: { fontWeight: "600", letterSpacing: 1.4, marginTop: 4, opacity: 0.92 },
  enAltSatir: { flexDirection: "row", justifyContent: "space-between", alignItems: "flex-end" },
  programWordmark: {
    fontWeight: "800",
    letterSpacing: 0.6,
    textShadowColor: "rgba(0,0,0,0.25)",
    textShadowOffset: { width: 0, height: 1 },
    textShadowRadius: 2,
  },
  altEtiket: { fontSize: 9, fontWeight: "600", letterSpacing: 1.2, opacity: 0.85, marginTop: 1 },
  cevirIpucu: { fontSize: 9, textAlign: "right", marginTop: 4, opacity: 0.7 },
  // Arka yüz
  manyetik: {
    position: "absolute",
    left: 0,
    right: 0,
    height: "22%",
    backgroundColor: "rgba(0,0,0,0.82)",
  },
  arkaIcerik: { flex: 1, justifyContent: "flex-start", gap: 8 },
  imzaSerit: {
    height: 22,
    backgroundColor: "rgba(255,255,255,0.9)",
    borderRadius: 3,
    justifyContent: "center",
    paddingHorizontal: 8,
  },
  imzaYazi: { color: "#1a1a1a", fontSize: 11, fontWeight: "700", fontStyle: "italic" },
  arkaGuvence: { color: "rgba(255,255,255,0.85)", lineHeight: 15 },
  arkaNot: { color: "#fff", fontWeight: "700", marginTop: 2 },
  arkaProgram: { color: "rgba(255,255,255,0.6)", fontWeight: "800", marginTop: "auto", textAlign: "right" },
});
