/**
 * NE:       Geçiş dönemindeki onaylı eski kampanyaları gerçek ürün cüzdanı için ayrı ayrı sıralar.
 * NEDEN:    Aynı kampanya ailesindeki iki kart tek “Bonus” satırında birleşirse ürün/ağ farkı kaybolur
 *           ve kullanıcının sahip olmadığı kart kapsamı kazanan gibi görünebilir.
 * NASIL:    Her seçili ürün için yalnız kanıtlı grup kesişimi olan kampanyaları eski TL motoruna verir;
 *           ürün adı/banka/ağ kimliğini sonuca ekler ve bütün gerçek kart satırlarını birlikte sıralar.
 * YAN ETKİ: Yok; girdi dizilerini değiştirmez, IO veya ağ erişimi yapmaz.
 */
import type { KararSatiri, TaslakKampanya } from "../tipler";
import { kararSatirlariniSirala, kararVer } from "./karar";
import {
  eskiKampanyaKartUrununeUyarMi,
  kartUrunuKampanyaProgramAdlari,
} from "./kartKatalogu";
import type { V3EslemeKatalogu } from "./v3Gecis";

export interface GercekKartKararGirdi {
  productIds: string[];
  kategori: string;
  sepetTL: number;
  kesimGunleri: Record<string, string>;
  bugun?: string;
}

export function gercekKartlarlaKararVer(
  kampanyalar: TaslakKampanya[],
  katalog: V3EslemeKatalogu,
  girdi: GercekKartKararGirdi
): KararSatiri[] {
  const satirlar = girdi.productIds.flatMap((productId) => {
    const urun = katalog.cardProducts.find((aday) => aday.id === productId && aday.active);
    if (!urun) return [];
    const programAdlari = kartUrunuKampanyaProgramAdlari(katalog, [productId]);
    const gun = parseInt(girdi.kesimGunleri[productId] ?? "", 10);
    const programKesimleri = Object.fromEntries(
      programAdlari.map((program) => [program, gun >= 1 && gun <= 31 ? gun : undefined])
    );
    const urunKampanyalari = kampanyalar.filter((kampanya) =>
      eskiKampanyaKartUrununeUyarMi(kampanya, katalog, productId)
    );
    const issuer = katalog.issuers.find((aday) => aday.id === urun.issuerId);
    return kararVer(urunKampanyalari, {
      uyeProgramlar: programAdlari,
      kategori: girdi.kategori,
      sepetTL: girdi.sepetTL,
      kesimGunleri: programKesimleri,
      bugun: girdi.bugun,
    }).map((satir) => ({
      ...satir,
      cardProductId: urun.id,
      cardProductName: urun.name,
      cardProgramId: urun.programId,
      issuerName: issuer?.aliases[0] ?? issuer?.name,
      paymentNetwork: urun.paymentNetworks[0],
    }));
  });

  return kararSatirlariniSirala(satirlar);
}
