/**
 * NE:       Görünür güven şeridi — KartAkıl'ın en büyük diferansiyatörünü (kırmızı çizgiler) vitrine taşır.
 * NEDEN:    Arkadaş geri bildirimi: "güven vermiyor, gerçek mi belli değil." Güven bilgisi bugüne dek
 *           modal arkasında SAKLIYDI (en yakın rakip Dekart bunu manşet yapıyor). Ama güven YAZI-VAAZ ile
 *           değil (Mehmet abi: "programın kendisiyle") — bu yüzden şerit boş iddia değil, programın
 *           GERÇEKTE yaptığı/yapmadığı davranışların kanıtı: kart no gerçekten sorulmaz, konum gerçekten
 *           cihazda kalır, sıralama gerçekten satılmaz. Kullanıcı bunu deneyimiyle doğrulayabilir.
 * NASIL:    4 kısa davranış-kanıtı, gümüş/nötr (altın DEĞİL — kanon: altın yalnız kazanç), ölçülü sönük
 *           ama okunur; tümü tek dokunuşla ayrıntı ekranını açar. Emoji yok, ✓ sembolü + sade tipografi.
 * YAN ETKİ: onDetay çağrısı Güven ekranını (modal) açar; şerit yerleşim akışında ince bir bant tutar.
 */
import { StyleSheet, Text, View } from "react-native";
import { TEMA } from "../tema";
import { Basilabilir } from "./Basilabilir";

const KANITLAR = [
  "Kart numaranı istemez",
  "Konumun cihazda kalır",
  "Sıralama satılık değil",
  "Banka parası almaz",
];

export function GuvenSeridi({
  onDetay,
  hareketAzalt = false,
  sikistir = false,
}: {
  /** Ayrıntı ekranını açar (neyi istemez / neyi tutmaz — tam liste) */
  onDetay?: () => void;
  hareketAzalt?: boolean;
  /** Açılış gibi dar bağlamda üst/alt boşluğu kısar */
  sikistir?: boolean;
}) {
  const icerik = (
    <>
      <View style={s.rozetler}>
        {KANITLAR.map((k) => (
          <View key={k} style={s.rozet}>
            <Text style={s.tik}>✓</Text>
            <Text style={s.rozetYazi}>{k}</Text>
          </View>
        ))}
      </View>
      {onDetay ? <Text style={s.detayIpucu}>Nasıl koruyorum? ›</Text> : null}
    </>
  );

  /*
   * NE: Güven şeridini yalnız gerçekten ayrıntı açabildiğinde buton olarak sunar.
   * NEDEN: Açılış ekranında onDetay yokken tıklanmayan şerit ekran okuyucuya yanlışlıkla “buton” deniyordu.
   * NASIL: Salt bilgi halinde View, etkileşimli ana ekranda aynı Basilabilir ve erişilebilirlik etiketi kullanılır.
   * YAN ETKİ: Görsel düzen değişmez; yalnız ekran okuyucu semantiği gerçek davranışla eşleşir.
   */
  if (!onDetay) {
    return <View style={[s.serit, sikistir && s.seritSik]}>{icerik}</View>;
  }

  return (
    <Basilabilir
      stil={[s.serit, sikistir && s.seritSik]}
      onPress={onDetay}
      hareketAzalt={hareketAzalt}
      accessibilityRole="button"
      accessibilityLabel="KartAkıl güvenlik ilkeleri — kart numaranı istemez, konumun cihazda kalır, sıralama satılık değildir, banka parası almaz. Ayrıntı için dokun."
    >
      {icerik}
    </Basilabilir>
  );
}

const s = StyleSheet.create({
  serit: {
    alignSelf: "stretch",
    borderRadius: TEMA.yaricap.orta,
    borderWidth: 1,
    borderColor: TEMA.yuzey.kat1.kenar,
    backgroundColor: TEMA.yuzey.kat1.zemin,
    paddingVertical: TEMA.bosluk.s,
    paddingHorizontal: TEMA.bosluk.m,
    gap: 6,
  },
  seritSik: { paddingVertical: 6 },
  rozetler: { flexDirection: "row", flexWrap: "wrap", columnGap: TEMA.bosluk.m, rowGap: 4 },
  rozet: { flexDirection: "row", alignItems: "center", gap: 5 },
  // Gümüş/nötr — altın DEĞİL (kanon: altın yalnız kazanç + kazanan + ana CTA)
  tik: { color: TEMA.renk.gumus, fontSize: 11, fontWeight: "800" },
  rozetYazi: { color: TEMA.renk.gumus, fontSize: 11.5, fontWeight: "600" },
  detayIpucu: { color: TEMA.renk.yaziEnSoluk, fontSize: 10.5, fontWeight: "600" },
});
