/**
 * NE:       Kampanya veri bütünlüğü KALKANI — bozuk/absürd kampanya kullanıcıya ULAŞMASIN (#2 kırmızı çizgi).
 * NEDEN:    "Kusursuz çalışma" + yol haritası: LLM/scraper ya da elle veri bir gün bozuk üretebilir
 *           ("1₺ öde 500 kazan" absürdü, %120 iade, eşik>tavan, bozuk tarih). Bunlar motora sızarsa
 *           kullanıcıya YANLIŞ TL gösterilir. Bu saf kalkan, gösterimden ÖNCE eler (fail-closed).
 * NASIL:    Saf fonksiyon; alan/aralık/mantık kontrolleri. "Absürd" = kazanç, eşik harcamayı aşıyor
 *           (banka zarar etmez → veri hatası). Gerçek 29 kampanyaya karşı 0 yanlış-ret ile doğrulandı
 *           (kampanyaSaglik.test.ts). Yeni program/veri eklenince test bunu korur.
 * YAN ETKİ: Yok — girdiyi değiştirmez, IO yapmaz.
 */
import type { FaydaTipi, TaslakKampanya } from "../tipler";

const FAYDA_TIPLERI: FaydaTipi[] = ["taksit", "puan", "indirim", "hediye", "cashback"];
const ISO_GUN = /^\d{4}-\d{2}-\d{2}$/u;

function metinDolu(x: unknown): x is string {
  return typeof x === "string" && x.trim().length > 0;
}
function sonluSayi(x: unknown): x is number {
  return typeof x === "number" && Number.isFinite(x);
}

export interface SaglikSonuc {
  saglikli: boolean;
  sebep?: string;
}

export function kampanyaSagligi(k: unknown): SaglikSonuc {
  if (k == null || typeof k !== "object") return { saglikli: false, sebep: "kayıt nesne değil" };
  const a = k as Partial<TaslakKampanya>;

  if (!metinDolu(a.program)) return { saglikli: false, sebep: "program boş" };
  if (!metinDolu(a.baslik)) return { saglikli: false, sebep: "başlık boş" };
  if (!metinDolu(a.kategori)) return { saglikli: false, sebep: "kategori boş" };
  if (!metinDolu(a.kaynak_url)) return { saglikli: false, sebep: "kaynak_url boş" };
  if (typeof a.fayda_tipi !== "string" || !FAYDA_TIPLERI.includes(a.fayda_tipi as FaydaTipi))
    return { saglikli: false, sebep: "fayda_tipi geçersiz" };
  if (!sonluSayi(a.fayda_degeri) || a.fayda_degeri < 0)
    return { saglikli: false, sebep: "fayda_degeri geçersiz" };

  const birim = a.fayda_birimi;
  if (a.fayda_tipi === "taksit") {
    if (birim !== "ay" || !Number.isInteger(a.fayda_degeri) || a.fayda_degeri < 1 || a.fayda_degeri > 60)
      return { saglikli: false, sebep: "taksit ay 1-60 değil" };
  } else if (birim === "yuzde") {
    if (a.fayda_degeri <= 0 || a.fayda_degeri > 100)
      return { saglikli: false, sebep: "yüzde 0-100 dışı" };
  } else if (birim !== "tl") {
    return { saglikli: false, sebep: "fayda_birimi geçersiz" };
  }

  // min_tutar + absürd (sabit TL kazanç eşik harcamayı aşamaz → banka zarar etmez, veri hatası)
  if (a.min_tutar != null) {
    if (!sonluSayi(a.min_tutar) || a.min_tutar < 0) return { saglikli: false, sebep: "min_tutar geçersiz" };
    if (birim === "tl" && a.min_tutar > 0 && a.fayda_degeri > a.min_tutar)
      return { saglikli: false, sebep: "absürd: sabit kazanç eşiği aşıyor (>%100 iade)" };
  }

  // kademeler — boş dizi = KADEMESİZ kampanya (tek sabit fayda), GEÇERLİDİR; yalnız "dizi değil" reddedilir.
  if (a.kademeler != null) {
    if (!Array.isArray(a.kademeler))
      return { saglikli: false, sebep: "kademeler dizi değil" };
    for (const kd of a.kademeler) {
      if (!kd || typeof kd !== "object") return { saglikli: false, sebep: "kademe nesne değil" };
      if (!sonluSayi(kd.min_tutar) || kd.min_tutar < 0)
        return { saglikli: false, sebep: "kademe min_tutar geçersiz" };
      if (!sonluSayi(kd.kazanc_tl) || kd.kazanc_tl < 0)
        return { saglikli: false, sebep: "kademe kazanc_tl geçersiz" };
      if (kd.min_tutar > 0 && kd.kazanc_tl > kd.min_tutar)
        return { saglikli: false, sebep: "absürd kademe: kazanç eşiği aşıyor" };
    }
  }

  // tarih
  if (a.baslangic != null && !(metinDolu(a.baslangic) && ISO_GUN.test(a.baslangic)))
    return { saglikli: false, sebep: "başlangıç tarihi bozuk" };
  if (a.bitis != null && !(metinDolu(a.bitis) && ISO_GUN.test(a.bitis)))
    return { saglikli: false, sebep: "bitiş tarihi bozuk" };
  if (metinDolu(a.baslangic) && metinDolu(a.bitis) && a.baslangic > a.bitis)
    return { saglikli: false, sebep: "başlangıç bitişten sonra" };

  return { saglikli: true };
}

export function kampanyaSaglikli(k: unknown): boolean {
  return kampanyaSagligi(k).saglikli;
}

/** Sağlıklı olanları döndürür; elenen(ler) için opsiyonel geri çağrı (dev-günlük için). */
export function saglikliKampanyalar<T>(
  kampanyalar: readonly T[],
  elenince?: (kampanya: T, sebep: string) => void
): T[] {
  const sonuc: T[] = [];
  for (const k of kampanyalar) {
    const s = kampanyaSagligi(k);
    if (s.saglikli) sonuc.push(k);
    else elenince?.(k, s.sebep ?? "bilinmiyor");
  }
  return sonuc;
}
