/**
 * NE:       Platformdan bağımsız kampanya gösterim çekirdeğini React Native mağaza logosuna bağlar.
 * NEDEN:    Saf metin/takvim testleri görsel dosya `require` çağrılarına takılmadan çalışırken mevcut
 *           `goster` dışa aktarım sözleşmesi ve uygulamanın gerçek ImageSourcePropType tipi korunmalı.
 * NASIL:    Saf yardımcıları aynı modülden yeniden dışa aktarır; yalnız mağaza eşleşmesine statik logo
 *           haritasını verir ve çalışma zamanındaki bozuk kampanya nesnesini güvenle null'a düşürür.
 * YAN ETKİ: Mevcut doğru metinler ve dışa aktarılan fonksiyon imzaları korunur; girdi değiştirilmez.
 */
import type { ImageSourcePropType } from "react-native";
import type { TaslakKampanya } from "../tipler";
import { MAGAZA_LOGO } from "../marka/magazaLogolari";
import { bilinenMagazayiBul } from "./gosterSaf";

export { faydaAlt, faydaYaz, kalanGun, tarihYaz } from "./gosterSaf";

/** Kampanyanın işyerlerinden logosu bilinen İLKİNİ bul (yoksa null) —
 *  "kampanya nerede" görselini üretir; başlıkta mağaza adı da geçebiliyor ama logo daha güçlü */
export function kampanyaMagaza(
  k: TaslakKampanya
): { ad: string; logo: ImageSourcePropType } | null {
  const aday: unknown = k;
  const isyerleri = aday != null && typeof aday === "object"
    ? (aday as Partial<TaslakKampanya>).isyerleri
    : undefined;
  return bilinenMagazayiBul(isyerleri, MAGAZA_LOGO);
}
