/**
 * NE:       Kampanya faydası, takvim günü ve mağaza eşleşmesi için platformdan bağımsız gösterim çekirdeği.
 * NEDEN:    NaN, negatif değer, bozuk ISO günü veya tanınmayan mağaza kullanıcıya sahte/bozuk bilgi
 *           göstermemeli; React Native görsel `require` bağımlılığı da Node birim testini engellememeli.
 * NASIL:    Sayılar sonlu ve alan sınırlarıyla (%1-100, taksit 1-60) doğrulanır; varsayılan bugün Türkiye
 *           günü, tarih farkı UTC gün sırasıdır; mağaza adları Türkçe karakter/boşluk farkına dayanıklıdır.
 * YAN ETKİ: Girdileri değiştirmez; saat dilimi ayarını değiştirmez, ağ/dosya/React Native erişimi yapmaz.
 */
import type { FaydaBirimi, FaydaTipi, TaslakKampanya } from "../tipler";
import { turkiyeTakvimTarihi } from "./tarih";

const GUN_MS = 86_400_000;
const ISO_TAKVIM_GUNU = /^(\d{4})-(\d{2})-(\d{2})$/u;
const AYLAR = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"] as const;
const FAYDA_BILGISI_YOK = "Fayda bilgisi yok";

const PARA_BICIMI = new Intl.NumberFormat("tr-TR", {
  maximumFractionDigits: 2,
});
const YUZDE_BICIMI = new Intl.NumberFormat("tr-TR", {
  maximumFractionDigits: 2,
});

const FAYDA_ALT_METNI = {
  taksit: "vade avantajı",
  puan: "puan karşılığı",
  cashback: "iade",
  hediye: "hediye",
  indirim: "indirim",
} satisfies Record<FaydaTipi, string>;

interface TakvimGunu {
  yil: number;
  ay: number;
  gun: number;
  utcGunSirasi: number;
}

interface GecerliFayda {
  tip: FaydaTipi;
  birim: FaydaBirimi;
  deger: number;
}

function takvimGununuOku(deger: unknown): TakvimGunu | null {
  if (typeof deger !== "string") return null;
  const eslesme = ISO_TAKVIM_GUNU.exec(deger);
  if (!eslesme) return null;

  const yil = Number(eslesme[1]);
  const ay = Number(eslesme[2]);
  const gun = Number(eslesme[3]);
  if (yil < 1000 || yil > 9999 || ay < 1 || ay > 12 || gun < 1 || gun > 31) return null;

  const tarih = new Date(0);
  tarih.setUTCHours(0, 0, 0, 0);
  tarih.setUTCFullYear(yil, ay - 1, gun);
  if (
    tarih.getUTCFullYear() !== yil ||
    tarih.getUTCMonth() !== ay - 1 ||
    tarih.getUTCDate() !== gun
  ) {
    return null;
  }

  return { yil, ay, gun, utcGunSirasi: Math.trunc(tarih.getTime() / GUN_MS) };
}

function kampanyaAlanlari(kampanya: TaslakKampanya): Partial<TaslakKampanya> | null {
  const aday: unknown = kampanya;
  return aday != null && typeof aday === "object" ? (aday as Partial<TaslakKampanya>) : null;
}

function faydaTipiMi(deger: unknown): deger is FaydaTipi {
  return typeof deger === "string" && Object.prototype.hasOwnProperty.call(FAYDA_ALT_METNI, deger);
}

function gosterilebilirSayi(deger: unknown): deger is number {
  return (
    typeof deger === "number" &&
    Number.isFinite(deger) &&
    deger >= 0 &&
    !Object.is(deger, -0) &&
    Math.abs(deger) <= Number.MAX_SAFE_INTEGER
  );
}

function faydaBilgisiniOku(k: TaslakKampanya): GecerliFayda | null {
  const kampanya = kampanyaAlanlari(k);
  const tip = kampanya?.fayda_tipi;
  const birim = kampanya?.fayda_birimi;
  const deger = kampanya?.fayda_degeri;
  if (!faydaTipiMi(tip) || !gosterilebilirSayi(deger)) return null;

  if (tip === "taksit") {
    return birim === "ay" && Number.isSafeInteger(deger) && deger > 0 && deger <= 60
      ? { tip, birim, deger }
      : null;
  }
  if (birim === "yuzde") {
    return deger > 0 && deger <= 100 ? { tip, birim, deger } : null;
  }
  return birim === "tl" ? { tip, birim, deger } : null;
}

export function faydaYaz(k: TaslakKampanya): string {
  const fayda = faydaBilgisiniOku(k);
  if (!fayda) return FAYDA_BILGISI_YOK;
  if (fayda.tip === "taksit") return `${fayda.deger} taksit`;
  if (fayda.birim === "yuzde") return `%${YUZDE_BICIMI.format(fayda.deger)}`;
  if (fayda.birim === "tl") return `${PARA_BICIMI.format(fayda.deger)} ₺`;
  return FAYDA_BILGISI_YOK;
}

export function faydaAlt(k: TaslakKampanya): string {
  const fayda = faydaBilgisiniOku(k);
  return fayda ? FAYDA_ALT_METNI[fayda.tip] : "fayda bilgisi";
}

/** Bitişe kalan gerçek takvim günü; geçmiş veya geçersiz gün null olduğunda UI rozeti göstermez. */
export function kalanGun(bitis: string | null | undefined, bugun?: string): number | null {
  const son = takvimGununuOku(bitis);
  const baslangic = takvimGununuOku(bugun ?? turkiyeTakvimTarihi());
  if (!son || !baslangic) return null;
  const fark = son.utcGunSirasi - baslangic.utcGunSirasi;
  return fark < 0 ? null : fark;
}

export function tarihYaz(iso: string): string {
  const tarih = takvimGununuOku(iso);
  return tarih ? `${tarih.gun} ${AYLAR[tarih.ay - 1]} ${tarih.yil}` : "Tarih bilgisi yok";
}

function magazaEslemeAnahtari(deger: unknown): string | null {
  if (typeof deger !== "string") return null;
  const anahtar = deger
    .trim()
    .replace(/\s+/gu, " ")
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .toLocaleLowerCase("tr-TR")
    .replace(/ı/gu, "i");
  return anahtar || null;
}

export function bilinenMagazayiBul<TLogo>(
  isyerleri: readonly unknown[] | null | undefined,
  logolar: Readonly<Record<string, TLogo>>
): { ad: string; logo: TLogo } | null {
  if (!Array.isArray(isyerleri) || !logolar || typeof logolar !== "object") return null;

  const bilinenler = new Map<string, { ad: string; logo: TLogo }>();
  for (const [ad, logo] of Object.entries(logolar) as [string, TLogo][]) {
    const anahtar = magazaEslemeAnahtari(ad);
    if (anahtar && logo != null && !bilinenler.has(anahtar)) {
      bilinenler.set(anahtar, { ad, logo });
    }
  }

  for (const isyeri of isyerleri) {
    const anahtar = magazaEslemeAnahtari(isyeri);
    const eslesme = anahtar ? bilinenler.get(anahtar) : undefined;
    if (eslesme) return eslesme;
  }
  return null;
}
