/**
 * NE:       Tamamı insan incelemesinden geçmiş V3 yayını mobil karar satırlarına bağlayan saf gölge adaptör.
 * NEDEN:    Yeni motor ancak gerçek kart, kullanıcı teyitli mağaza ve katalogdaki açık merchant eşleşmesi
 *           birlikte varsa çalışmalı; aksi halde eksik bağlam yanlış kesinlik üretebilir.
 * NASIL:    Önce katalog kanıtlarını ve kanonik SHA-256 kimliğini doğrular; merchant/kategori adını yalnız
 *           açık katalog adı veya alias ile birebir eşler, cüzdan girdisini tahminsiz kurup tüm dizileri
 *           kopyalar ve opaque + derin dondurulmuş bağlam üretir; uygulanabilir V3 kampanyası yoksa
 *           doğrudan gerçek kartın kesim gününden tarafsız vade satırı üretir ve dönüşümden sonra
 *           vadeleri gün sayısına göre yeniden sıralayıp boş uygunsuz satırların önüne taşır.
 * YAN ETKİ: IO/ağ/depolama yapmaz; legacy kampanya sonucunu V3'e karıştırmaz.
 */
import type {
  CampaignRule,
  CampaignV3,
  CardProduct,
  DecisionInputV3,
  DecisionResultV3,
  UygunlukDurumu,
} from "../../../shared/src/index";
import type { KararGuvenDurumu, KararSatiri } from "../tipler";
import type { V3EslemeKatalogu } from "./v3Gecis";
import { kartKatalogunuDogrula } from "./kartKatalogu";
import { sha256Metni, v3KanonikJsonMetni } from "./v3KaynakHash";
import { kartlariSirala } from "./uygunluk";
import { ertelemeGunu } from "./karar";
import { turkiyeTakvimTarihi } from "./tarih";

export type V3MobilFallbackNedeni =
  | "catalog_invalid"
  | "real_cards_missing"
  | "merchant_unmatched"
  | "category_unmatched";

export interface V3MobilKararBaglami {
  merchantName: string;
  branchName: string | null;
  categoryName: string;
  basketAmountTL: number;
  productIds: string[];
  statementDays: Record<string, string>;
  evaluatedAt: string;
}

export type V3MobilGirdiSonucu =
  | {
      readonly state: "ready";
      readonly input: DecisionInputV3;
      readonly merchantId: string;
      readonly catalogVersion: string;
      readonly catalogHash: string;
    }
  | { state: "legacy_fallback"; input: null; reason: V3MobilFallbackNedeni };

export type V3HazirMobilGirdiSonucu = Extract<V3MobilGirdiSonucu, { state: "ready" }>;

export type V3MobilKararSonucu =
  | { state: "ready"; rows: KararSatiri[]; merchantId: string }
  | { state: "legacy_fallback"; rows: null; reason: V3MobilFallbackNedeni };

interface KayitliMobilKararBaglami {
  input: DecisionInputV3;
  merchantId: string;
  catalogVersion: string;
  catalogHash: string;
  frozen: boolean;
}

const uretimDogrulanmisMobilBaglamlari = new WeakMap<object, KayitliMobilKararBaglami>();
const aracDogrulanmisMobilBaglamlari = new WeakMap<object, KayitliMobilKararBaglami>();

function derinDondur<T>(deger: T): T {
  if (deger && typeof deger === "object" && !Object.isFrozen(deger)) {
    for (const altDeger of Object.values(deger as Record<string, unknown>)) derinDondur(altDeger);
    Object.freeze(deger);
  }
  return deger;
}

function mobilBaglamiKaydet(
  baglam: V3HazirMobilGirdiSonucu,
  kayitlar: WeakMap<object, KayitliMobilKararBaglami>,
  frozen: boolean
): V3HazirMobilGirdiSonucu {
  const sonuc = frozen ? derinDondur(baglam) : baglam;
  kayitlar.set(sonuc, {
    input: sonuc.input,
    merchantId: sonuc.merchantId,
    catalogVersion: sonuc.catalogVersion,
    catalogHash: sonuc.catalogHash,
    frozen,
  });
  return sonuc;
}

function kayitliMobilBaglamiAc(
  deger: unknown,
  kayitlar: WeakMap<object, KayitliMobilKararBaglami>
): V3HazirMobilGirdiSonucu | null {
  try {
    if (typeof deger !== "object" || deger === null) return null;
    const kayit = kayitlar.get(deger);
    if (!kayit) return null;
    const baglam = deger as Partial<V3HazirMobilGirdiSonucu>;
    if (
      baglam.state !== "ready" ||
      baglam.input !== kayit.input ||
      baglam.merchantId !== kayit.merchantId ||
      baglam.catalogVersion !== kayit.catalogVersion ||
      baglam.catalogHash !== kayit.catalogHash ||
      (kayit.frozen && (!Object.isFrozen(deger) || !Object.isFrozen(kayit.input)))
    ) {
      return null;
    }
    return deger as V3HazirMobilGirdiSonucu;
  } catch {
    return null;
  }
}

export function v3DogrulanmisMobilKararBaglaminiAc(
  deger: unknown
): V3HazirMobilGirdiSonucu | null {
  return kayitliMobilBaglamiAc(deger, uretimDogrulanmisMobilBaglamlari);
}

/**
 * NE:       Motor oracle testinin sentetik karar bağlamını üretimden ayrı opaque registry'ye kaydeder.
 * NEDEN:    Testler bozuk şekilleri sınarken üretim WeakMap markasını basabilirse opaque sınır anlamsızlaşır.
 * NASIL:    Yalnız hazır nesnenin kimliğini ve alan referanslarını ayrı araç registry'sine kaydeder; üretim
 *           açıcı bu kaydı hiçbir zaman görmez ve kalite kapısı sembolün üretim importunu yasaklar.
 * YAN ETKİ: Girdiyi kopyalamaz, dondurmaz veya değiştirmez; yalnız test/yayın aracı sürecinde kullanılmalıdır.
 */
export function v3MobilKararAraciIcinBaglamiKaydet(
  deger: V3MobilGirdiSonucu | null
): V3MobilGirdiSonucu | null {
  try {
    if (deger?.state === "ready") {
      mobilBaglamiKaydet(deger, aracDogrulanmisMobilBaglamlari, false);
    }
  } catch {
    return null;
  }
  return deger;
}

export function v3AracDogrulanmisMobilKararBaglaminiAc(
  deger: unknown
): V3HazirMobilGirdiSonucu | null {
  return kayitliMobilBaglamiAc(deger, aracDogrulanmisMobilBaglamlari);
}

function birebirEslemeAnahtari(deger: string): string {
  return deger.trim().normalize("NFC").toLocaleLowerCase("tr-TR");
}

function birebirKayitBul<T extends { name: string; aliases: string[] }>(
  ad: string,
  kayitlar: T[]
): T | null {
  const aranan = birebirEslemeAnahtari(ad);
  const eslesenler = kayitlar.filter((kayit) =>
    [kayit.name, ...kayit.aliases].some(
      (aday) => birebirEslemeAnahtari(aday) === aranan
    )
  );
  return eslesenler.length === 1 ? eslesenler[0] : null;
}

function ortakKartUrununeDonustur(
  urun: V3EslemeKatalogu["cardProducts"][number]
): CardProduct {
  return {
    id: urun.id,
    issuerId: urun.issuerId,
    programId: urun.programId,
    productName: urun.name,
    tier: urun.tier,
    paymentNetworks: [...urun.paymentNetworks],
    productAliases: [...urun.aliases],
    eligibilityGroupIds: [...urun.eligibilityGroupIds],
    active: urun.active,
  };
}

function kesimGunu(deger: string | undefined): number | null {
  const gun = Number.parseInt(deger ?? "", 10);
  return Number.isInteger(gun) && gun >= 1 && gun <= 31 ? gun : null;
}

/**
 * NE:       Mobil seçimlerden deterministik V3 karar motorunun güvenli girdisini üretir.
 * NEDEN:    Fuzzy merchant, varsayılan segment veya varsayılan POS gerçek olmayan uygunluk kanıtı yaratır.
 * NASIL:    Yalnız birebir katalog eşleşmesi ve tümü aktif gerçek kart ürünleriyle user_confirmed/high
 *           market, physical kanal, null POS, boş ilerleme ve boş kullanıcı segmenti kurar.
 * YAN ETKİ: Girdileri değiştirmez; koşullar eksikse neden koduyla legacy fallback döndürür.
 */
export function v3MobilKararGirdisiniOlustur(
  katalog: V3EslemeKatalogu,
  baglam: V3MobilKararBaglami
): V3MobilGirdiSonucu {
  let catalogHash: string;
  let verifiedProductIds: ReadonlySet<string>;
  try {
    const denetim = kartKatalogunuDogrula(katalog);
    const yapisalSorunVar = denetim.issues.some(
      (sorun) => sorun.code !== "group_uncovered"
    );
    if (
      yapisalSorunVar ||
      typeof katalog.version !== "string" ||
      katalog.version.length === 0 ||
      katalog.version !== katalog.version.trim()
    ) {
      return { state: "legacy_fallback", input: null, reason: "catalog_invalid" };
    }
    verifiedProductIds = new Set(denetim.verifiedProductIds);
    catalogHash = sha256Metni(v3KanonikJsonMetni(katalog));
  } catch {
    return { state: "legacy_fallback", input: null, reason: "catalog_invalid" };
  }
  const merchant = birebirKayitBul(baglam.merchantName, katalog.merchants);
  if (!merchant) {
    return { state: "legacy_fallback", input: null, reason: "merchant_unmatched" };
  }

  const kategori = birebirKayitBul(baglam.categoryName, katalog.categories);
  if (!kategori) {
    return { state: "legacy_fallback", input: null, reason: "category_unmatched" };
  }

  const tekilUrunKimlikleri = [...new Set(baglam.productIds)];
  const urunler = tekilUrunKimlikleri.map((productId) =>
    katalog.cardProducts.find((aday) => aday.id === productId && aday.active)
  );
  if (
    tekilUrunKimlikleri.length === 0 ||
    urunler.some((urun) => !urun) ||
    tekilUrunKimlikleri.some((productId) => !verifiedProductIds.has(productId)) ||
    urunler.length !== tekilUrunKimlikleri.length
  ) {
    return { state: "legacy_fallback", input: null, reason: "real_cards_missing" };
  }

  const cardProducts = urunler.map((urun) => ortakKartUrununeDonustur(urun!));
  const input: DecisionInputV3 = {
    market: {
      status: "user_confirmed",
      confidenceBand: "high",
      selected: {
        merchantId: merchant.id,
        branchId: `confirmed:${merchant.id}`,
        merchantName: merchant.name,
        branchName: baglam.branchName ?? merchant.name,
        categoryIds: [kategori.id],
        distanceM: 0,
        insideKnownBoundary: null,
        catalogFreshnessDays: Number.MAX_SAFE_INTEGER,
        priorConfirmations: 0,
        confidence: 1,
      },
      candidates: [],
      rawLocationLeavesDevice: false,
    },
    basketAmountTL: baglam.basketAmountTL,
    channel: "physical",
    posId: null,
    wallet: cardProducts.map((urun) => ({
      id: `wallet:${urun.id}`,
      cardProductId: urun.id,
      nickname: null,
      statementDay: kesimGunu(baglam.statementDays[urun.id]),
      userSegmentTags: [],
      lastFourDigits: null,
    })),
    cardProducts,
    campaignProgress: [],
    evaluatedAt: baglam.evaluatedAt,
  };
  return mobilBaglamiKaydet({
    state: "ready",
    input,
    merchantId: merchant.id,
    catalogVersion: katalog.version,
    catalogHash,
  }, uretimDogrulanmisMobilBaglamlari, true);
}

function paraYaz(tutar: number): string {
  return Math.max(0, tutar).toLocaleString("tr-TR", { maximumFractionDigits: 0 });
}

function guvenDurumu(state: UygunlukDurumu): KararGuvenDurumu {
  return state;
}

function etiketler(karar: DecisionResultV3): { etiket: string; etiketAlt: string } {
  if (karar.state === "guaranteed") {
    if (karar.nonCashBenefit) {
      return { etiket: karar.nonCashBenefit, etiketAlt: "TL kazancı değildir" };
    }
    return { etiket: `+${paraYaz(karar.guaranteedBenefitTL)} ₺`, etiketAlt: "doğrulanmış net kazanç" };
  }
  if (karar.state === "potential") {
    if (karar.nonCashBenefit) {
      return { etiket: `${karar.nonCashBenefit} olabilir`, etiketAlt: "koşula bağlı" };
    }
    return {
      etiket: `+${paraYaz(karar.potentialBenefitTL)} ₺'ye kadar`,
      etiketAlt: "koşula bağlı üst sınır",
    };
  }
  if (karar.state === "unknown") {
    return { etiket: "Teyit gerekli", etiketAlt: "eksik bilgi var" };
  }
  return { etiket: "Uygun fırsat yok", etiketAlt: "onaylı eşleşme yok" };
}

function tazelikEtiketi(karar: DecisionResultV3): string | null {
  if (karar.freshness === "fresh") return "kaynak güncel";
  if (karar.freshness === "aging") return "kaynak yenilenmeli";
  if (karar.freshness === "stale") return "kaynak eski";
  return null;
}

function katilimKuraliVarMi(kural: CampaignRule): boolean {
  if (kural.op === "enrollment_required") return true;
  if (kural.op === "all" || kural.op === "any") return kural.rules.some(katilimKuraliVarMi);
  if (kural.op === "not") return katilimKuraliVarMi(kural.rule);
  return false;
}

function aciklamaMetni(karar: DecisionResultV3): string {
  const anaMetin =
    karar.state === "guaranteed"
      ? "İnsan onaylı kurallar bu alışveriş bağlamında sağlanıyor."
      : karar.state === "potential"
        ? "Bu fayda ancak aşağıdaki tamamlanabilir koşullar sağlanırsa kazanılabilir."
        : karar.state === "unknown"
          ? "Eksik POS, katılım veya ilerleme bilgisi nedeniyle kesin hüküm verilemiyor."
          : "Bu kart için seçili mağazada uygulanabilir insan onaylı kampanya bulunamadı.";
  return [anaMetin, ...karar.blockingReasons].join(" ");
}

/**
 * NE:       Tek V3 motor sonucunu mevcut KararSatiri görsel sözleşmesine kayıpsız taşır.
 * NEDEN:    Potential/unknown/ineligible sonuçlara kesin TL dili verilmesi kullanıcıyı kasada yanıltır.
 * NASIL:    Her güven durumuna ayrı etiket ve açıklama verir; hesap adımlarını, kritik koşulları,
 *           engelleri ve resmî kaynak URL'sini korur; yalnız guaranteed sonucu net kazanç sayar.
 * YAN ETKİ: Görsel bileşenler mevcut KararSatiri tipini tüketmeye devam eder.
 */
export function v3KararSatirinaDonustur(
  karar: DecisionResultV3,
  kampanya: CampaignV3 | null,
  kartUrunu: CardProduct,
  katalog: V3EslemeKatalogu
): KararSatiri {
  const program = katalog.programs.find((aday) => aday.id === kartUrunu.programId);
  const issuer = katalog.issuers.find((aday) => aday.id === kartUrunu.issuerId);
  const etiket = etiketler(karar);
  const kaynakTazeligi = tazelikEtiketi(karar);
  const taksit = kampanya?.benefit.type === "installment";
  const sadeKosullar = [...karar.criticalConditions, ...karar.blockingReasons];

  return {
    program: program?.name ?? kartUrunu.programId,
    cardProductId: kartUrunu.id,
    cardProductName: kartUrunu.productName,
    cardProgramId: kartUrunu.programId,
    issuerName: issuer?.aliases[0] ?? issuer?.name,
    paymentNetwork: kartUrunu.paymentNetworks[0],
    guvenDurumu: guvenDurumu(karar.state),
    tip: taksit ? "taksit" : "kampanya",
    kazancTL: karar.state === "guaranteed" ? karar.guaranteedBenefitTL : 0,
    etiket: etiket.etiket,
    etiketAlt: kaynakTazeligi ? `${etiket.etiketAlt} · ${kaynakTazeligi}` : etiket.etiketAlt,
    baslik:
      kampanya?.title ?? `${kartUrunu.productName} için onaylı kampanya eşleşmedi`,
    aciklama: aciklamaMetni(karar),
    sadeKosullar,
    katilimGerekli: kampanya ? katilimKuraliVarMi(kampanya.rule) : false,
    kaynakUrl: karar.sourceUrls[0] ?? null,
    digerFirsat: 0,
    hesap: karar.calculationSteps,
  };
}

/**
 * NE:       V3 motor sırasını koruyup sonradan üretilen vade satırlarını gerçek avantajına göre dizer.
 * NEDEN:    Motorun alfabetik ineligible kuyruğu dönüşümden sonra 11 günlük vadeyi 40 günün önünde veya
 *           kesim günü olmayan boş satırı gerçek vadenin üstünde bırakabilir; büyük cevap ilk satırı kullanır.
 * NASIL:    Uygulanabilir kampanya/taksit satırlarının motor sırasını korur; ardından bilgi amaçlı vadeleri
 *           gün sayısı azalan biçimde, en sona da kesim günü olmayan ineligible satırları koyar.
 * YAN ETKİ: Yeni bir dizi üretir; satır nesnelerini ve motorun uygulanabilir kampanya sırasını değiştirmez.
 */
function v3DonusumSonrasiSirala(satirlar: KararSatiri[]): KararSatiri[] {
  const grup = (satir: KararSatiri): number => {
    if (satir.guvenDurumu === "informational" && satir.tip === "vade") return 1;
    if (satir.guvenDurumu === "ineligible") return 2;
    return 0;
  };
  return satirlar
    .map((satir, motorSirasi) => ({ satir, motorSirasi }))
    .sort((a, b) => {
      const grupFarki = grup(a.satir) - grup(b.satir);
      if (grupFarki !== 0) return grupFarki;
      if (grup(a.satir) === 1) {
        const aGun = Number.parseInt(a.satir.etiket, 10) || 0;
        const bGun = Number.parseInt(b.satir.etiket, 10) || 0;
        if (bGun !== aGun) return bGun - aGun;
      }
      return a.motorSirasi - b.motorSirasi;
    })
    .map(({ satir }) => satir);
}

/**
 * NE:       Hazır V3 kampanya kümesini mobil seçim bağlamında sıralayıp UI satırlarına çevirir.
 * NEDEN:    App katmanında motor girdisi veya güven dili tekrar kurulursa legacy/V3 davranışları ayrışabilir.
 * NASIL:    Güvenli girdi kapısını, kartlariSirala'yı ve tek dönüşüm sözleşmesini ardışık çalıştırır.
 * YAN ETKİ: Gölge kapı açılamazsa satır üretmez; çağıran mevcut legacy sonucunu aynen kullanabilir.
 */
export function v3MobilKarariniOlustur(
  kampanyalar: CampaignV3[],
  katalog: V3EslemeKatalogu,
  baglam: V3MobilKararBaglami
): V3MobilKararSonucu {
  const girdi = v3MobilKararGirdisiniOlustur(katalog, baglam);
  if (girdi.state === "legacy_fallback") {
    return { state: "legacy_fallback", rows: null, reason: girdi.reason };
  }

  const kampanyaHaritasi = new Map(kampanyalar.map((kampanya) => [kampanya.id, kampanya]));
  const urunHaritasi = new Map(girdi.input.cardProducts.map((urun) => [urun.id, urun]));
  const rows = v3DonusumSonrasiSirala(kartlariSirala(kampanyalar, girdi.input).map((karar) => {
    const satir = v3KararSatirinaDonustur(
      karar,
      karar.campaignId ? kampanyaHaritasi.get(karar.campaignId) ?? null : null,
      urunHaritasi.get(karar.cardProductId)!,
      katalog
    );
    const cuzdanKarti = girdi.input.wallet.find((aday) => aday.cardProductId === karar.cardProductId);
    if (karar.state !== "ineligible" || karar.campaignId !== null || cuzdanKarti?.statementDay == null) {
      return satir;
    }
    const gun = ertelemeGunu(
      cuzdanKarti.statementDay,
      turkiyeTakvimTarihi(new Date(girdi.input.evaluatedAt))
    );
    return {
      ...satir,
      guvenDurumu: "informational",
      tip: "vade",
      kazancTL: 0,
      etiket: `${gun} gün`,
      etiketAlt: "ödeme ertelenir",
      baslik: "Onaylı V3 kampanyası yok — vade avantajı",
      aciklama: `Ekstre kesimi ayın ${cuzdanKarti.statementDay}'i: bugünkü harcaman yaklaşık ${gun} gün sonra ödenir.`,
      sadeKosullar: [],
      katilimGerekli: false,
      kaynakUrl: null,
      hesap: [
        `Kesim günü ${cuzdanKarti.statementDay} → kesime kalan gün + son ödeme payı = ${gun} gün erteleme`,
      ],
    } satisfies KararSatiri;
  }));
  return { state: "ready", rows, merchantId: girdi.merchantId };
}
