/**
 * NE:       Kazanç kilometre taşı töreni — kullanıcının GERÇEK toplam kazancı yuvarlak bir eşiği
 *           (100/250/500/1.000/2.500/5.000₺) aştığında ya da kişisel rekor kırıldığında tek-atış sakin tören.
 * NEDEN:    "Gerçekten para biriktiriyorum" duygusunu ANIN içinde yaşat (bir sonraki mührü kovala → habit).
 *           Asil altın damga, konfeti değil (Mehmet abi'nin sevdiği tören; cıvık değil). Sürpriz #3.
 * NASIL:    Tam ekran overlay; altın hale + kutlama madalyonu Animated.spring (TEMA.yay.canli) + yeni toplam
 *           useSayac ile 0'dan koşar + TutarYazi altın. dokunsalBasari tören haptiği. Tek atış, LOOP YOK.
 *           ~2 sn sonra otomatik kapanır; dokunuşla da kapanır. reduce-motion → animasyonsuz belir.
 * YAN ETKİ: Para BİREBİR (gerçek toplam). Ağ/sunucu yok. Backdrop kısa süre örter, otomatik çekilir.
 */
import { useEffect, useRef } from "react";
import { Animated, Image, Pressable, StyleSheet, Text } from "react-native";
import { useSayac } from "../motor/useSayac";
import { dokunsalBasari } from "../dokunsal";
import { TEMA } from "../tema";
import { TutarYazi } from "./TutarYazi";
import { AltinHale } from "./AltinHale";

const KUTLAMA = require("../../assets/durumlar/kutlama.webp");

export function KilometreToreni({
  tip,
  toplam,
  deger,
  hareketAzalt = false,
  onKapat,
}: {
  /** rekor = kişisel en yüksek tek kazanç kırıldı · esik = toplam yuvarlak eşiği aştı */
  tip: "rekor" | "esik";
  /** Yeni GERÇEK toplam kazanç (₺) — count-up hedefi */
  toplam: number;
  /** esik: aşılan eşik (₺) · rekor: yeni rekor kazanç (₺) */
  deger: number;
  hareketAzalt?: boolean;
  onKapat: () => void;
}) {
  const g = useRef(new Animated.Value(hareketAzalt ? 1 : 0)).current;
  const sayac = useSayac(toplam, { hareketAzalt, sureMs: TEMA.yay.sayacMs });

  useEffect(() => {
    dokunsalBasari();
    let anim: Animated.CompositeAnimation | null = null;
    if (!hareketAzalt) {
      anim = Animated.spring(g, { toValue: 1, useNativeDriver: true, ...TEMA.yay.canli });
      anim.start();
    }
    const t = setTimeout(onKapat, 2000);
    return () => {
      anim?.stop();
      clearTimeout(t);
    };
  }, [g, hareketAzalt, onKapat]);

  const baslik =
    tip === "rekor"
      ? "Kişisel rekorun! 🏅"
      : `Kazancın ${deger.toLocaleString("tr-TR")}₺'yi geçti`;
  const alt = tip === "rekor" ? "Bugüne kadarki en büyük kazancın" : "Toplam kazancın büyüyor";

  return (
    <Pressable
      style={s.backdrop}
      onPress={onKapat}
      accessibilityRole="button"
      accessibilityLabel={`${baslik}. Kapatmak için dokun`}
    >
      <Animated.View
        style={[
          s.kart,
          { opacity: g, transform: [{ scale: g.interpolate({ inputRange: [0, 1], outputRange: [0.7, 1] }) }] },
        ]}
      >
        <AltinHale yaricap={120} />
        <Image source={KUTLAMA} style={s.madalyon} resizeMode="cover" />
        <Text style={s.baslik}>{baslik}</Text>
        <TutarYazi metin={`${sayac.toLocaleString("tr-TR")} ₺`} boy={44} renk={TEMA.para.kazanc} />
        <Text style={s.alt}>{alt}</Text>
      </Animated.View>
    </Pressable>
  );
}

const s = StyleSheet.create({
  backdrop: {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: "rgba(8,9,12,0.82)",
    alignItems: "center",
    justifyContent: "center",
    zIndex: 50,
    paddingHorizontal: TEMA.bosluk.xl,
  },
  kart: { alignItems: "center", paddingHorizontal: TEMA.bosluk.xl, paddingVertical: TEMA.bosluk.xxl },
  madalyon: {
    width: 96,
    height: 96,
    borderRadius: 48,
    overflow: "hidden",
    borderWidth: 1.5,
    borderColor: TEMA.renk.altinKenar,
    marginBottom: TEMA.bosluk.l,
  },
  baslik: { color: TEMA.renk.yazi, fontSize: 16, fontWeight: "700", textAlign: "center", marginBottom: TEMA.bosluk.s },
  alt: { color: TEMA.renk.yaziSoluk, fontSize: 12.5, marginTop: 6, textAlign: "center" },
});
