/**
 * NE:       Premium boş-durum kartı — bespoke amblem + başlık + açıklama + opsiyonel CTA.
 * NEDEN:    Görsel devrim: boş ekran bile kaliteli hissettirmeli; jenerik/kaba boşluk YASAK.
 *           Kimlik rengi (altın) amblemde işler; yüzey aydınlanan katman sistemine bağlı.
 * NASIL:    kat1 yüzeyli kart + kat2 dairesel amblem (react-native-svg bespoke glyph, altın kontur);
 *           amblem tipi prop ile (cuzdan/firsat/arama). CTA opsiyonel ve altın; 48pt dokunma hedefi.
 * YAN ETKİ: Yok — saf sunum; onCta yalnız üst bileşenin verdiği işlevi çağırır.
 */
import { Image, StyleSheet, Text, View } from "react-native";
import Svg, { Path, Rect } from "react-native-svg";
import { TEMA } from "../tema";
import { Basilabilir } from "./Basilabilir";
import { CamYuzey } from "./CamYuzey";

type Amblem = "cuzdan" | "firsat" | "arama" | "karne";

// Grup B durum görselleri (3D render, ChatGPT). Varsa amblem yerine premium görsel; yoksa SVG glif fallback.
const DURUM_GORSEL: Partial<Record<Amblem, number>> = {
  cuzdan: require("../../assets/durumlar/cuzdan-bos.webp"),
  karne: require("../../assets/durumlar/karne-bos.webp"),
  firsat: require("../../assets/durumlar/sonuc-yok.webp"),
  arama: require("../../assets/durumlar/sonuc-yok.webp"),
};

function Glif({ tur }: { tur: Amblem }) {
  const c = TEMA.renk.altinAcik;
  if (tur === "karne") {
    return (
      <Svg width={34} height={34} viewBox="0 0 24 24" fill="none">
        <Path d="M4 20h16" stroke={c} strokeWidth="1.6" strokeLinecap="round" />
        <Path d="M7 20v-5M12 20V8M17 20v-9" stroke={c} strokeWidth="1.6" strokeLinecap="round" />
      </Svg>
    );
  }
  if (tur === "cuzdan") {
    return (
      <Svg width={34} height={34} viewBox="0 0 24 24" fill="none">
        <Rect x="3" y="6" width="18" height="12" rx="2.5" stroke={c} strokeWidth="1.6" />
        <Path d="M3 10h18" stroke={c} strokeWidth="1.6" />
        <Path d="M17 3l.66 1.4L19.2 4.6l-1.1 1.05.28 1.55L17 6.46l-1.36.74.28-1.55L14.8 4.6l1.54-.2z" fill={c} />
      </Svg>
    );
  }
  if (tur === "firsat") {
    return (
      <Svg width={34} height={34} viewBox="0 0 24 24" fill="none">
        <Path d="M4 4h7l9 9-7 7-9-9V4z" stroke={c} strokeWidth="1.6" strokeLinejoin="round" />
        <Path d="M8 8h.01" stroke={c} strokeWidth="2.6" strokeLinecap="round" />
      </Svg>
    );
  }
  return (
    <Svg width={34} height={34} viewBox="0 0 24 24" fill="none">
      <Path d="M11 4a7 7 0 105.2 11.7L20 19.5" stroke={c} strokeWidth="1.6" strokeLinecap="round" />
    </Svg>
  );
}

export function BosDurum({
  amblem,
  baslik,
  yazi,
  ctaEtiket,
  onCta,
}: {
  amblem: Amblem;
  baslik: string;
  yazi: string;
  ctaEtiket?: string;
  onCta?: () => void;
}) {
  const gorsel = DURUM_GORSEL[amblem];
  return (
    <View style={s.kart}>
      <CamYuzey yaricap={TEMA.yaricap.buyuk} />
      {gorsel != null ? (
        <View style={s.gorselSar}>
          <Image source={gorsel} style={s.gorsel} resizeMode="cover" />
        </View>
      ) : (
        <View style={s.amblem}>
          <Glif tur={amblem} />
        </View>
      )}
      <Text style={s.baslik}>{baslik}</Text>
      <Text style={s.yazi}>{yazi}</Text>
      {ctaEtiket && onCta ? (
        <Basilabilir
          onPress={onCta}
          stil={s.cta}
          accessibilityRole="button"
          accessibilityLabel={ctaEtiket}
        >
          <Text style={s.ctaYazi}>{ctaEtiket}</Text>
        </Basilabilir>
      ) : null}
    </View>
  );
}

const s = StyleSheet.create({
  kart: {
    borderRadius: TEMA.yaricap.buyuk,
    backgroundColor: TEMA.yuzey.kat1.zemin,
    borderWidth: 1,
    borderColor: TEMA.yuzey.kat1.kenar,
    padding: TEMA.bosluk.xl,
    alignItems: "center",
    gap: TEMA.bosluk.m,
    marginTop: TEMA.bosluk.xxl,
    overflow: "hidden",
  },
  amblem: {
    width: 72,
    height: 72,
    borderRadius: 36,
    backgroundColor: TEMA.yuzey.kat2.zemin,
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    alignItems: "center",
    justifyContent: "center",
  },
  gorselSar: {
    width: 124,
    height: 124,
    borderRadius: 62,
    overflow: "hidden",
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
  },
  gorsel: { width: "100%", height: "100%" },
  baslik: { color: TEMA.renk.yazi, fontSize: 17, fontWeight: "700", textAlign: "center" },
  yazi: { color: TEMA.renk.yaziSoluk, fontSize: 13, lineHeight: 19, textAlign: "center" },
  cta: {
    minHeight: 48,
    borderRadius: TEMA.yaricap.hap,
    backgroundColor: TEMA.renk.altin,
    paddingHorizontal: TEMA.bosluk.xl,
    paddingVertical: TEMA.bosluk.m,
    justifyContent: "center",
    marginTop: 4,
  },
  ctaYazi: { color: TEMA.renk.zeminKoyu, fontWeight: "800", fontSize: 14 },
});
