/**
 * NE:       Kart-ekleme akışının 2. sahnesi — seçilen bankanın kartları DESTE olarak + seçim töreni.
 * NEDEN:    Mehmet abi (2026-07-21): banka seçilince o bankanın kartları gerçek görünümüyle gelsin,
 *           dokununca cüzdana otursun (sinematik, "sekmeli seçim" değil). Araştırma: liste değil deste,
 *           sıralı yay girişi + seçilince tek altın gleam (mikro-tören).
 * NASIL:    kartUrunleriniFiltrele(KATALOG,"",issuerId) → tek sütun gerçek kart yüzleri (KrediKarti,
 *           ürün-bazlı kartGorunumu). Sıralı yay girişi (useGiris). Dokun → seç/kaldır + haptik;
 *           yeni seçilen kartta BİR kez altın süpürme (BuyukCevap parla deseni) + kalıcı altın kontur + ✓.
 *           Genişlik kabın ölçüsünden (taşma yok). Reduce Motion'da gleam/giriş anında oturur.
 * YAN ETKİ: Yalnız üst bileşenin seçim listesini değiştirir (onSeciliDegistir); ağ/dosya yok.
 */
import { useEffect, useRef, useState } from "react";
import { Animated, Easing, StyleSheet, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import katalogVerisi from "../veri/v3-esleme-katalogu.json";
import type { KartUrunuEslemeKaydi, V3EslemeKatalogu } from "../motor/v3Gecis";
import { kartUrunleriniFiltrele, urunProgramAdi } from "../motor/kartKatalogu";
import { kartGorunumu } from "../marka/markalar";
import { useGiris } from "../hareket";
import { dokunsalHafif, dokunsalSecim } from "../dokunsal";
import { TEMA } from "../tema";
import { KrediKarti } from "./KrediKarti";
import { Basilabilir } from "./Basilabilir";

const KATALOG = katalogVerisi as unknown as V3EslemeKatalogu;
const ISO = 54 / 85.6;

interface Props {
  issuerId: string;
  seciliIds: string[];
  onSeciliDegistir: (ids: string[]) => void;
  onGeri: () => void;
  hareketAzalt?: boolean;
}

function DesteKarti({
  urun,
  secili,
  sira,
  en,
  onSecim,
  hareketAzalt,
}: {
  urun: KartUrunuEslemeKaydi;
  secili: boolean;
  sira: number;
  en: number;
  onSecim: (id: string) => void;
  hareketAzalt: boolean;
}) {
  const giris = useGiris(sira, hareketAzalt);
  const gorunum = kartGorunumu(urun.programId, urun.id);
  const issuer = KATALOG.issuers.find((i) => i.id === urun.issuerId);
  const boy = Math.round(en * ISO);

  // Mikro-tören: kart YENİ seçildiğinde bir kez altın süpürme geçer (BuyukCevap parla deseni).
  const parla = useRef(new Animated.Value(0)).current;
  const onceki = useRef(secili);
  useEffect(() => {
    if (secili && !onceki.current && !hareketAzalt) {
      parla.setValue(0);
      const anim = Animated.timing(parla, {
        toValue: 1,
        duration: 760,
        easing: Easing.inOut(Easing.sin),
        useNativeDriver: true,
      });
      anim.start();
      onceki.current = secili;
      return () => anim.stop(); // gleam sırasında "← Bankalar" ile unmount olursa durdur (D1)
    }
    onceki.current = secili;
  }, [secili, hareketAzalt, parla]);

  return (
    <Animated.View style={[s.kartSar, giris]}>
      <Basilabilir
        onPress={() => {
          dokunsalHafif();
          onSecim(urun.id);
        }}
        hareketAzalt={hareketAzalt}
        accessibilityRole="button"
        accessibilityState={{ selected: secili }}
        accessibilityLabel={`${urun.name}, ${issuer?.aliases[0] ?? issuer?.name}, ${secili ? "cüzdanda, kaldırmak için dokun" : "cüzdana eklemek için dokun"}`}
      >
        <View style={{ width: en, height: boy }}>
          <KrediKarti
            program={urunProgramAdi(KATALOG, urun)}
            urunAdi={urun.name}
            markaAdi={gorunum.markaAdi}
            odemeAgi={urun.paymentNetworks[0]}
            kartGradyan={gorunum.kartGradyan}
            kartYaziKoyu={gorunum.kartYaziKoyu}
            imza={gorunum.imza}
            altEtiket={issuer?.aliases[0] ?? issuer?.name}
            en={en}
            soluk={!secili}
            hareketAzalt={hareketAzalt}
          />
          {secili && (
            <>
              <View
                style={[StyleSheet.absoluteFill, s.cerceve, { borderRadius: Math.round(en * 0.055) }]}
                pointerEvents="none"
              />
              {!hareketAzalt && (
                <Animated.View
                  pointerEvents="none"
                  style={[
                    StyleSheet.absoluteFill,
                    {
                      opacity: parla.interpolate({ inputRange: [0, 0.12, 0.88, 1], outputRange: [0, 1, 1, 0] }),
                      transform: [
                        { translateX: parla.interpolate({ inputRange: [0, 1], outputRange: [-en, en] }) },
                        { rotate: "18deg" },
                      ],
                    },
                  ]}
                >
                  <LinearGradient
                    colors={["transparent", "rgba(240,217,152,0.4)", "transparent"]}
                    start={{ x: 0, y: 0.5 }}
                    end={{ x: 1, y: 0.5 }}
                    style={s.gleam}
                  />
                </Animated.View>
              )}
              <View style={s.check}>
                <Text style={s.checkYazi}>✓</Text>
              </View>
            </>
          )}
        </View>
        <Text style={[s.durum, secili && s.durumSecili]}>
          {secili ? "✓ Cüzdanda" : "Eklemek için dokun"}
        </Text>
      </Basilabilir>
    </Animated.View>
  );
}

export function KartDestesi({ issuerId, seciliIds, onSeciliDegistir, onGeri, hareketAzalt = false }: Props) {
  const [genislik, setGenislik] = useState(0);
  const seciliSeti = new Set(seciliIds);
  const kartlar = kartUrunleriniFiltrele(KATALOG, "", issuerId);
  const issuer = KATALOG.issuers.find((i) => i.id === issuerId);
  const bankaAd = issuer?.aliases[0] ?? issuer?.name ?? "Banka";
  const en = genislik > 0 ? genislik : 300;

  function secimDegistir(productId: string) {
    onSeciliDegistir(
      seciliSeti.has(productId)
        ? seciliIds.filter((id) => id !== productId)
        : [...seciliIds, productId]
    );
  }

  const seciliSayi = kartlar.filter((k) => seciliSeti.has(k.id)).length;

  return (
    <View style={s.kap} onLayout={(e) => setGenislik(e.nativeEvent.layout.width)}>
      <Basilabilir
        onPress={() => {
          dokunsalSecim();
          onGeri();
        }}
        stil={s.geri}
        hareketAzalt={hareketAzalt}
        accessibilityRole="button"
        accessibilityLabel="Bankalara dön"
      >
        <Text style={s.geriYazi}>← Bankalar</Text>
      </Basilabilir>

      <Text style={s.baslik}>{bankaAd} kartların</Text>
      <Text style={s.altBaslik}>
        {seciliSayi > 0
          ? `${seciliSayi} kart cüzdanında. Eklemek için karta dokun.`
          : "Sende olan kart(lar)a dokun, cüzdanına otursun."}
      </Text>

      <View style={s.deste}>
        {kartlar.map((urun, i) => (
          <DesteKarti
            key={urun.id}
            urun={urun}
            secili={seciliSeti.has(urun.id)}
            sira={i}
            en={en}
            onSecim={secimDegistir}
            hareketAzalt={hareketAzalt}
          />
        ))}
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  kap: { gap: TEMA.bosluk.m },
  geri: { alignSelf: "flex-start", paddingVertical: 6, paddingHorizontal: 2, minHeight: 40, justifyContent: "center" },
  geriYazi: { color: TEMA.renk.altinAcik, fontSize: 14, fontWeight: "700" },
  baslik: { color: TEMA.renk.yazi, fontSize: 20, fontWeight: "800" },
  altBaslik: { color: TEMA.renk.yaziSoluk, fontSize: 13, lineHeight: 18 },
  deste: { gap: TEMA.bosluk.l, marginTop: TEMA.bosluk.s },
  kartSar: { gap: 6, alignItems: "center" },
  cerceve: { borderWidth: 2, borderColor: TEMA.renk.altin },
  gleam: { flex: 1 },
  check: {
    position: "absolute",
    top: -8,
    right: -8,
    minWidth: 26,
    height: 26,
    paddingHorizontal: 6,
    borderRadius: 13,
    backgroundColor: TEMA.renk.altin,
    alignItems: "center",
    justifyContent: "center",
    shadowColor: "#000",
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.4,
    shadowRadius: 4,
    elevation: 4,
  },
  checkYazi: { color: "#1a1206", fontSize: 14, fontWeight: "900" },
  durum: { color: TEMA.renk.yaziSoluk, fontSize: 12, fontWeight: "700" },
  durumSecili: { color: TEMA.renk.altinAcik },
});
