/**
 * NE:       Kullanıcı ve en yakın mağaza koordinatlarından gerçek harita kapsamını ve anahtarsız dış harita URL'sini üretir.
 * NEDEN:    Native ve web aynı gerçek noktaları göstermeli; bozuk koordinat, rastgele ölçek veya platforma göre
 *           farklı mağaza sırası kullanıcıya yanlış mevki anlatmamalıdır.
 * NASIL:    Geçerli kullanıcıyı merkeze alır, en fazla altı geçerli mağazayı yakınlık sırasıyla numaralar, tüm
 *           noktaları taşımayan güvenli bir enlem/boylam bölgesi hesaplar ve dış Google Maps URL'sini ayrı üretir.
 * YAN ETKİ: Saf hesap katmanıdır; GPS, ağ ve dosya erişimi yoktur. URL açılırsa koordinat Google Haritalar'a gider.
 */
import { koordinatGecerliMi, type YakinMagaza } from "./konumHesap";

export type KullaniciKonumu = { lat: number; lon: number };

export type GercekHaritaNoktasi = {
  sira: number;
  marka: string;
  subeAd: string;
  mesafeM: number;
  lat: number;
  lon: number;
};

export type GercekHaritaKapsami = {
  merkez: KullaniciKonumu;
  latitudeDelta: number;
  longitudeDelta: number;
  noktalar: GercekHaritaNoktasi[];
};

const ASGARI_ENLEM_FARKI = 0.018;
const ASGARI_BOYLAM_FARKI = 0.018;
const KAPSAM_CARPANI = 1.55;

export function gercekHaritaKapsamiOlustur(
  konum: KullaniciKonumu | null,
  yakinlar: readonly YakinMagaza[],
  adet = 6
): GercekHaritaKapsami | null {
  const sinir = Number.isFinite(adet) ? Math.max(0, Math.min(6, Math.floor(adet))) : 0;
  if (!konum || !koordinatGecerliMi(konum.lat, konum.lon) || !Array.isArray(yakinlar)) return null;

  const noktalar = yakinlar
    .filter(
      (magaza) =>
        magaza &&
        koordinatGecerliMi(magaza.lat, magaza.lon) &&
        Number.isFinite(magaza.mesafeM) &&
        magaza.mesafeM >= 0
    )
    .slice(0, sinir)
    .map((magaza, indeks) => ({
      sira: indeks + 1,
      marka: magaza.marka,
      subeAd: magaza.subeAd,
      mesafeM: magaza.mesafeM,
      lat: magaza.lat,
      lon: magaza.lon,
    }));

  const enlemler = [konum.lat, ...noktalar.map((nokta) => nokta.lat)];
  const boylamlar = [konum.lon, ...noktalar.map((nokta) => nokta.lon)];
  const enKucukEnlem = Math.min(...enlemler);
  const enBuyukEnlem = Math.max(...enlemler);
  const enKucukBoylam = Math.min(...boylamlar);
  const enBuyukBoylam = Math.max(...boylamlar);
  const latitudeDelta = Math.max(ASGARI_ENLEM_FARKI, (enBuyukEnlem - enKucukEnlem) * KAPSAM_CARPANI);
  const longitudeDelta = Math.max(
    ASGARI_BOYLAM_FARKI,
    (enBuyukBoylam - enKucukBoylam) * KAPSAM_CARPANI,
    latitudeDelta * 0.85
  );

  return {
    merkez: {
      lat: (enKucukEnlem + enBuyukEnlem) / 2,
      lon: (enKucukBoylam + enBuyukBoylam) / 2,
    },
    latitudeDelta: Math.min(90, latitudeDelta),
    longitudeDelta: Math.min(180, longitudeDelta),
    noktalar,
  };
}

export function gercekHaritaURL(konum: KullaniciKonumu | null): string | null {
  if (!konum || !koordinatGecerliMi(konum.lat, konum.lon)) return null;

  return (
    "https://www.google.com/maps/@?api=1&map_action=map" +
    `&center=${konum.lat},${konum.lon}&zoom=15&basemap=roadmap`
  );
}
