/**
 * NE: Android donanım geri tuşunun uygulama içindeki tek ve öngörülebilir öncelik sırasını belirler.
 * NEDEN: Kullanıcı açık modal, başka sekme veya yarım karar adımındayken uygulamadan ansızın çıkmamalıdır.
 * NASIL: SOS → Güven → ana karar sekmesi → karar seçimini temizleme sırasıyla ilk uygulanabilir eylemi döndürür.
 * YAN ETKİ: Yoktur; state değiştirmez ve Android dışı platformlara dokunmaz.
 */
export type AndroidGeriEylemi =
  | "acil-kapat"
  | "guven-kapat"
  | "karar-sekmesine-don"
  | "karar-secimini-temizle"
  | "sisteme-birak";

export function androidGeriEylemi(
  acilAcik: boolean,
  guvenAcik: boolean,
  sekme: string,
  kararSecimiVar: boolean,
): AndroidGeriEylemi {
  if (acilAcik) return "acil-kapat";
  if (guvenAcik) return "guven-kapat";
  if (sekme !== "karar") return "karar-sekmesine-don";
  if (kararSecimiVar) return "karar-secimini-temizle";
  return "sisteme-birak";
}
