/**
 * NE:       Basilabilir — dokunuşta yaylanan ve KartAkıl'ın teknik köşe izini taşıyan ortak etkileşim sarmalı.
 * NEDEN:    Görsel Devrim 2 "dokunuş hissi": 12 dosyadaki ad-hoc `pressed && opacity/scale` yerine
 *           TEK yay-fizik dili. Parmak değince öğe hafif küçülüp yaylanır (asil, abartısız) → arayüz "yaşar".
 * NASIL:    Animated.createAnimatedComponent(Pressable) tek sefer; useBasili scale'ini doğrudan style'a
 *           ekler. Her gerçek hedefe yerleşimi bozmayan iki mikro sinyal işareti bindirir; vurgu rengi
 *           çağıran tarafından değiştirilebilir, yalnız görünmez/backdrop hedeflerinde kapatılabilir.
 * YAN ETKİ: Saf sunum; useNativeDriver transform. hareketAzalt=true'da scale sabit 1. Eski hedef boyutları,
 *           onPressIn/onPressOut zinciri ve erişilebilirlik propları korunur.
 */
import { useMemo } from "react";
import {
  Animated,
  Pressable,
  StyleSheet,
  View,
  type PressableProps,
  type StyleProp,
  type ViewStyle,
  type GestureResponderEvent,
} from "react-native";
import { useBasili } from "../hareket";

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

type Props = Omit<PressableProps, "style" | "children"> & {
  stil?: StyleProp<ViewStyle>;
  hareketAzalt?: boolean;
  teknolojiRenk?: string;
  teknolojiIz?: boolean;
  children?: React.ReactNode;
};

export function Basilabilir({
  stil,
  hareketAzalt,
  teknolojiRenk = "rgba(255,255,255,0.22)",
  teknolojiIz = true,
  onPressIn,
  onPressOut,
  children,
  ...p
}: Props) {
  const { olcek, bas, birak } = useBasili(hareketAzalt);
  const animStil = useMemo(
    () => [stil, { transform: [{ scale: olcek }] }],
    [stil, olcek],
  );
  return (
    <AnimatedPressable
      {...p}
      onPressIn={(e: GestureResponderEvent) => {
        bas();
        onPressIn?.(e);
      }}
      onPressOut={(e: GestureResponderEvent) => {
        birak();
        onPressOut?.(e);
      }}
      style={animStil}
    >
      {children}
      {teknolojiIz ? (
        <>
          <View pointerEvents="none" style={[s.ustKose, { borderColor: teknolojiRenk }]} />
          <View pointerEvents="none" style={[s.altIz, { backgroundColor: teknolojiRenk }]} />
        </>
      ) : null}
    </AnimatedPressable>
  );
}

const s = StyleSheet.create({
  ustKose: {
    position: "absolute",
    top: 4,
    right: 5,
    width: 11,
    height: 6,
    borderTopWidth: 1,
    borderRightWidth: 1,
    borderTopRightRadius: 3,
  },
  altIz: {
    position: "absolute",
    bottom: 4,
    left: 6,
    width: 8,
    height: 1,
    borderRadius: 1,
    opacity: 0.55,
  },
});
